window.__D("text/zohar/c038",{"p":[[9520012603,"<p>מִסִּטְרָא דִּימִינָא, אִתְקְרִיאַת אֶבֶן. וְכַמָּה אֲבָנִין מְפוּלָּמִין יַקִּירִין אִשְׁתְּכָחוּ מִנָהּ, דְּמִנַּיְיהוּ מַיָּא דְּאוֹרַיְיתָא נָפְקִין. וּבְגִינֵיהוֹן אִתְּמַר, אָמַר רִבִּי עֲקִיבָא לְתַלְמִידָיו כְּשֶׁתַּגִיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר אַל תֹּאמְרוּ מַיִם מַיִם שֶׁמָּא תִּסְתַּכְּנוּ בְּנַפְשְׁכֶם. לָא תֵּימְרוּן דְּאִינּוּן מַיִם, מַיִם מַמָּשׁ. מִשּׁוּם (תהילים ק״א:ז׳) דּוֹבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. דְּאִלֵּין מַיִם, דָּא אוֹרַיְיתָא, דְּאִתְּמַר בָּהּ (משלי ו׳:כ״ג) וְתוֹרָה אוֹר. וּבְגִין דְּהַאי נְהוֹרָא נְבִיעַ בְּמַבּוּעָא דְּמַיָּא, (ישעיהו נ״ח:י״א) אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו, אִתְקְרֵי מַיִם.</p>\n<p>וּמִסִּטְרָא דִּשְׂמָאלָא, הַאי אֶבֶן דְּאִיהִי י', אִתְקְרֵי גַּחֶלֶת. וּמִתַּמָּן עֶשֶׂר סְפִירָן כְּשַׁלְהֶבֶת קְשׁוּרָה בַּגַחֶלֶת. וְאִית לָהּ ד' גַּוְונִין, (ועשרה) אִינּוּן, יוֹד הֵא וָאו הֵא. יְדוָֹ\"ד. וְאִיהִי יַד הַגְּדוֹלָה בִּימִינָא, יַד הַחֲזָקָה בִּשְׂמָאלָא, עַמוּדָא דְּאֶמְצָעִיתָא, מִתַּמָּן אִיהִי יַד רָמָה, כָּלִיל מִּמ\"ב גַּוְונִין.</p>\n<p>וּבְגִין דְּאִיהִי מִסִּטְרָא דִּימִינָא אֶבֶן, וּמִסִּטְרָא דִּשְׂמָאלָא גַּחֶלֶת, בָּהּ נָטִיל קוּדְשָׁא בְּרִיךְ הוּא נוּקְמָא, מִיִשְׁמָעֵאל וְאֱדוֹם, דְּאִינּוּן אִישִּׁין נוּכְרָאִין, וּמַיִם הַזֵּדוֹנִים. וּמְמָנָן דִּלְהוֹן סָמָאֵל וְנָחָשׁ. סָמָאֵל אֶשָּׁא דְּגֵיהִנָּם, מְמוּנֶה עַל אוּמָה דְּעֵשָׂו. נָחָשׁ מְמוּנֶה עַל אוּמָה דְּיִשְׁמָעֵאל, וְאִיהוּ רָהָב דִּמְמָנָא עַל מַיָּא.</p>\n<p>בִּימִינָא דְּאַבְרָהָם, דְּדַרְגֵּיהּ חֶסֶד, נָטִיל נוּקְמָא מִיִּשְׁמָעֵאל, וּמְמָנָא דִּילֵיהּ. וּבִשְׂמָאלָא דְּיִצְחָק, דְּדַרְגֵיהּ פַּחַד, נָטִיל נוּקְמָא מֵעֵשָׂו, וּמְמָנָא דִּילֵיהּ. בִּתְרֵין מְשִׁיחִין, דְּאִינּוּן חַד מִימִינָא, מָשִׁיחַ בֶּן דָּוִד. וְחַד מִשְּׂמָאלָא, מָשִׁיחַ בֶּן יוֹסֵף. וּבְדַרְגָּא דְּיַעֲקֹב, דְּאִיהִי לָקֳבְלֵיהּ, בְּרָזָא (בראשית מח) דְּשִׂכֵּל אֶת יָדָיו (כי מנשה הבכור). אַרְיֵה לִשְׂמָאלָא. שׁוֹר לִימִינָא, דְּיִשְׁמָעֵאל. בְּגִין דִּיהוּדָה גָּלָה בְּעֵשָׂו, אִשְׁתְּכַח יְמִינָא דִקְדוּשָּׁה, עִם שְׂמָאלָא דְּעֵשָׂו. וּשְׂמָאלָא דִּקְדוּשָּׁה עִם יְמִינָא מִסְאֲבָא דְּיִשְׁמָעֵאל, (בראשית מ״ט:י׳) עַד כִּי יָבֹא שִׁילֹה, רַעְיָא מְהֵימָנָא, בְּדַרְגֵיהּ תִּפְאֶרֶת יִשְׂרָאֵל, נָטִיל נוּקְמָא מֵעֵרֶב רַב.</p>\n<p>בִּתְלַת דַּרְגִּין אִלֵּין, יִפְקוֹד (נ\"א יפקון) כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים, מִן גָּלוּתָא. וּבְהוֹן נָטִיל נוּקְמָא, מֵעֵשָׂו וְיִשְׁמָעֵאל וְעֵרֶב רַב. כְּגַוְונָא דְּעֵרֶב רַב מְעוּרָבִין בְּעֵשָׂו וְיִשְׁמָעֵאל, הָכִי יַעֲקֹב מְעוּרָב בְּאַבְרָהָם וְיִצְחָק, עֵרוּב דְּתַרְוַויְיהוּ. וְהָכִי מִתְעָרֵב שִׁילֹה, עִם מָשִׁיחַ בֶּן דָּוִד וּמָשִׁיחַ בֶּן יוֹסֵף, וִיהֵא שַׁלְשֶׁלֶת דְּתַרְוַויְיהוּ, כְּהַהוּא זִמְנָא דְּחָזָא בִּלְעָם בַּנְּבוּאָה דִּילֵיהּ, דְּהָכִי מִתְקַשְּׁרֵי תְּרֵין מְשִׁיחִין בְּרַעֲיָּא מְהֵימָנָא, בִּתְלַת אֲבָהָן, בְּגָלוּתָא בַּתְרָאָה.</p>\n<p>פָּתַח וְאָמַר, (במדבר כ״ג:כ״א) לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל יְיָ אֱלֹהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ. וְכֹלָּא לְקַיְּימָא קְרָא, (ישעיהו נ״ד:ז׳) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ. בְּהַהוּא זִמְנָא מְתַבְרִין קְלִיפּוֹת, דַּהֲווֹ מְסָחֲרִין לִשְׁכִינְתָּא. מִיַּד אִתְגַלְיָיא אַבְנָא חֲדָא מִתְּלַת אֲבָנִין, דְּאִינּוּן סְגוֹלְתָא. דְּעָלַיְיהוּ אִתְּמַר, (יחזקאל א׳:א׳) וַיְהִי בִּשְׁלֹשִׁים שָׁנָה, וְאִינּוּן ייְיָ בָּרְבִיעִי, אַבְנָא רְבִיעָאָה. <Nonei></i>בַּחֲמִשָּׁה לַחֹדֶשׁ, אַבְנָא חֲמִשָּׁאָה. לָקֳבְלַיְיהוּ, (שמואל א י״ז:מ׳) וַיִּקַּח דָּוִד חֲמִשָּׁה חַלּוּקֵי אֲבָנִים מִן הַנַּחַל. וְאִינּוּן לָקֳבְלַיְיהוּ חָמֵשׁ תֵּיבִין, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל יְדוָֹ\"ד אֱלֹהֵינוּ יְדוָֹ\"ד.</p>\n<p>(יחזקאל א׳:א׳) וַאֲנִי בְּתוֹךְ הַגּוֹלָה, דָּא שְׁכִינְתָּא, בָּהּ קוּדְשָׁא בְּרִיךְ הוּא אֶחָד. ו' בְּתוֹסֶפֶת וַאֲנִי, הוּא נָהָר, צַדִיק חַי עָלְמִין. (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, מַאי עֵדֶן. דָּא בִּינָה, נָהָר דְּנָפִיק מִנָּהּ, דָּא ו', בֶּן יָ\"הּ, דַּרְגָּא דְּרַעְיָא מְהֵימָנָא, וְרַעְיָא מְהֵימְנָא, נָפִיק מֵאִימָּא עִלָּאָה, וְאִתְפָּשַּׁט בְּשִׁית סְפִירָאן עַד צַדִּיק, וּמִנֵּיהּ אַשְׁקֵי לְגִנְתָּא (דעדן), דְּאִיהִי שְׁכִינְתָּא.</p>\n<p>מַאי כְּבָ\"ר. כ', כֶּתֶר. ב', בִּינָה. ר', רֵאשִׁית חָכְמָה. כֶּתֶר בִּימִינָא, חָכְמָה בִּשְׂמָאלָא, בִּינָה בְּאֶמְצָעִיתָא. רֶכֶב לְעֵילָּא לְעִלַּת הָעִלּוֹת. י' סְפִירָאן כֻּלְּהוּ, אִתְכָּלָלוּ בְּנָהָר, דְּאִיהוּ אִתְפְּשָׁט עַד צַדִּיק, דְּאִיהוּ כָּל, כָּלִיל כֹּלָּא. וּבְגִינֵיהּ אוֹקְמוּהָ, (דניאל ד׳:ט׳) אִילָנָא רַבָּא וְתַקִּיף, וּמָזוֹן לְכֹלָּא בֵּיהּ. מִנֵּיהּ תַּלְיָא כֹּלָּא. כַּד חָמָא שְׁכִינְתָּא מִגּוֹ קְלִיפִין, חָזָא עִמָּהּ עֶשֶׂר סְפִירָן. (ע\"כ רעיא מהימנא) (עיין רכ\"ו ע\"ב)</p>"],[9520012604,"<p>(ס\"א ובחבורא קדמאה) סֹלֶת לְמִנְחָה, לְאַעְלָאָה לְהַאי סֹלֶת, קַמֵּי מַלְכָּא עִלָּאָה לְמִנְחָה. בֵּין תְּרֵין דְּרוֹעִין.</p>\n<p><Noneb>רעיא מהימנא</b> וּבְחִבּוּרָא קַדְמָאָה, אָמַר רַעְיָא מְהֵימָנָא, מֵהַאי אִשְׁתְּמוֹדַע, הָנֵי מִילִּין סְתִימִין אִינּוּן, וְצָרִיךְ לְמִפְתַּח לוֹן קַמֵּי חַבְרַיָּיא, אַבְרָהָם יִצְחָק דְּתָקִינוּ שַׁחֲרִית וּמִנְחָה, אִתְּמַר עָלַיְיהוּ, (ישעיהו מ״ח:י״ג) אַף יָדִי יָסְדָה אֶרֶץ, דָּא יִצְחָק. וִימִינִי טִפְּחָה שָׁמָיִם, דָּא אַבְרָהָם. דְּדַרְגִּין דִּלְהוֹן חֶסֶד וָפַחַד. דְּאִתְּמַר עָלַיְיהוּ (ישעיהו ס״ב:ח׳) נִשְׁבַּע יְיָ בִּימִינוֹ, וּבִזְרוֹעַ עֻזּוֹ, אִינּוּן תְּרֵין דְּרוֹעִין דְּמַלְכָּא, דְּאִיהוּ יְדוָֹ\"ד, עַמּוּדָא דְּאֶמְצָעִיתָא. סֹלֶת דִּילֵיהּ, דָּא שְׁכִינְתָּא תַּתָּאָה, נְהוֹרָא דִּילֵיהּ, סֹלֶת נְקִיָּיה מִסִּטְרוֹי בְּלָא פְּגִימוּ דַּחֲשׁוֹכָא, וּבְלָא תַּעֲרוֹבֶת חֲשׁוֹכָא כְּלָל. דְּהָכִי אִינּוּן חֲשׁוֹכִין עִם נְהוֹרִין, כְּבַר קֳדָם מוֹץ וְתֶבֶן.</p>\n<p>וּבְחוֹבֵיהוֹן דְּיִשְׂרָאֵל, מִתְעָרְבִין חֲשׁוֹכִין בִּנְהוֹרִין, וּכְגַוְונָא דְּדָשׁ בַּר נָשׁ תְּבוּאָה, וּלְבָתַר אִיהוּ בּוֹרֵר לָהּ, כְּבוֹרֵר אוֹכֶל מִתּוֹךְ פְּסוֹלֶת. כַּךְ יִשְׂרָאֵל, צָרִיךְ לְמֶעְבַּד בְּרוּחֵיהוֹן, כַּד אִתְעֲרָב בְּהוֹן חֲשׁוֹכִין. וְרָזָא דְּמִלָּה, (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. דִּבְהָכִי אִתְבַּר חֲשׁוֹכָא, דְּאִיהוּ יֵצֶר הָרָע, דִּמְכַסֵּי עַל רוּחָא, כְּמוֹץ דִּמְכַסֶּה עַל חִטָּה. אוֹ כְּעָנָן, דִּמְכַסֶּה עַל שִׁמְשָׁא, וְלָא מָנַח לֵיהּ לְאַנְהָרָא.</p>\n<p>וּבְזִמְנִין דְּחֹשֶׁךְ, דְּאִיהוּ יֵצֶר הָרָע, מְכַסֶּה עַל יֵצֶר הַטּוֹב, דְּאִיהוּ אוֹר. אִיהוּ כְּמַאן דְּתָפִיס בְּבֵית הָאֲסוּרִין דְיֵצֶר הָרָע. וְאוֹף הָכִי, כַּד יֵצֶר הַטּוֹב אִיהוּ תָּפִיס בִּרְשׁוּ דְיֵצֶר הָרָע, הָכִי אִינּוּן תְּפִיסִין חַיָּילִין דְּיֵצֶר הַטּוֹב, בִּרְשׁוּ דְּחַיָּילִין דְּיֵצֶר הָרָע. וּבְזִמְנָא דְּיִתְבַּר בַּר נָשׁ רוּחֵיהּ, בְּכָל אֵבָרִין דִּילֵיהּ, קֳדָם יְדוָֹ\"ד, מַה כְּתִיב. (ישעיהו מ״ט:ט׳) לֵאמֹר לַאֲסוּרִים צֵאוּ וְלַאֲשֶׁר בַּחֹשֶׁךְ הִגָּלוּ.</p>\n<p>אֲבָל שְׁכִינְתָּא אִיהִי סֹלֶת נְקִיָּיה, דְּלֵית חֲשׁוֹכָא וְקַבָּלָא יָכִיל לְאִתְעָרְבָא בָּהּ. אִיהִי כַּגֶפֶן, דְּלָא מְקַבְּלָא הַרְכָּבָה מִמִּין אַחֲרָא, דְּלָאו אִיהִי מִינָהּ. וְהַאי סֹלֶת בֵּין דְּרוֹעֵי מַלְכָּא אִיהִי יָתְבָא, בְּלוּלָה בְּשֶׁמֶן כָּתִית. (ע\"כ רעיא מהימנא).</p>"],[9520012605,"<p>(ובחבורא קדמאה) בְּלוּלָה בְּשֶׁמֶן כָּתִית, בְּשֶׁמֶן, בְּהַהוּא שֶׁמֶן דְּנָגִיד וְנָפִיק מִלְּעֵילָּא. אָמַר רַבִּי שִׁמְעוֹן, יָאוּת אַמְרַת. אֲבָל מַאי כָּתִית. אֶלָּא רָזָא עִלָּאָה אִיהוּ. דְּכֵיוָן דְּאִיהוּ שֶׁמֶן, מַאי כָּתִית. אֶלָּא רֶמֶז הוּא דְּקָא רָמִיז לְשַׁמְּשָׁא בְּנוּקְבָּא, לְאַנְגְּדָא לְגַבָּהּ שֶׁמֶן כָּתִית כַּדְּקָא יָאוּת לָהּ, לָא הֲוִי אֶלָּא כָּתִית (ס\"א אלא רזא עלאה הוא, דקא רמיז לאנגדא לגבה שמן כתית כדקא יאות לה), לְאַפָּקָא מִזֵּיתִים, דְּאִינּוּן שַׁיְיפִין דְּגוּפָא, וּלְאַמְשָׁכָא הַהוּא נְגִידוּ מִלְּעֵילָּא, בְּכָל שַׁיְיפָא וְשַׁיְיפָא. (לא הוי אלא כתית)</p>\n<p>וְצַדִיק אִיהוּ דְּכָתִישׁ <Nonei></i>כְּתִישִׁין, וְאַפִּיק מִכָּל אִינּוּן שַׁיְיפִין עִלָּאִין, דְּאִינּוּן זֵיתִין קַדִישִׁין, מְשַׁח רְבוּ בְּתִיאוּבְתָא שְׁלִים, לְגַבֵּי נוּקְבֵיהּ. וְאִי לָא כָּתִישׁ, לָא יִפּוּק הַהוּא מִשְׁחָא, אֶלָּא בְּלָא תִּיאוּבְתָא דְּשַׁיְיפִין, וְהַהוּא נְגִידוּ, לָא אִתְהֲנֵי מִנֵּיהּ נוּקְבָּא, וְלָא הֲוִי כַּדְּקָא יָאוּת, עַד דְּתְהֵא בְּלוּלָה מִנֵּיהּ מִכָּל שַׁיְיפִין. וְעַל דָּא בְּלוּלָה בְּשֶׁמֶן כָּתִית, לְאִתְהֲנָאָה וּלְאִתְזְנָא מִנֵּיהּ. (אמר רעיא מהימנא)</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> (שייך לקמן סוף ע\"ג (נ\"ל דצ\"ל ע\"ב)) אָמַר רַעְיָא מְהֵימָנָא, בּוּצִּינָא קַדִישָׁא, כַּמָּה מְתִיקִין מִילָךְ, וַדָאי אִתְּמַר הָכָא, בְּלוּלָה בְּשֶׁמֶן כָּתִית. וְאִתְּמַר הָתָם, בְּאוֹרַיְיתָא דְבְּעַל פֶּה, בְּלוּלָה בַּמִקְרָא, בַּמִשְׁנָה, בַּתַּלְמוּד. וְעוֹד אִית רָזָא תִּנְיָינָא, בְּלוּלָה בְּשֶׁמֶן כָּתִית. וַדַּאי לָאו אוֹרַיְיתָא אִיהִי בְּלוּלָה. אֶלָּא לְמַאן דְּסָבִיל כַּמָה מַכְתְּשִׁין בְּגִינָהּ. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, דְּלֵית אוֹרַיְיתָא מִתְקַיֶּימֶת, אֶלָּא בְּמִי שְׁמֵמִית גַּרְמֵיהּ עָלָהּ. וְעוֹד אָמְרוּ, בִּזְמַן שֶׁאַתָּה מְכַתֵת רַגְלֶיךָ מִמְּדִינָה לַמְדִינָה, תִּזְכֶּה לִרְאוֹת פְּנֵי שְׁכִינָה.</p>\n<p>וְעוֹד בְּלוּלָה בְּשֶׁמֶן <Nonei></i>כָּתִית, דָּא הוּא דִּמְקַיֵּים פַּת בַּמֶלַח תֹּאכַל, (יחזקאל ד׳:י״א) וּמַיִם בַּמְּשׂוּרָה תִּשְׁתֶּה. וְעוֹד בְּלוּלָה בְּשֶׁמֶן כָּתִית, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ מְדוּכָּא מֵעֲוֹנוֹתֵינוּ. וְעוֹד בְּלוּלָה בְּשֶׁמֶן כָּתִית, דָּא צַּדִיק חַי עָלְמִין, דְּנָגִיד טִפִּין קַדִישִׁין, דְּאִינּוּן פִּירוּרִין כַּזֵּיתִים, מִמּוֹחָא עִלָּאָה, דְּאִינּוּן חַד עִשָּׂרוֹן לָקֳבֵל י'. וּשְׁנֵי עֶשְׂרוֹנִים, י' י'. וּשְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר, י' י' י'. וְאִינּוּן עִשָּׂרוֹן לַכֶּבֶשׂ, וב' עֶשְׂרוֹנִים לָאַיִל, וּשְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר.</p>\n<p>וְרָזָא דְּמִלָּה אָמְרוּ בְּתַעֲנִיוֹת, אֵין טִפָּה יוֹרֶדֶת מִלְּמַעְלָה, שֶׁאֵין עוֹלִין כְּנֶגְדָהּ טִפַּיִּים. וְאִינּוּן בְּרָזָא דָּא ... וּרְמִיזוּ דִּילְהוֹן לְקָבֵל תְלָת מוֹחִין. חַד מוֹחַ הַזִכָּרוֹן. תִּנְיָינָא מוֹחַ הַמַחֲשָׁבָה. תְלִיתָאָה מוֹחַ הַדִּמְיוֹן. הַדִּמְיוֹן וְהַזִכָּרוֹן סָלְקִין מִן לִבָּא הַמָחְשָׁבִית נַחְתָא עַל לִבָּא וּמְקַבְּלִין לָהּ עָלַיְיהוּ כְּמַלְכָּא בְּגִין דְּהָאי אָדָם דְאִיהוּ מַחֲשָׁבָה דְרָכִיב וְשָׁלִיט עַל חֵיוָא תְלִיתָאָה וְנָחִית עֲלָהּ לְגַבֵּי תְרֵין חֵיוָון וּפַתְחִין גַדְפַיְיהוּ לְקַבְּלָא לָהּ כְּגוֹן חוֹלֵם עַל צֵּירֵי אִתְעֲבִיד סֶגוֹלְתָּא וְדָא כֶּתֶר עֶלְיוֹן עַל חָכְמָה וּבִינָה.</p>\n<p>עִשָּׂרוֹן וּשְׁנֵי עֶשְׂרוֹנִים, רְמִיזִין לִתְלַת חֵיוָן דְּמֶרְכַּבְתָּא עִלָּאָה. דְּאִינּוּן: גְּדוּלָה, גְּבוּרָה, תִּפְאֶרֶת. שְׁלֹשָׁה עֶשְׂרוֹנִין, רְמִיזִין: לְנֶצַּח, הוֹד, יְסוֹד. מִרְכֶּבֶת הַמִּשְׁנֶה. רְבִיעִית הַהִין: דָּא מַלְכוּת קַדִישָׁא, ה' רְבִיעָאָה מִן שֵׁם יְדוָֹ\"ד. דְּאִיהוּ אַרְבַּע אַנְפֵּי אָדָם. (ע\"כ רעיא מהימנא).</p>\n<p>רְבִיעִית הַהִין, רַגְלָא רְבִיעָאָה לְכֻרְסְיָיא עִלָּאָה, וְאִיהוּ עוֹלָה תָּמִיד לְגַבֵּיהּ בְּכָל יוֹמָא וְיוֹמָא, עַד מַחֲשַׁבְתָּא עִלָּאָה, דְּלֵית לָהּ סוֹף. וּבְגִין דָּא, עוֹלָה קָא אַתְיָא עַל הִרְהוּר הַלֵּב.</p>"],[9520012606,"<p><Noneb>רעיא מהימנא</b> וּבְחִבּוּרָא קַדְמָאָה אָמַר, רַעְיָא מְהֵימָנָא, הַהִיא תָּגָא דְּזַרְקָא, אִיהִי יוֹד, רְבִיעִית. אוּף הָכִי בַּחַיָּה דִשְׁמָהּ אָדָם, דְּאַרְבַּע אַנְפִּין דִּילֵיהּ דְּאִינּוּן יְדוָֹ\"ד, מַקָּף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָּא. תְּלַת חֵיוָן, דְּאִינּוּן תְּרֵיסָר שְׁבָטִין. (ע\"כ רעיא מהימנא).</p>\n<p>וּבְחִבּוּרָא קַדְמָאָה, עוֹלַת תָּמִיד, אִיהִי רֶגֶל רְבִיעָאָה לְכֻרְסְיָיא עִלָּאָה, דָּא עוֹלָה תָּמִיד בְּכָל יוֹם, מֵאִינּוּן יוֹמִין שִׁית דִּבְרֵאשִׁית. בְּשַׁבָּת עַל חַד תְּרֵין, בְּגִין דְּיִתוֹסַף בָּהּ נְהִירוּ וּשְׁלֵימָא כַּדְּקָא יָאוּת, וְהָא אִתְּמַר.</p>"],[9520012607,"<p><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, מַלְכוּ. בְּשִׁית סְפִירָן אִיהִי עוֹלָה תָּמִיד לְגַבֵּי ו', דְּאָחִיד בְּהוֹן. בֶּן יָ\"הּ, גָּנִיז בַּבִּינָה. וּבְאָן סְפִירָה מֵאִינּוּן שִׁית סְלִיקַת לְגַבֵּיהּ. בְּיוֹמָא תְּלִיתָאָה, דְּאִקְרֵי תִּפְאֶרֶת. דִּבְיוֹם הַשַּׁבָּת אִתוֹסַף עִמֵּיהּ נֶפֶשׁ יְתֵירָה, דְּאִיהִי בִּינָה. ה' עִלָּאָה. י' אוֹת בְּשַׁבָּת, חָכְמָה עִלָּאָה. מֶלֶךְ מְעוּטָּר בְּכֶתֶר, וּבְגִין דָּא, בִּתְפִלַת מוּסַף כֶּתֶר יִתְּנוּ לְךָ.</p>\n<p>וּבְרָאשֵׁי חָדְשֵׁיכֶם, וְכִי כַּמָה רֵישִׁין אִית לָהּ לְסִיהֲרָא. אֶלָּא אִינּוּן תְּרֵין נְקוּדִין, כְּגַוְונָא דָּא נְקוּדָה תַּתָּאָה סִיהֲרָא, תְּרֵין רֵישִׁין דִּילָהּ, תְּרֵין נְקוּדִין דְּאִינּוּן עַלָהּ, סֶגוֹל. בְּקַדְמִיתָא הֲוָה כֶּתֶר עֲלֵי תְּרֵי מַלְכִין כְּגַוְונָא דָּא, וַהֲוַת סְגוֹלְתָּא. וּלְבָתַר דְּאַמָרְת אִי אֶפְשָׁר לִשְׁנֵי מְלָכִים לְהִשְׁתַּמֵשׁ בְּכֶתֶר אֶחָד, אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לְכִי וּמַעֲטִי אֶת עַצְמֵךְ. וּנְחִיתַת לְרַגְלוֹי דִּתְרֵין מְלָכִים, כְּגַוְונָא דָּא וְהַיְינוּ סֶגוֹל, מַה דַּהֲוַת סְגוֹלְתָּא, אִתְהַדְּרַת סֶגוֹל.</p>\n<p>וְרָזָא דְּמִלָּה, לָקֳבֵל תְּרֵין נְקוּדִין, דְּאִינּוּן תְּרֵין מְלָכִים, קָא רָמִיז פָּרִים בְּנֵי בָקָר שְׁנַיִם, וְלָקֳבֵל נְקוּדָה עֲטָרָה עַל רֵישַׁיְיהוּ, אָמַר, וְאַיִל אֶחָד, כְּמוֹ כֶּתֶר אֶחָד. בָּתַר דְּאַמְרַת אִי אֶפְשָׁר לִשְׁנֵי מְלָכִים שֶׁיִשְׁתַּמְּשׁוּ בְּכֶתֶר אֶחָד, אַזְעִירַת גַּרְמָהּ אוּף הָכִי, וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת. אַיִל דְּיִצְחָק, אִתְהַדָּר שָׂעִיר. אִתְהַפָּךְ מֵרַחֲמֵי לְדִינָא, וְאִתְזְעִיר.</p>\n<p>וּבְגִין דָּא שָׂעִיר עִזִּים אֶחָד לְחַטָּאת, וְלֹא אָמַר לְעוֹלָה, לְמֶהֱוִי כֶּתֶר. וּמְנָלָן דְּאִית יְרִידָה בַּחַטָּאת, שֶׁנֶּאֱמַר (ויקרא ט׳:כ״ב) וַיֵּרֶד מֵעֲשׂוֹת הַחַטָּאת. וַאֲמַאי שָׁתַּף עוֹלָה עִם חַטָּאת בַּיְּרִידָה. אֶלָּא לְאוֹלְפָא, דְּעוֹלָה הֲוַת בְּקַדְמִיתָא מִדַּת הָרַחֲמִים, וּלְבָתַר אִתְהַפְּכַת לְדִינָא בַּיְּרִידָה, וְאִתְקְרִיאַת חַטָּאת, וְכֹלָּא חַד.</p>\n<p>וּבְגִין דָּא, הָבִיאוּ עָלַי <Nonei></i>כַּפָּרָה, עָלַי הֲוַת סִיהֲרָא כֶּתֶר וַדַּאי, כְּגַוְונָא דָּא וּלְבָתַר אִתְמְעִיטַת, וְנַחְתַּת לְרַגְלִין דִּילֵיהּ, כְּגַוְונָא דָּא וּבְזִמְנָא דָּא הָבִיאוּ עָלַי כַּפָּרָה, אִיתְּמַר בָּהּ, (ויקרא ו) הִיא הָעוֹלָה, סְלִיקַת מֵרַגְלוֹי. דְּאִתְּמַר בָּהּ, (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי. לְמֵימַר בָּהּ, הַשָּׁמַיִם כִּסְאִי. וְהַאי אִיהוּ רָזָא, (שמואל ב כ״ג:ג׳) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. דִּמְהַפֵּךְ דִּינָא לְרַחֲמֵי. וְרָזָא דְּמִלָּה, (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. כְּגַוְונָא דָּא, דוד\"י. יְדוָֹד.</p>\n<p>וְעוֹד, כֶּבֶשׂ א' וּשְׁנֵי כְּבָשִׂים בְּנֵי שָׁנָה תְּמִימִים, לָקֳבֵל תְּלַת סְפִירָן. שִׁבְעָה כְּבָשִׂים בְּנֵי שָׁנָה, לָקֳבֵל שֶׁבַע סְפִירָן. שִׁבְעָה כְּבָשִׂים, אִינּוּן ז' יוֹמִין דְּסִיהֲרָא. בְּנֵי שָׁנָה, בְּנוֹי דְּסִיהֲרָא, דְּאִקְרֵי שָׁנָה. דְּאִיהִי חֲדָא מֵאִינּוּן שָׁנִים קַדְמוֹנִיּוֹת. (ע\"כ רעיא מהימנא).</p>"],[9520012608,"<p>וּבְרָאשֵׁי חָדְשֵׁיכֶם וְגוֹ'. וְכִי כַּמָה רָאשִׁין אִינּוּן לְסִיהֲרָא. וְהָא לֵית רֵישָׁא לְסִיהֲרָא, אֶלָּא שִׁמְשָׁא, דְּאִיהוּ רֵישָׁא לְגַבָּהּ. אֶלָּא רָאשֵׁי תְּרֵין בְּכָל יַרְחָא וְיַרְחָא. וְאִינּוּן יַעֲקֹב וְיוֹסֵף, דְּמִתְחַדְּתֵּי עַל סִיהֲרָא. וְעַל דָּא בָּעוּ לְחַדְּתָּא לָהּ.</p>\n<p>פָּרִים בְּנֵי בָקָר שְׁנַיִם, אִלֵּין אִינּוּן דְּאָמְרָה סִיהֲרָא, דְּהֵיךְ יִשְׁתַּמְשׁוּן בָּהּ כַּחֲדָא, וְאַזְעִירַת גַּרְמָהּ תְּחוֹתַיְיהוּ. וְאַיִל אֶחָד, דָּא אַיִל דְּיִצְחָק. וְכִי אַבְרָהָם לְאָן אָזִיל. אֶלָּא בְּגִין דְּאִתְּעַר תַּמָּן עֵשָׂו, אִתְכְּנִישׁ אַבְרָהָם, דְּלָא יֶחֱמֵי לֵיהּ, וּמַאן אִיהוּ שָׂעִיר דְּרֹאשׁ חֹדֶשׁ. (תרי נוסחי) וּבְגִּין דְּזַמִּין לְאִתְּעֲרָא תַּמָּן עֵשָׂו דְּאִיהוּ שָׂעִיר אִתְכְּנִישׁ אַבְרָהָם, וְלָא אִשְׁתְּכַח תַּמָּן, יִצְחָק, אִשְׁתְּכַח תַּמָּן, דִּרְחִימוּ דִּילֵיהּ לְגַבֵּיהּ, כְּחַמְרָא עַל דּוּרְדְּיֵיהּ. יַעֲקֹב אִשְׁתְּכַח תַּמָּן, לְתַבְרָא אַנְפּוֹי. יוֹסֵף דְּאִיהוּ שׁוֹר (ס\"א שטן) דִּילֵיהּ, לְגַבֵּי רָחֵל.</p>"],[9520012609,"<p><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימְנָא, וַדַּאי בְּנֵי שָׁנָה אִתְקְרִיאוּ עַל שֵׁם חַמָּה, (נ\"א מלכות) אִימָּא קַדִּישָׁא, דְּאִתְּמַר בָּהּ פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. (ס\"א סיהרא דאקרי שנה דאית בה שנ\"ה יומין, כחושבן) שָׁנָה אִית בָּהּ שס\"ה יוֹמִין, כְּחוּשְׁבַּן שס\"ה לֹא תַּעֲשֶׂה. וְאִיהוּ עַל דָּא לִשְׂמָאלָא. אִימָּא עִלָּאָה, סִיהֲרָא בִּימִינָא. אֲסוּרָה בְּרַתָּא לְאַבָּא דְּאִיהוּ לִימִינָא חֶסֶד. וְאִיהִי כְּלִילָא מרמ\"ח פִּקוּדִין. אִשְׁתְּכַח ו' עִם אִימָּא לִשְׂמָאלָא. בְּרַתָּא עִם אַבָּא לִימִינָא דְּחֶסֶד. (ואיהי כלילא מרמ\"ח פקודין. אשתכח ו' עם אימא, ברתא עם אבא לימינא) וְרָזָא דְּמִלָּה, (משלי ג׳:י״ט) בְּחָכְמָה יָסַד אֶרֶץ. חָכְמָה אַבָּא. אֶרֶץ בְּרַתָּא. כּוֹנֵן שָׁמַיִם דְּאִיהוּ בְּרָא, עִם אִימָּא דְּאִיהוּ תְּבוּנָה, וְהַאי אִיהוּ ידד\"ו, הֲוָיוֹת בְּאֶמְצַע.</p>"],[9520012610,"<p>וְעוֹד וּשְׂעִיר עִזִּים אֶחָד, תְּרֵין שְׂעִירִין אִינּוּן, דְּאִתְּמַר עָלַיְיהוּ (ויקרא ט״ז:ח׳) וְלָקַח אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ' גּוֹרָל אֶחָד לַיְיָ וְגוֹרָל אֶחָד לַעֲזָאזֵל. שָׂעִיר לַיְיָ, בְּגִין מִיעוּט סִיהֲרָא, וְאִיהוּ שָׂעִיר אֶחָד לַיְדוָֹ\"ד לְחַטָּאת. אֶחָד: מִסִּטְרָא דְּיִחוּדָא. אֲבָל שָׂעִיר דַּעֲזָאזֵל, לָא כְּתִיב בֵּיהּ אֶחָד, לָא קָרְבָּן, וְלָא אִשֶּׁה, וְלָא עוֹלָה. אֶלָּא וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. וְשִׁלַּח, כִּדְאָמַר יַעֲקֹב (בראשית ל״ב:י״ט) מִנְחָה הִיא שְׁלוּחָה לַאדֹנִי לְעֵשָׂו. אוּף הָכִי שׁוֹחַד, לְתַּבְרָא רוּגְזָא דְּסָמָאֵ\"ל, דְּלָא יִתְקְרִיב לְמַקְדְּשָׁא לְקַטְרְגָא.</p>\n<p>לְכַלְבָּא דְּאִיהוּ רָעֵב, וּמַאן דְּבָעֵי דְּלָא נָשִׁיךְ לֵיהּ, יָהִיב לֵיהּ בִּשְׂרָא לְמֵיכַל, אוֹ נָהֲמָא, וְיַשְׁקֵי לֵיהּ מַיָּא. וְרָזָא דְּמִלָּה, (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לֶחֶם וְגוֹ'. וּבְדָא יִתְהָדַּר רְחִימוּ דְּבַּר נָשׁ, דְּלָא דַּיי דְּלָא נָשִׁיךְ לֵיהּ בְּכַמָּה יִסּוּרִין, אֶלָּא אִתְהַדָּר לְמֶהֱוִי לֵיהּ סַנֵּיגוֹרָא, וְאִתְהַדָּר רְחִימוֹי.</p>\n<p>וַאֲמַאי הֲווֹ שַׁלְחִין לֵיהּ בְּיַד אִישׁ עִתִּי, פָּגִים. בְּגִין דְּסִטְרִין אַחֲרָנִין כֻּלְּהוּ מָארֵי מוּמִין, וְאִתְקְרִיאוּ שְׂעִירִים, דִּכְתִּיב, (ישעיהו י״ג:כ״א) וּשְׂעִירִים יְרַקְּדוּ שָׁם. וְאִתְּמַר בְּהוֹן, (ויקרא י״ז:ז׳) וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים. דְּעָלַיְיהוּ אִתְּמַר, (דברים ל״ב:י״ז) יִזְבְּחוּ לַשֵּׁדִים לֹא אֱלוֹהַּ. וּבְשָׂעִיר דָּא, אִתְפְּרַשׁ מִכֹּלָּא, וְנוֹשֵׂא כָּל חוֹבִין דְּיִשְׂרָאֵל עָלֵיהּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא ט״ז:כ״ב) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם. וְעוֹד, בָּתַר דְּנָטִיל אִיהוּ וְנָשָׂא. קוּדְשָׁא בְּרִיךְ הוּא נוֹשֵׂא עָוֹן. (שמות ל״ד:ז׳) מַאי בֵּין נוֹשֵׂא לְנָשָׂא. נָשָׂא: מָטוּלָא. נוֹשֵׂא: סְלִיקוּ דְּמָטוּלָא. (ובחבורא קדמאה) (ע\"כ רע\"מ)</p>\n<p>וּשְׁלֹשָׁה עֶשְׂרוֹנִים, תְּלַת דַּרְגִּין קַדְמָאִין דִּילָהּ, דְּכָל חַד וְחַד עֶשֶׂר, כְּגַוְונָא דִּלְעֵילָּא עֶשְׂרוֹנִים, חַד מֵעֲשַׂרָה. וּשְׂעִיר חַטָּאת אֶחָד, אֲמַאי אִקְרֵי חַטָּאת. בְּגִין דְּאִיהוּ חַטָּאת, וּמִסִּטְרָא דְּחַטָּאת הוּא. אָמַר רִבִּי אֶלְעָזָר, וְהָא כְּתִיב לַיְיָ. <Nonei></i>אֶלָּא לַיְיָ אִתְקְרִיב וַדַּאי, דִּכְתִּיב לְכַפֵּר. לְתַּבְרָא אַנְפִּין, וְכֹלָּא יִתְקְרִיב לְמַקְדְּשָׁא, אֶלָּא יָהֲבֵי חוּלָקָא חֲדָא לְסָמָאֵל, וְאָכִיל לֵיהּ, וְלָא אָחִיד בִּשְׁאַר קָרְבְּנִין. וְדָא אִיהוּ לְחוֹדֵיהּ, דְּלָא אִשְׁתְּתַּף אַחֲרָא עִמֵּיהּ לְמֵיכַל בֵּיהּ.</p>\n<p>אִיהוּ אִתְהֲנֵי בְּגוֹ סְעוּדָתָא דְּמַלְכָּא בְּחוּלָקָא דָּא, וְעַל דָּא חַדֵּי, וְאִתְפְּרַשׁ מִיִשְׂרָאֵל, וְלָא מְקַטְרְגָא עָלַיְיהוּ. וְאִי לָאו דְּהֲוָה מִיעוּטָא דְּסִיהֲרָא, לָא הֲווֹ יָהֲבֵי לֵיהּ בִּסְעוּדָתָא דְּמַלְכָּא כְּלוּם. וְכִי בְּמִיעוּטָא דְּסִיהֲרָא מַאי קָא עָבִיד. אֶלָּא בְּגִין דְּקָרִיב וְיָנִיק, וְנָטִיל חֵילָא לְעַמֵּיהּ, מִגּוֹ סְטָר שְׂמָאלָא דְּסִיהֲרָא, וְאִתְתְּקַף בֵּיהּ. וּבְשָׂעִיר דָּא אִתְפְּרַשׁ מִכֹּלָּא, וְאִתְהֲנֵי בְּהַאי. וּבְגִין דְקוּדְשָׁא בְּרִיךְ הוּא אַזְעִיר לָהּ לְסִיהֲרָא, מְקָרְבִין לֵיהּ לְהַאי שָׂעִיר, בְּגִין דְּיִתְפְּרַשׁ מִנָּהּ, וְלָא יִתְקְרִיב לְמַקְדְּשָׁא. וְעַל דָּא תָּנֵינָן, הָבִיאוּ עָלַי כַּפָּרָה. עָלַי: בְּגִינֵי, דְּאַזְעִירַת לָהּ, בְּגִין סִבַּת דִּילִי אַתּוּן צְרִיכִין דָּא.</p>"],[9520012611,"<p><Noneb>רעיא מהימנא</b> (במדבר כ״ח:י״א) וּבְרָאשֵׁי חָדְשֵׁיכֶם, אִינּוּן יַעֲקֹב וְיוֹסֵף. (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף, דִּמְחַדְּתֵּי עַל סִיהֲרָא. אַשְׁכַּחְנָא בְּסִפְרָא דְּחֲנוֹךְ דְּאָמַר, כְּמָה דִּבְרֹאשׁ חֹדֶשׁ, דְּאִתְדַּכִּיאַת סִיהֲרָא לְאִתְקָרְבָא בְּבַעְלָהּ, אִצְטְרִיךְ לְמֵיהַב לְסִטְרָא אַחֲרָא חוּלָקָא חֲדָא, בְּהַהוּא זִינָא דִּילָהּ. אוּף הָכִי נָמֵי אִצְטְרִיכַת לְאִתְּתָא, בְּשַׁעֲתָא דְּאִתְדַּכִּיאַת לְאִתְקָרְבָא בְּבַעְלָהּ, לְמֵיהַב חוּלָקָא חֲדָא לְסִטְרָא אַחֲרָא, בְּהַהוּא זִינָא דִּילֵיהּ.</p>\n<p>וּמַאן אִיהוּ. הַהוּא חוּלָקָא טוּפְרָהָא בְּטִנּוּפָא דִּלְהוֹן. וּזְעֵיר מֵרֵישׁ דְּשַׂעֲרָא, בְּגִין דְּבָעֵי לְאַסְרְקָא רֵישָׁא, וּלְאַכְרְכָא לוֹן דָּא בְּדָא, וְלָא יֵזִיל אֲבַתְרָהּ הַהוּא סִטְרָא בִּישָׁא, לְאַבְאָשָׁא לָהּ, וְאִתְפְּרַשׁ מִנָּהּ בְּכָל סִטְרִין. וּמַה תַּעֲבִיד, מֵהַהוּא שַׂעֲרָא וְטוּפְרִין. לְבָתַר דְּתַכְרִיךְ לוֹן כַּחֲדָא, אִצְטְרִיךְ לְאָנָחָא לוֹן בַּאֲתָר דְּלָא עַבְרִין תַּמָּן בְּנֵי נָשָׁא, אוֹ בְּגוֹ חוֹרִין תַּתָּאִין דַּחֲצֵרָא, וְתַגְנִיז לוֹן תַּמָּן. (ועוד ובראשי חדשיכם אמרו, שייך כאן)</p>\n<p>וְעוֹד וּבְרָאשֵׁי חָדְשֵׁיכֶם אָמְרוּ רַבָּנָן דְּמַתְנִיתִין, דְּכַד הֲווֹ מְקַדְּשִׁין יַרְחִין עַל פִּי בֵּית דִּין, הֲווֹ מַשִּׂיאִין מַשּׂוּאוֹת בְּרָאשֵׁי הֶהָרִים, וַהֲווּ אַמְרִין כָּזֶה רְאֵה וְקַדֵּשׁ. לְזִמְנִין סִהֲרָא הֲוַת כְּגַוְונָא דָּא הֲוָה מִסְתַכְּלָא לְעֵילָא בְּקַרְנָא. וּלְזִמְנִין מִסְתַכְּלָא לְתַתָּא כְּגווָֹנָא דָּא לְזִמְנִין מִסְתַכְּלָא לְמִזְרָח כְּגווָֹנָא דָּא כ לְזִמְנִין לְמַעֲרָב כְּגווָֹנָא דָּא לְזִמְנִין לְדָרוֹם וּלְזִמְנִין לַצָּפוֹן וְהַאי אִיהוּ כ אִסְתַכְּלוּתָהּ דִּילָהּ לְשִׁית סִטְרִין דְּכָלִיל לוֹן תִפְאֶרֶת דְאִיהוּ ו' גְּדוּלָּה גְּבוּרָה תִּפְאֶרֶת. נֶצַח הוֹד יְסוֹד.</p>\n<p>נְקוּדָא דְּנָגִיד עָלֵיהּ מִלְּגוֹ, הִיא חָכְמָה. וְהַהִיא חוּט דְּאַסְחַר עָלָהּ, אִיהוּ כֶּתֶר. וְהַהִיא נְקוּדָא אִיהוּ לְזִמְנִין עֲטָרָה, וּלְזִמְנִין כִּסֵּא, לְמֵיתַב עָלֵיהּ, לְזִמְנִין שְׁרַפְרָף לַהֲדוֹם רַגְלָיו.</p>\n<p>וַאֲמַאי אִתְקְרִיאַת לְבָנָה. עַל שֵׁם לִבּוּן הַהֲלָכָה, דְּאִיהִי מִלְּגוֹ, (תהילים מ״ה:י״ד) כָּל כְּבוּדָּה בַּת מֶלֶךְ פְּנִימָה. וּבְאֶשָּׁא דְּבִינָה דְּנָחִית עָלָה אִיהִי מִתְלַבְּנַת. וְרָזָא דְּמִלָּה, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וּמַאי דַּהֲוַת אֲדֹנָי דִּינָא, סוּמָקָא בִּגְבוּרָה, דְּתַמָּן בִּינָה. אִתְלַבְּנַת מִסִּטְרָא דְּחֶסֶד, דְּתַמָּן חָכְמָה, וְאִתְהַדְּרַת יְדוָֹד.</p>\n<p>וּמַה גָּרִים לְאִתְהַפְּכָא מִדִּינָא לְרַחֲמֵי צַדִּיקִים גְּמוּרִים דְּסִיהֲרָא מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע, אִיהִי קְלִיפָא דִּילֵיהּ חֲשׁוּכָא, אִם בַּהֶרֶת שְׁחוֹרָה, הִיא יֵצֶר הָרָע, שִׁפְחָה. (ויקרא יג) וּשְׁפָלָה אֵינֶנָּה וְהִיא כֵּהָה, וְלֵית לָהּ מִדִילָהּ, אֶלָּא הַהוּא חוּט דְּנָהִיר בָּהּ, דְּאִיהוּ לִוָּה לָהּ בְּלֵילְיָא, דְּאִיהִי גָּלוּתָא. וְאִתְעֲבָר מִנָּהּ בִּימָמָא, דְּאִיהוּ עָלְמָא דְּאָתֵי, דְּבֵיהּ (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>אֲבָל סִיהֲרָא דְּעֵץ הַחַיִּים, הַהִיא נְקוּדָּה דִּלְגָו מִנָּהּ, אִיהִי כְּמַבּוּעָא דְּלֵית לֵיהּ פְּסָק, דִּכְתִּיב בָּהּ, (ישעיהו נ״ח:י״א) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו. וְאִתְקְרִיאַת אַיֶּלֶת אַהָבִים מִסִּטְרָא דְּחֶסֶד, דְּהַיְינוּ (ירמיהו ל״א:ג׳) אַהֲבַת עוֹלָם אַהֲבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חֶסֶד. וּתְרֵין קַרְנָיִן אִית לָהּ מִן נְהוֹרָא, כְּגַוְונָא דָּא לְזִמְנִין הָאַחַת גָּבוֹהַּ מִן הַשֵׁנִית כְּגווָֹנָא דָּא: לְזִמְנִין קַרְנִין אִינוּן שָׁוִין. (ע\"כ רעיא מהימנא).</p>"],[9520012612,"<p><Nonei></i>וּבַחֹדֶשׁ הָרִאשׁוֹן וְגוֹ'. רִבִּי אַבָּא פָּתַח, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרוֹג אֵלֶיךָ אֱלֹהִים. הַאי קְרָא אוֹקְמוּהָ, כְּתִיב הָכָא אַיָּל וּכְתִיב הָתָם אַיֶּלֶת בְּגִין דְּאִית דְּכַר וְאִית נוּקְבָּא (ואף על גב דאית דכר ונוקבא, כולא חד. האי איל, איהו אקרי דכר. ואיהו אקרי נוקבא. הדא הוא דכתיב כאיל תערוג ולא כתיב יערוג. וכלא חד. אילת השחר).</p>\n<p>מַאי אַיֶּלֶת הַשַּׁחַר. אֶלָּא דָּא אִיהִי חַיָּה חֲדָא רַחֲמָנִית, דְּלֵית בְּכָל חֵיוָן דְּעָלְמָא רַחֲמָנִית כְּוָותָהּ. בְּגִין דִּבְשַׁעֲתָא דִּדְחִיקַת לָהּ שַׁעֲתָא, וְאִצְטְרִיכַת לִמְזוֹנָא לָהּ וּלְכָל חֵיוָן. אִיהִי אַזְלַת לְמֵרָחִיק לְאֹרַח רְחִיקָא. וְאָתִיאַת וְאוֹבִילַת מְזוֹנָא. וְלָא בָּעָאת לְמֵיכַל, עַד דְּתֵיתֵי וְתִתְהַדָר לְאַתְרָהָא. אֲמָאי. בְּגִין דְּיִתְכַּנְשׁוּן לְגַבָהּ שְׁאַר חֵיוָן, וּתְחָלֵק לוֹן מֵהַהוּא מְזוֹנָא. וְכַד אָתַת, מִתְכַּנְּשִׁין לְגַבָּהּ כָּל שְׁאַר חֵיוָן, וְהִיא קַיְּימָא בְּאֶמְצָעִיתָא, וּפַלְגַת לְכָל חַד וְחַד. וְסִימָן, (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ'. וּמִמַּה דִּפְלִיגַת לוֹן, אִיהִי שַׂבְעָה, כְּאִלּוּ אָכְלָה יַתִּיר מֵיכְלָא מִכֹּלָּא. (אימתי פליגת לון).</p>\n<p>וְכַד יֵיתֵי צַפְרָא דְּאִקְרֵי שַׁחַר. יֵיתֵי לָהּ חֲבָלִים דְּגָלוּתָא. וּבְגִין דָּא, אִתְקְרִיאַת אַיֶּלֶת הַשַּׁחַר. עַל שֵׁם קַדְרוּתָא דְּצַפְרָא. דַּחֲבָלִים לָהּ כַּיּוֹלֵדָה. הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ז) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ וְגוֹ'. (אמר רעיא מהימנא בההוא זמנא שייך אחרי זה)</p>\n<p>אֵימָתַי פַּלְגַּת לְהוֹן. כַּד צַפְרָא בָּעֵי לְמֵיתֵי. בְּעוֹד דְּאִיהִי לֵילְיָא, וְקַדְרוּתָא סְלִיקַת לְאַנְהָרָא. כְּמָה דְאַתְּ אָמֵר, וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ'. כֵּיוָן דְּאַנְהִיר צַפְרָא, כֻּלְּהוּ שַׂבְעִין בִּמְזוֹנָא דִּילָהּ.</p>\n<p>כְּדֵין, קָלָא חֲדָא אִתְעַר בְּאֶמְצָעִיתָא דִּרְקִיעַ, קָארֵי בְּחַיִל וְאָמַר, קְרִיבִין עוּלוּ לְדוּכְתַיְיכוּ. רְחִיקִין. פּוּקוּ. כָּל חַד וְחַד לִיכְנֻשׁ לְאַתְרֵיהּ דְּאִתְחֲזֵי לֵיהּ. כֵּיוָן דְּאַנְהִיר שִׁמְשָׁא, כָּל חַד וְחַד אִתְכְּנִישׁ לְאַתְרֵיהּ. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ב) תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן וְגוֹ'. וְאִיהִי אַזְלַת בִּימָמָא, וְאִתְגַּלְיָא בְּלֵילְיָא. וּפַלְגָּא בְּצַפְרָא. וּבְגִין כָּךְ אִקְרֵי, אַיֶּלֶת הַשַּׁחַר.</p>\n<p>לְבָתַר אִתַּתְקְפַת כְּגִיבָּר וְאַזְלַת, וְאִקְרֵי אַיָּל. לְאָן אֲתָר אַזְלַת. אַזְלַת שִׁתִין פַּרְסֵי מֵהַהוּא <Nonei></i>אֲתָר דְּנָפְקָא, וְעָאלַת לְגוֹ טוּרָא דַּחֲשׁוֹכָא. (ומתמן ארחת מזונא) אַזְלַת בְּגוֹ הַהוּא טוּרָא דַּחֲשׁוֹכָא, אָרַח לְרַגְלָהּ חִוְיָא חֲדָא עֲקִימָא, וְאָזִיל לְרַגְלָהּ. וְאִיהִי סַלְּקָא מִתַּמָּן, לְגַבֵּי טוּרָא דִּנְהוֹרָא. כֵּיוָן דְּמָטַת תַּמָּן, זַמִּין לָהּ קוּדְשָׁא בְּרִיךְ הוּא חִוְיָא אַחֲרָא, וְנָפִיק וּמְקַטְרְגָא דָּא בְּדָא, וְאִיהִי אִשְׁתְּזִיבַת. וּמִתַּמָּן נַטְלַת מְזוֹנָא, וְתָבַת לְאַתְרָהּ, בְּפַלְגוּת לֵילְיָא. וּמִפַּלְגוּ לֵילְיָא, שַׁרְיָא לְפַלְגָא, עַד דִּסְלִיקַת קַדְרוּתָא דְּצַפְרָא. כֵּיוָן דְּאַנְהִיר יְמָמָא, אַזְלַת, וְלָא אִתְחֲזִיאַת, כְּמָה דְּאִתְּמַר.</p>\n<p>וּבְשַׁעֲתָא דְּעָלְמָא אִצְטְרִיךְ לְמִטְרָא, מִתְכַּנְּשִׁין לְגַבָּהּ כָּל שְׁאַר חֵיוָן, וְהִיא סְלִיקַת לְרֵישׁ טוּרָא רַמָאָה, וְאִתְעַטְּפַת רֵישָׁהָא בֵּין בִּרְכָהָא, וְגָעַת גּוֹעָה בָּתַר גּוֹעָה, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁמַע קֹלָּהּ, וְאִתְמְלֵי רַחֲמִין, וְחָס עַל עָלְמָא. וְהִיא נַחְתַּת מֵרֵישׁ טוּרָא, וְרָהֲטַת, וּטְמִירָת גַּרְמָהָא. וְכָל שְׁאַר חֵיוָתָא אֲבַּתְרָהָא רָהֲטִין, וְלָא מַשְׁכְּחִין לָהּ. הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם. מַאי עַל אֲפִיקֵי מָיִם. עַל אֲפִיקֵי מָיִם מֵהַנְהוּ דְּאִתְיְבָּשׁוּ, וְעָלְמָא צָחֵי עַל מַיָּיא, כְּדֵין תַּעֲרוֹג.</p>\n<p>בְּשַׁעֲתָא דְּאִתְעַבְּרַת, אַסְתִּימַת, כֵּיוָן דְּמָטָא זִמְנָא לְמֵילַד, גָּעָאת וְרָמַאת קָלִין, קָלָא בָּתַר קָלָא, עַד שִׁבְעִין קָלִין, כְּחוּשְׁבַּן תֵּיבִין (תהילים כ׳:ב׳) דְּיַעַנְךָ יְיָ בְּיוֹם צָרָה, דְּאִיהִי שִׁירָתָא דְּעוּבַּרְתָּא דָּא. וְקוּדְשָׁא בְּרִיךְ הוּא שָׁמַע לָהּ, וְזַמִּין לְגַבָּהּ. כְּדֵין אַפִּיק חַד חִוְיָא רַבְרְבָא, מִגּוֹ טוּרֵי חָשׁוּךְ וְאָתֵי בֵּין טוּרִין, פּוּמֵיהּ מְלַחֲכָא בְּעַפְרָא, מָטֵי עַד הַאי אַיָּל, וְאָתֵי וְנָשִׁיךְ לָהּ בְּהַהוּא אֲתָר, תְּרֵי זִמְנֵי.</p>\n<p>זִמְנָא קַדְמָאָה נָפִיק דָּמָא, וְאִיהִי לָחִיךְ. זִמְנָא תִּנְיָינָא, נָפִיק מַיָּיא וְשָׁתוּ כָּל אִינּוּן בְּעִירָן דִּי בְּטוּרַיָיא, וְאִתְפַּתְחַת וְאוֹלִידַת. וְסִימָנִךְ (במדבר כ׳:י״א) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. וּכְתִיב וַתֵּשְׁתְּ הָעֵדָה וּבְעִירָם.</p>\n<p>בְּהַהוּא זִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא חָס עָלָהּ עַל (ס\"א עובדא) עוּבַּרְתָּא דְּנָחָשׁ (ס\"א דחיה) דָּא. מַה כְּתִיב, (תהילים כ״ט:ט׳) קוֹל יְיָ יְחוֹלֵל אַיָּלוֹת וַיֶּחֱשׂוֹף יְעָרוֹת וְגוֹ', קוֹל יְיָ יְחוֹלֵל אַיָּלוֹת, אִינּוּן חַבָלִין וְצִירִין, לְאַתְּעָרָא אִינּוּן שִׁבְעִין קַלִין. מִיַּד וַיֶּחֱשׂוֹף יְעָרוֹת, לְאַעְבָּרָא (נ\"א לאתערא) הַהוּא נָחָשׁ, וּלְאִתְגַּלְיָיא הַהִיא חַיָּה בֵּינַיְיהוּ לְמֵיהַךְ. וּבְהֵיכָלוֹ, מַאי וּבְהֵיכָלוֹ. בְּהֵיכָלוֹ דְקוּדְשָׁא בְּרִיךְ הוּא, כָּל אִינּוּן אָכְלוּסִין, פַּתְחִין וְאַמְרִין כָּבוֹד. מַאי כָּבוֹד. (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ מִמְּקוֹמוֹ.</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> וְאִי תֵּימָא דִּלְע' תָּחִיל וּלְב' שְׁנִין אוֹלִידַת, בָּתַר אֶלֶף וּמָאתָן, כְּחוּשְׁבַּן רע\"ב. הָא כְּתִיב (ישעיהו ס״ו:ז׳) בְּטֶרֶם תָּחִיל יָלָדָה. וְרָזָא דְּמִלָּה, (ישעיהו ס״ה:כ״ד) וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה עוֹד וְגוֹ'. וּמַאי (ס\"א יומא) בְּטֶרֶם. אֶלָּא קֹדֶם דְּיִשְׁתְּלִימוּ, שִׁבְעִין וּתְרֵין שְׁנִין, בָּתַר אֶלֶף וּמָאתָן, אִינּוּן חֲבָלִים דְּיוֹלֵדָה, יִתְגָלְיָין ב' מְשִׁיחִין בְּעָלְמָא. וּבְהַהוּא זִמְנָא (תהילים כ״ט:ט׳) וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד, וְהָא אוֹקְמוּהָ (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ.</p>\n<p>בְּהַהִיא שַׁעֲתָא, אִלֵּין מָארֵי תּוֹרָה יִהוֹן נִכְבָּדִים. אִלֵּין דִּסְבִילוּ כַּמָה חֲבָלִים וְצִּירִין כַּיּוֹלֵדָה, וַהֲווּ מְבוּזִּין בֵּין עַמֵּי הָאָרֶץ, יְהוֹן נִכְבָּדִים. וּמִיַּד (תהילים כ״ט:י׳) יְיָ לַמַּבּוּל יָשָׁב, לְרַשִׁיעֲיָא. אֵין מַבּוּל, אֶלָּא דִּינִין דְּמַבּוּל. כְּגַוְונָא דְּנִפְתָחוּ (בראשית ז׳:י״א) מַעְיְינוֹת תְּהוֹם וַאֲרוּבּוֹת הַשָּׁמַיִם נִפְתְּחוּ בְּיוֹמֵי טוּפְנָא, אוּף הָכָא יִתְעָרוּן דִּינִין לְגַבַּיְיהוּ עֵילָּא וְתַתָּא, עַד דְּלֵית סוֹף וְתַכְלִית, וְכָל בִּזּוּיִין וּקְלָנָא, דְּעָבְדוּ אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, לְשֵׁם יְהוָֹה וּלְעַמֵּיהּ, וְכַמָּה חֵרוּפִין דִּסְבִילוּ יִשְׂרָאֵל מִנַּיְיהוּ עַל שֵׁם יְיָ, מִכֻּלְּהוּ נָטִיל נוּקְמָא קוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אִתְקְרֵי, (נחום א׳:ב׳) נוֹקֵם יְיָ וְנוֹטֵר וּבַעַל חֵמָה לְגַבַּיְיהוּ.</p>"],[9520012613,"<p>וּבַחֹדֶשׁ הָרִאשׁוֹן, מַאן רִאשׁוֹן. דָּא נִיסָן. תַּמָּן אוֹלִידַת הַהִיא חַיָּה, לְקַיֵּים מַה דְּאוֹקְמוּהָ מָארֵי מַתְנִיתִין, בְּנִיסָן נִגְאֲלוּ וּבְנִיסָן עֲתִידִין לְהִגָּאֵל. וּבְי\"ד דִּילֵיהּ, (שמות י״ז:ט״ז) וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ, תַּמָּן אוֹמֵי לְאַעְבְּרָא מֵעָלְמָא זַרְעָא דְּעֵשָׂו עֲמָלֵקִיִּים, בְּהַהוּא זִמְנָא (שמות י״ב:כ״א) מִשְׁכוּ וּקְחוּ לָכֶם צֹּאן לְמִשְׁפְּחוֹתֵיכֶם וְשַׁחֲטוּ הַפָּסַח. מִשְׁכוּ: (הושע ז׳:ה׳) מָשַׁךְ יָדוֹ אֶת לוֹצְּצִּים.</p>\n<p>בְּהַהוּא זִמְנָא, כֹּה אָמַר יְיָ לָרוֹעִים הַפּוֹשְׁעִים בִּי. וְאוֹמֵר, (יחזקאל י״ג:ט׳) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ. וְאִלֵּין אִינּוּן רוֹעִים דְּעָנָא, פַּרְנָסֵי דָּרָא. וּבְגִין דָּא אִתְּמַר עָלַיְיהוּ, (הושע ב׳:ט״ז) הִנֵּה אָנֹכִי מְפַתֶּיהָ וְהוֹלַכְתִּיהָ הַמִּדְבָּרָה. (יחזקאל כ׳:ל״ו) וְנִשְׁפַּטְתִּי אִתְּכֶם וְגוֹ', כַּאֲשֶׁר נִשְׁפַּטְתִּי אֶת אֲבוֹתֵיכֶם דְּקָטִיל לוֹן בְּמַכַּת חֹשֶׁךְ. (ע\"כ רעיא מהימנא)</p>\n<p><Nonei></i>(במדבר כ״ח:ט״ז) וּבַחֹדֶשׁ הָרִאשׁוֹן, מַאן חֹדֶשׁ הָרִאשׁוֹן. דָּא אִיהוּ חֹדֶשׁ, דְּהַאי חַיָּה אִתְגַּלְיָיא בֵּיהּ וְאִתַתְקְפַת בֵּיהּ, וְנָפְקָא לְעָלְמָא בְּאַרְבָּעָה עָשָׂר יוֹם. בְּאַרְבָּעָה עָשָׂר, אִלֵּין שְׁאַר חֵיוָותָא, דְּאִינּוּן י' י' לְכָל סְטָר, בְּד' סִטְרִין דְּעָלְמָא. וּבְסִפְרֵי קַדְמָאֵי, אִיהוּ י', וְחַד לְכָל סְטָר לְאַרְבַּע סִטְרִין, וְאִינּוּן אַרְבַּע עָשָׂר. כֵּיוָן דְּאִינּוּן אַרְבַּע, מִתְחַבְּרָאן וּמִתְתַּקְּנָן עִם אִינּוּן עֶשֶׂר דִּבְסִטְרָא דִּימִינָא, כְּדֵין י\"ד, בְּחֶדְוָה לְאִתְתַּקְנָא חַיָּה דָּא (ס\"א לאתקנא סיהרא חיה דא) בְּתִקּוּנָהָא.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, וַדַּאי הָכִי הוּא. וְתָּא חֲזֵי, כְּתִיב (שמות י״ב:כ״א) מִשְׁכוּ וּקְחוּ לָכֶם צֹאן וְגוֹ', מִשְׁכוּ, (בחבורא קדמאה) מַאי מִשְׁכוּ. כְּמַאן דְּמָשִׁיךְ מֵאֲתָר אַחֲרָא, לַאֲתָר דָּא. מִשְׁכוּ יוֹמִין עִלָּאִין לְגַבֵּי יוֹמִין תַּתָּאִין. יוֹמִין עִלָּאִין אִינּוּן שס\"ו, <Nonei></i>כְּחוּשְׁבַּן מִשְׁכוּ. יוֹמִין תַּתָּאִין, זִמְנִין דְּאִינּוּן שנ\"ה, וּבְזִמְנָא, דְּאִתְנַהֲרָא סִיהֲרָא בְּאַשְׁלְמוּתָא, סְלִיקוּ לְמֶהֱוֵי אִינּוּן יוֹמִין שס\"ה, כְּחוּשְׁבַּן מִשְׁכוּ חָסֵר חַד.</p>\n<p>מִשְׁכוּ יוֹמִין עִלָּאִין לְגַבֵּי יוֹמִין תַּתָּאִין, לְמֶהֱוִי כֻּלְּהוּ כַּחֲדָא בְּחִבּוּרָא חֲדָא. וּמַאן מָשִׁיךְ לוֹן. אִינּוּן עֶשֶׂר דְּלִסְטַר יְמִינָא, דִּכְתִּיב בֶּעָשׂוֹר. בֶּעָשׂוֹר, בַּעֲשָׂרָה מִבָּעֵי לֵיהּ, מַאי בֶּעָשׂוֹר. אֶלָּא (תצוה ק\"פ ע\"א) ט' אִינּוּן לְכָל סְטָר, וּנְקוּדָּה חֲדָא דְּאַזְלָא בְּאֶמְצָעִיתָא. כְּגַוְונָא דָּא, וְהַהִיא נְקוּדָה אֲשְׁלִימָת לְעֶשֶׂר וְעַל דָּא בְּעֲשׂוֹר כְּמָה דְאִתְמָר זָכוֹר וְשָׁמוֹר לְשִׁמוּשָׁא בַּעֲשָׂרָה אִינוּן יוֹמִין תֵּשַׁע בְּהַהוּא נְקוּדָה. לַחֹדֶשׁ הַזֶּה יוֹמִין דְלִסְטָר יְמִינָא בְּגִין לְאִתְחַבְּרָא זֹאת בָּזֶה לְמֵהֲוִי כֹּלָּא חַד.</p>\n<p>וּבְזִמְנָא דְּאִינּוּן ד' אִתְקְשָּׁרוּ לְד' סִטְרִין (מתחברן) בַּהֲדַיְיהוּ. כְּדֵין אוֹלִידַת הַהוּא חַיָּה וְחִוְיָא אָזִיל לֵיהּ וּבְהַהוּא זִמְנָא מְקַדְּשִׁין לְעֵילָּא לְהַאי חַיָּה וְקָרָאן לָהּ כָּבוֹד. וּכְדֵין אִתְקַדָּשׁ מוֹעֲדָא. מַה דְּלָא הֲוָה עַד הַשְׁתָּא, וּכְעַן קָרָאן לָהּ כָּבוֹד, הֲדָא הוּא דִּכְתִּיב, (תהילים כ״ט:ט׳) וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד. (אמר רעיא מהימנא מילין אלין שייך כאן)</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, מִלִּין אִלֵּין סְתִימִין, וְצָרִיךְ לְמִפְתַּח לוֹן לְגַבֵּי חַבְרַיָּיא, דְּמַאן דְּסָתִים לוֹן גְּנִיזִין דְּאוֹרַיְיתָא, אִיהוּ מְצַעֵר לוֹן. דִּלְרַשִׁיעֲיָיא נְהוֹרִין דְּרָזִין, אִתְחַזְרָן לוֹן חֲשׁוֹכִין. וְאִיהוּ מָתְלָא לְמָמוֹנָא דְּאִיהוּ גָּנִיז, מַאן דְּחָפַר לֵיהּ, עַד דְּגַלֵּי לֵיהּ, וְלָאו אִיהוּ דִּילֵיהּ, אִתְהַדָּר בְּסוּכְלְתָנוּתֵיהּ בַּחֲשׁוֹכָא וְקַבְלָא. וּלְמַאן דְּאִיהוּ דִּילֵיהּ, נָהִיר לֵיהּ. וּבְגִין דָּא, אִית לְבַּר נָשׁ לְגַלָּאָה רָזִין סְתִימִין דִּבְאוֹרַיְיתָא.</p>\n<p>בֶּעָשׂוֹר: ט' אִינּוּן לְכָל סְטָר, לָקֳבֵל ט' יַרְחִין דְּיוֹלֵדָה, כְּחוּשְׁבַּן א\"ח. מַאן יוֹלֶדֶת. ד' מִן אֶחָד. א\"ח, אִיהוּ ט', לְד' סִטְרִין דְּאָת ד', וְאִינּוּן אַרְבָּעִים. א\"ח זָכוֹר, ד' שָׁמוֹר. הָא אַרְבְּעִין וּתְרֵין.</p>\n<p>אִשְׁתְּאַר כָּבוֹד, דְּאִתְּמַר בֵּיהּ בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְאִיהוּ כָּבוֹד ל\"ב, ד' זִמְנִין לְכָל סְטָר דְּאָת ד', הֲרֵי ס\"ד לְד' סִטְרִין, רנ\"ו. וְאוֹקְמוּהָ, כָּבוֹד לְעֵילָּא, ל\"ב לְתַתָּא. וּבְגִין דָּא <Nonei></i>מְיַיחֲדִין בְּכָל יוֹמָא תְּרֵין זִמְנִין, דְּאַמָרָן בְּהוּ תְּרֵין זִמְנִין כָּבוֹד, דְּאִיהוּ ס\"ד. וּתְרֵין זִמְנִין ד' ד' מִן אֶחָ\"ד, הֲרֵי ע\"ב. הֲרֵי ד' דְּאֶחָ\"ד, שְׁלִימוּ דְּמ\"ב שְׁמָהָן. וּשְׁלִימוּ דְּע\"ב שְׁמָהָן. וּבְגִין דָּא אַמְרִין בְּמִזְמוֹר לְדָוִד (תהילים כ״ד:ח׳) מִי זֶה מֶלֶךְ הַכָּבוֹד יְיָ עִזוּז וְגִבּוֹר. וּבְזִמְנָא תִּנְיָינָא מִי הוּא זֶה מֶלֶךְ הַכָּבוֹד. (ע\"כ רעיא מהימנא) (אמר רעיא מהימנא מילין אלין שייך כאן).</p>\n<p>מַאן הֵיכָלוֹ. דָּא הֵיכָל עִלָּאָה פְּנִימָאָה, דְּתַמָּן מִתְקַדְּשָׁא כֹּלָּא. תַּמָּן מְקַדְּשִׁין לְמַאן דְּחָזֵי לְאִתְקַדְּשָׁא. הֵיךְ מְקַדְּשִׁין לֵיהּ בְּהַהוּא הֵיכָלָא. בְּקַדְמִיתָא אִתְפְּתָּחוּ תַּרְעִין, וְחַד מַפְתְּחָא סְתִימָא, אַתְקִין וּפָתַח תַּרְעָא חַד, לִסְטַר דָּרוֹם, כְּדֵין עָאל כַּהֲנָא רַבָּא בְּהַהוּא פִּתְחָא, וְאִזְדְּרָז בְּהֵימְיֶינוֹי, וְתִקּוּנוֹי. וְאִתְעַטָּר בְּעִטְרָא דִּקְדוּשָּׁה וּלְבִישׁ חוֹשְׁנָא וְאֱפוֹדָא, וּמְעִילָא דְּשִׁבְעִין זָגִין וְרִמּוֹנִין, דְּאִינּוּן (שמות כ״ח:ל״ד) פַּעֲמוֹן זָהָב וְרִמּוֹן. וְצִיץ נִזְרָא דְּקוּדְשָׁא עַל מִצְחֵיהּ, דְּאִתְקְרֵי צִיץ נֶזֶר הַקֹּדֶשׁ, וְאִתְקְשַׁט בְּד' בִּגְדֵי זָהָב, וּבְד' בִּגְדֵי לָבָן. וְעַל הַהוּא צִיץ מ\"ב אַתְוָון מְלַהֲטָן בֵּיהּ, וּמְנַצְּצָן עָלֵיהּ, וְנָהִיר כָּל הַהוּא הֵיכָלָא בִּנְהוֹרִין עִלָּאִין. (רעיא מהימנא אסתחר ההוא היכלא לקמן וכו')</p>\n<p>אִסְתְּחַר הַהוּא מַפְתְּחָא, וּפָתַח סִטְרָא אַחֲרָא דְּבִסְטַר צָפוֹן, כְּדֵין עָאל לֵוִי, מַעְשֵׂרָא דְּיַעֲקֹב, דְּאַפְרִישׁ לְּקוּדְשָׁא בְּרִיךְ הוּא. וְכִנּוֹר דְּעֶשֶׂר נִימִין עִמֵּיהּ, וְאִתְעַטָּר בְּעִטְרוֹי, וּכְדֵין אִסְתְּחָר מַפְתְּחָא, וּפָתַח בְּהַהוּא הֵיכָלָא חַד תַּרְעָא, הַהוּא תַּרְעָא דְּקַיְּימָא בְּאֶמְצָעִיתָא, עַמּוּדָא דְּלִסְטַר מִזְרָח <Nonei></i>עָאל וְאִתְעַטָּר בְּשִׁבְעִין עִטְרִין, וְאִתְעַטָּר בְּאַרְבַּע אַתְוָון, דְּאִינּוּן תְּרֵיסָר. וְאִתְעַטָּר בְּגִלּוּפִין דְּמָאתָן וְע' אֶלֶף עָלְמִין, וְאִתְעַטָּר בְּעִטְרִין דְּסַיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא, בְּכַמָּה לְבוּשֵׁי יְקָר, בְּכַמָּה עִטְרִין קַדִּישִׁין.</p>\n<p>אִסְתְּחַר הַהוּא מַפְתְּחָא, וּפָתַח לֵיהּ כָּל תַּרְעִין גְּנִיזִין, וְכָל תַּרְעִין דִּקְדּוּשִׁין טְמִירִין, וְאִתְקַדָּשׁ בְּהוּ, וְקַיְּימָא תַּמָּן כְּמַלְכָּא. מִתְבְּרָךְ בְּכַמָּה בִּרְכָאן, מִתְעַטֵּר בְּכַמָּה עִטְרִין. כְּדֵין נַפְקֵי כֻּלְּהוּ בְּחִבּוּרָא חֲדָא, מִתְעַטְּרָן בְּעִטְרַיְיהוּ כַּדְּקָא יָאוּת. כֵּיוָן דְּנַפְקֵי אִתְּעַר לֵיהּ בְּקִשׁוּטוֹי.</p>\n<p>וְהַאי חַיָּה אִתְּעָרָא, וְאַזְעִירַת גַּרְמָהּ, מִגּוֹ רְחִימוּ דְּשִׁירָתָא, הֵיךְ אַזְעָרַת גַּרְמָהּ מִגּוֹ רְחִימוּ דְּשִׁירָתָא, אַזְעָרַת גַּרְמָהּ זְעֵיר זְעֵיר, עַד דְּאִתְעָבֵידַת נְקוּדָּה חֲדָא. כֵּיוָן דְּאִיהִי אַזְעִירַת גַּרְמָהּ, (בשירתא) כְּדֵין כְּתִיב, (שמות ב׳:א׳) וַיֵּלֶךְ אִישׁ מִבֵּית לֵוִי וַיִּקַּח אֶת בַּת לֵוִי. בַּת לֵוִי וַדַּאי, מִסִּטְרָא דִּשְׂמָאלָא. הֵיאַךְ אָחִיד לָהּ. אוֹשִׁיט שְׂמָאלָא תְּחוֹת רֵישַׁהּ מִגּוֹ חֲבִיבוּ.</p>\n<p>וְאִי תֵּימָא, כֵּיוָן דְּאִיהִי נְקוּדָּה חֲדָא, אֵיךְ יָכִיל לְאַחֲדָא בִּנְקוּדָּה זְעֵירָא. אֶלָּא לְגַבֵּי עֵילָּא, כָּל מַה דְּהוּא מִלָּה זְעֵירָא, דָּא תּוּשְׁבַּחְתָּא, וְדָא עִלּוּיָיא וְרַב בִּרְבוּ עִלָּאָה. מִיַּד כַּהֲנָא רַבָּא אִתְּעַר לָהּ, וְאָחִיד לָהּ, וְחָבִיק לָהּ, דְּאִלוּ הֲוַות רַבְרְבָא, לָא יַכְלִין לְאַחֲדָא כְּלַל. אֲבָל כֵּיוָן דְּאַזְעִירַת גַּרְמָהּ, וְאִיהִי נְקוּדָּה חֲדָא, כְּדֵין אֲחָדִין בָּהּ, וְסַלְּקִין לָהּ לְעֵילָּא, כֵּיוָן דְּסַלְּקִין לָהּ, וְיָתְבָא בֵּין תְּרֵין סִטְרִין אִלֵּין, כְּדֵין הַהוּא עַמּוּדָא דְּקַיְּימָא בְּאֶמְצָעִיתָא, אִתְחַבָּר בַּהֲדָהּ בְּחָבִיבוּ דִּנְשִׁיקִין, בִּרְחִימוּ דְּחִבּוּרָא חֲדָא. כְּדֵין (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, בִּרְחִימוּ דְּנְשִׁיקִין מִתְדַּבְּקָן דָּא בְּדָא, בְּלָא פִּרוּדָא, עַד דְּנַקְטָא נַפְשָׁא דְּעִנּוּגִין כַּדְּקָא יָאוּת.</p>\n<p>בְּשַׁעֲתָא דְּנַקְטָא נַפְשָׁא דְּעִנּוּגִין כַּדְּקָא יָאוּת, וּבַעְיָא לְפַקְדָּא לְחֵילָהָא, מִתְכַּנְּשִׁין כֻּלְּהוּ, וְקַרְיָין לָהּ מִגּוֹ הֵיכָלָא קַדִּישָׁא, כָּבוֹד כָּבוֹד כָּבוֹד. בְּהֵיכָלָא קַדִּישָׁא אַבָּא וְאִמָּא, פַּתְחֵי וְאַמְרֵי מְקוּדָּשׁ מְקוּדָּשׁ. כְּדֵין יַרְחָא אִתְקַדָשׁ כַּדְּקָא יָאוּת. וּכְדֵין כְּתִיב, וּבַחֹדֶשׁ הָרִאשׁוֹן, רִאשׁוֹן ודַּאי, וְעַל דָּא מִשְׁכוּ וְגוֹ'. וְעַל דָּא בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה, דְּאִתְחַבָּר סִיהֲרָא בְּשִׁמְשָׁא, וּמַה דַּהֲוַת (נקטא) נְקוּדָּה חֲדָא, כַּד נַחְתָּא אִתְפְּשָׁט זְעֵיר זְעֵיר, וְאִתְמַלְּיָיא, וְאִתְעָבִידַת ה', מַלְיָיא מִכָּל סִטְרִין, מִתְקַדְּשָׁא כַּדְּקָא יָאוּת.</p>\n<p><Noneb>רעיא מהימנא</b> <Nonei></i>אִסְתְּחַר הַהוּא הֵיכָלָא, וּפָתַח תַּרְעָא אַחֲרָא דִּסְטָר דָּרוֹם (ד\"א צפון) בְּשִׁבְעִין וּתְרֵין עִטְרִין. לְבָתַר אַפְתַּח תַּרְעָא תְּלִיתָאָה, לִסְטַר מִזְרָח, בְּחַמְשִׁין (ותרין) נְהוֹרִין, דְּחַמְשִׁין תַּרְעִין דְּבִינָה. לְבָתַר אַפְתַּח תַּרְעָא אַחֲרָא דְּלִסְטַר צָפוֹן (ד\"א מערב), בְּע\"ב עִטְרִין, וְכֻלְּהוּ רמ\"ח בְּחוּשְׁבַּן תֵּיבִין דְּפָרְשִׁיָין דִּקְרִיאַת שְׁמַע. וּמַה דִּבְקַדְמֵיתָא הַהִיא חַיָּה הֲוַת זְעֵירָא, בְּהַהוּא זִמְנָא אִתְרְבִיאַת, הֲדָא הוּא דִּכְתִּיב, (ישעיהו ו׳:ג׳) מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ, דְּאִיהוּ כָּבוֹד עִלָּאָה וְתַתָּאָה.</p>\n<p>כַּד מָטֵי לְחַ\"י עָלְמִין, דְּבֵיהּ ח\"י בִּרְכָאן דִּצְלוֹתָא, וּפָתַח בֵּיהּ (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ. כְּדֵין עַמּוּדָא דְּאֶמְצָעִיתָא, אִתְחַבָּר בַּהֲדָהּ בְּחָבִיבוּ דְּנְשִׁיקִין דְּשִׂפְוָון, וְאִינּוּן נֶצַח וְהוֹד, דְּלָשׁוֹן אִיהוּ צַדִּיק בֵּינַיְיהוּ. לְשׁוֹן לִמוּדִים בְּהַהוּא זִמְנָא, (בראשית כ״ט:י״א) וַיִּשַּׁק יַעֲקֹב לְרָחֵל, כְּדֵין קָרָאן לְהַהִיא חַיָּה כָּבוֹד כְּבוֹד אַבָּא וְאִימָּא, מְקוּדָּשׁ מְקוּדָּשׁ. כְּדֵין יַרְחָא אִתְקַדְּשָׁא כַּדְּקָא יָאוּת, כְּדֵין וּבַחֹדֶשׁ הָרִאשׁוֹן רִאשׁוֹן וַדַּאי.</p>\n<p>וּכְדֵין מִשְׁכוּ. וְעַל דָּא בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה, דְּאִתְחַבָּר סִיהֲרָא קַדִּישָׁא בְּשִׁמְשָׁא. דְּאִתְּמַר בֵּיהּ, (תהילים פ״ד:י״ב) כִּי שֶׁמֶשׁ וּמָגֵן יְיָ אֱלֹהִים (צבאות). וּמַה דַּהֲוַת נְקוּדָה זְעֵירָא, (ס\"א כגוונא דא) אִתְמַלְּאַת בְּסִיהֲרָא, וּכְדֵין אִיהִי הַחֹדֶשׁ מָלֵא. <Nonei></i>וְסִיהֲרָא אִתְמַלְּיָיא כְּגַוְונָא דָּא. מָלֵא כָּל הָאָרֶץ כְּבוֹדוֹ. בְּקַדְמִיתָא חָסֵר, וּכְעַן בִּשְׁלִימוּ. (ע\"כ רעיא מהימנא) (ר' חייא פתח וכו')</p>\n<p>רִבִּי חִיָּיא פָּתַח, בְּאַרְבָּעָה עָשָׂר יוֹם לַחֹדֶשׁ פֶּסַח וְגוֹ'. אִימְרָא דְּאִיהוּ פִּסְחָא אֲמַאי. אֶלָּא דַּחֲלָא דְּמִצְרָאֵי, וְאֱלָהָא דִּלְהוֹן, הֲוָה אִמְרָא. בְּגִין דְּמִצְרָאֵי פַּלְחִין לְמַזַּל טָלֶה, וּבְגִין כָּךְ פַּלְחִין לְאִימְרָא. תָּא חֲזֵי, כְּתִיב (שמות ח׳:כ״ב) הֵן נִזְבַּח אֶת תּוֹעֲבַת מִצְרַיִם. מַאי תּוֹעֲבַת מִצְרַיִם. וְכִי עַל דְּשַׂנְאִין לֵיהּ, כְּתִיב תּוֹעֲבַת מִצְרַיִם. אֶלָּא דַּחֲלָא דְּמִצְרָאֵי, וְאֱלָהָא דִּילְהוֹן, אִקְרֵי תּוֹעֲבַת מִצְרַיִם. כְּמָה דִּכְתִּיב, (דברים י״ח:ט׳) כְּתוֹעֲבֹת הַגּוֹיִם, דַּחֲלָא דִּשְׁאַר עַמִּין.</p>\n<p>תָּא חֲזֵי חָכְמְתָא דְּיוֹסֵף, דִּכְתִּיב, (בראשית מ״ז:ב׳) וּמִקְצֵה אֶחָיו לָקַח חֲמִשָּׁה אֲנָשִׁים, וְאוֹלִיף לוֹן לְמֵימַר, אַנְשֵׁי מִקְנֶה הָיוּ עֲבָדֶיךָ. וְכִי מַלְכָּא דְּהֲוָה שַׁלִּיט עַל כָּל אַרְעָא, וְאַבָּא לְמַלְכָּא, עָבִיד כְּדָּא, וְעָבִיד לַאֲחוֹי דְּיִשְׂנְאוּן <Nonei></i>לְהוֹן, וְלָא יַחְשְׁבוּן לְהוֹן. (למעבד להון רועי צאן) אֶלָּא וַדַּאי תּוֹעֲבַת מִצְרַיִם, דַּחֲלָא וְאֱלָהָא דִּילְהוֹן אִקְרֵי הָכִי, וְעַל דָּא כְּתִיב, (שמות ח׳:כ״ב) הֵן נִזְבַּח אֶת תּוֹעֲבַת מִצְרַיִם.</p>\n<p>אָמַר יוֹסֵף, כָּל (בראשית מז) מֵיטַב מִצְרַיִם הִיא אֶרֶץ רַעְמְסֵס, וְהַהִיא אַרְעָא אַפְרִישׁוּ לְדַחֲלָא דִּלְהוֹן, לְרַעְיָא וּלְמֵיהַךְ בְּכָל עִנּוּגִין דְּעָלְמָא. וְכָל מִצְרָאֵי חָשִׁיבוּ לְאִינּוּן דְּרָעָאן לְדַחֲלֵיהוֹן, כְּדַחֲלֵיהוֹן. אַעֲבִיד לְאַחַי דְּיַרְתּוּן הַהִיא אַרְעָא, וְיִסְגְּדוּן לוֹן מִצְרָאֵי, וְיַחְשְׁבוּן לוֹן כַּדְּקָא יָאוּת. וְהַיְינוּ דִּכְתִּיב, (בראשית מ״ז:ג׳) כִּי תּוֹעֲבַת מִצְרַיִם כָּל רוֹעֵה צֹאן, מְחַשְּׁבִין לוֹן כְּדַחֲלֵיהוֹן.</p>\n<p>אָמַר רִבִּי יוֹסֵי, וְהָא תָּנֵינָן כְּמָה דְּאִתְפְּרַע קוּדְשָׁא בְּרִיךְ הוּא מֵאִינּוּן דְּפַלְחֵי לְעֲבוֹדָה זָרָה, הָכִי אִתְפְּרַע מֵעֲבוֹדָה זָרָה מַמָּשׁ, וְכִי יוֹסֵף עָבִיד לַאַחוֹי עֲבוֹדָה זָרָה. אָמַר לֵיהּ, לָא עָבִיד יוֹסֵף לַאַחוֹי עֲבוֹדָה זָרָה, אֶלָּא עָבִיד לוֹן לְשַׁלְּטָאָה עַל עֲבוֹדָה זָרָה דִּילְהוֹן, וּלְאַכְפְּיָא עֲבוֹדָה זָרָה דִּילְהוֹן תְּחוֹת יְדַיְיהוּ, וּלְרַדָּאָה לוֹן בַּמַּקֵּל. (אמר רעיא מהימנא כגון, בסוף דף שקודם זה) אָמַר יוֹסֵף, אִי יִשְׁלְטוּן אַחַי עַל עֲבוֹדָה זָרָה דִּילְהוֹן, כָּל שֶׁכֵּן דְּיִשְׁלְטוּן עַל גַּרְמַיְיהוּ, וּבְגִין כָּךְ אוֹתִיב לוֹן בְּמֵיטַב אַרְעָא, וְאַשְׁלִיט לוֹן עַל כָּל אַרְעָא.</p>\n<p>וְעַל דָּא אִמְרָא דְּאִיהוּ פֶּסַח אֲמַאי. אֶלָּא דַּחֲלָא דְּמִצְרָאֵי, וְאֱלָהָא דִּילְהוֹן הֲוָה אִימְרָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִבְּעָשׂוֹר לַחֹדֶשׁ סִיבוּ דַּחֲלָא דִּילְהוֹן דְּמִצְרָאֵי, וְתִפְשׂוּ לֵיהּ, וִיהֵא אָסוּר וְתָפִישׂ בִּתְפִישָׂה דִּילְכוֹן, יוֹמָא חַד וּתְרֵין וְג', וּבְיוֹמָא ד', אַפִּיקוּ לֵיהּ לְדִינָא, וְאִתְכְּנָשׁוּ עָלֵיהּ.</p>\n<p>וּבְשַׁעֲתָא דְּמִצְרָאֵי הֲווֹ שַׁמְעִין קָל דַּחֲלָא דִּילְהוֹן, דְּתָפִישׂ בִּתְפִישָׂה דְּיִשְׂרָאֵל, וְלָא יַכְלִין לְשֵׁזָבָא לֵיהּ, הֲווֹ בָּכָאן, וַהֲוָה קַשְׁיָא עָלַיְיהוּ, כְּאִילּוּ גַּרְמַיְיהוּ אִתְעֲקִידוּ לְקָטְלָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יִהְיֶה תָּפִישׂ בִּרְשׁוּתַיְיכוּ, יוֹמָא בָּתַר יוֹמָא, אַרְבָּעָה יוֹמִין, בְּגִין דִּיֶחמוּן יָתֵיהּ תָּפִישׂ, וּבְיוֹמָא רְבִיעָאָה אַפִּיקוּ לֵיהּ לְקָטְלָא, וְיֶיחמוּן לֵיהּ מִצְרָאֵי הֵיךְ אַתּוּן עַבְדִּין בֵּיהּ דִּינָא, וְדָא קַשְׁיָא לְהוּ מִן כָּל מַכְתְּשֵׁי דְּעָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִינּוּן דִּינִין דְּיַעַבְדוּן בְּדַחֲלֵיהוֹן.</p>\n<p>לְבָתַר דַּיְינִין לֵיהּ <Nonei></i>בְּנוּרָא, דִּכְתִּיב, (דברים ז׳:כ״ה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַל תֹּאכְלוּ מִמֶּנּוּ נָא. דְּלָא יֵימְרוּן בִּרְעוּתָא וּבְתִּיאוּבְתָּא דְּדָחַלְנָא, אַכְלִין לֵיהּ הָכִי. אֶלָּא אַתְקִינוּ לֵיהּ צָלִי, וְלֹא מְבוּשָׁל, דְּאִלוּ מְבוּשָׁל יְהֵא טָמִיר, וְלָא יֶחמוּן לֵיהּ, אֶלָּא תִּקּוּנָא דִּילֵיהּ דְּיֶחֱמוּן לֵיהּ הָכִי מוֹקְדָא בְּנוּרָא, בְּגִין דְּרֵיחֵיהּ נוֹדֵף.</p>\n<p>וְתוּ רֵישֵׁיהּ עָלֵיהּ כָּפוּף עַל קַרְסוּלוֹי, דְּלָא יֵימְרוּן דְּחַיָּה, אוֹ מִלָּה אַחֲרָא הוּא, אֶלָּא דְּיִשְׁתְּמוֹדְעוּן לֵיהּ, דְּאִיהוּ דַּחֲלָא דִּלְהוֹן. וְתוּ, דְּלָא יֵיכְלוּן לֵיהּ. בְּתִיאוּבְתָּא, אֶלָּא עַל שַׂבְעָא, אֹרַח קְלָנָא וּבִזָּיוֹן. וְתוּ, עֶצֶם לֹא תִשְׁבְּרוּ בוֹ, אֶלָּא דְּיֶחֱמוּן גַּרְמוֹי רָמָאן בְּשׁוּקָא, וְלָא יֵיכְלוּן לְשֵׁזָבָא לֵיהּ. וְעַל דָּא כְּתִיב, (במדבר ל״ג:ד׳) וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים. דִּינִין סַגִּיאִין. תּוּ וּמַקֶּלְכֶם בְּיֶדְכֶם, וְלָא חַרְבָּא וְרוֹמְחָא וּשְׁאַר מָאנֵי קְרָבָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, הָא אוֹקְמוּהָ, דְּמִצְרָאֵי פַּלְחֵי לְמַזָּל טָלֶה, וּבְגִין כָּךְ פַּלְחִין לְאִימְרָא. אָמַר רִבִּי יוֹסֵי, אִי הָכִי, טָלֶה יִפְלְחוּן, וְלָא אִימְרָא. אָמַר לֵיהּ, כֹּלָּא פַּלְחִין, אֶלָּא מַזָּל טָלֶה נָחִית וְסָלִיק בְּטָלֶה וְאִימְרָא, וּבְגִין כָּךְ פַּלְחִין לְכֹלָּא. אָמַר לֵיהּ הָכִי שְׁמַעְנָא, דְּכָל בְּעִירָא רַבָּא (ס\"א דצאן) דַּחֲלָא דִּלְהוֹן הֲוָה, וְעַל דָּא קָטִיל קוּדְשָׁא בְּרִיךְ הוּא כָּל בְּכוֹר בְּהֵמָה. וְהָא אִתְּמַר דְּאִלֵּין אִינּוּן דַּרְגִּין דִּלְעֵילָּא, דְּאִקְרוּן הָכִי.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, כְּתִיב (שמות י״ב:כ׳) כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ, וּכְתִיב (שמות י״ג:ג׳) לֹא יֵאָכֵל חָמֵץ. אֶלָּא דָּא דְּכַר, וְדָא נוּקְבָּא. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, בְּדָא (זה שייך ברעיא מהימנא אחר קרבנא) כְּתִיב לֹא תֹּאכֵלוּ, וּבְדָא כְּתִיב לֹא יֵאָכֵל, אֲמַאי לָא כְּתִיב לֹא תֹּאכְלוּ. אֶלָּא, נוּקְבָּא דְּאִיהִי אַסְטִיאַת אָרְחָהָא, בְּאַזְהָרָה ודַּאי, דְּכַר דְּאִיהוּ אָחִיד בְּחוּטָא דְּדַכְיוּ יַתִּיר, בְּבַקָּשָׁה. וְעַל דָּא כְּתִיב, לֹא יֵאָכֵל, לֹא תֹאכֵלוּ.</p>\n<p>אָמַר לֵיהּ אַבָּא, וְהָא כְּתִיב (דברים ט״ז:ג׳) לֹא תֹאכַל עָלָיו חָמֵץ. אָמַר לֵיהּ, אַסְגֵּי תָּבִין יְתֵירִין לִיקָרָא לְקָרְבְּנָא. אֲבָל בְּקַדְמִיתָא בְּבַקָּשָׁה לֹא יֵאָכֵל. אֲבָל לְבָתַר בְּאַזְהָרָה, לֹא תֹּאכְלוּ, דְּהוּא קַשְׁיָא מִתַּרְוַויְיהוּ. מַחְמֶצֶת מַאי טַעְמָא. בְּגִין דְּרֵיחָא דְּמוֹתָא אִית תַּמָּן. חָמֵץ, דְּכַר. מַחְמֶצֶת, נוּקְבָּא. (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוְת, בְּרֵישָׁא וְסֵיפָא דְּתֵיבָה, תִּשְׁכַּח לָהּ. וּבְגִין דָּא מַאן דְּאָכִיל חָמֵץ בַּפֶּסַח, אִיהוּ אַקְדִּימַת לֵיהּ מוֹתָא, וְלִינְדַע דְּמִית הוּא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, כְּתִיב (שמות י״ב:ט״ו) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא.</p>\n<p>מַצָּה, אֲמַאי (ס\"א אתקריאת מצה). אֶלָּא הָכִי תָּנֵינָן, שַׁדַּי: בְּגִין דְּאָמַר לְעוֹלָמוֹ דַּי, דְּיֹאמַר לְצָרוֹתֵינוּ דַּי. אוּף הָכִי מַצָּה, בְּגִין דְּקָא מְשַׁדֵּד דְּמַבְרָחַת לְכָל סִטְרִין בִּישִׁין, וְעָבִיד קְטָטָה בְּהוּ, כְּגַוְונָא דְּשַׁדַּי דִּמְזוּזָה, דְּמַבְרִיחַ לְשֵׁדִים וּמַזִּיקִים דְּתַרְעָא, אוּף הָכִי אִיהִי מַבְרָחַת לוֹן מִכָּל מִשְׁכְּנֵי קְדוּשָּׁה, וְעָבִיד מְרִיבָה וּקְטָטָה בְּהוּ. כְּמָה דְאַתְּ אָמֵר, (שמות י״ז:ז׳) מַסָּה וּמְרִיבָה. עַל דָּא כְּתִיב מַצָּה. וְהָא מַסָּה בְּסָמֶךְ אִיהוּ. אֶלָּא תַּרְגּוּמוֹ דְּמַסָּה, אִיהוּ מָצוּתָא.</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, כְּגוֹן לִישָׁנָא דְּאִיהוּ מַקֵּל לְכָל אַנְשֵׁי בֵּיתֵיהּ, וְאִיהוּ לִישָׁנָא דְּאָת ו', וְאִיהוּ מַטֵה דְּבֵיהּ עֶשֶׂר אוֹתִיוֹת, וּבֵיהּ מָחָא קוּדְשָׁא בְּרִיךְ הוּא עַל יְדוֹי י' מָחָאן. וּבְגִין דְּכָל מָחָאן הֲווֹ מִסִּטְרָא דְּה' ה', רִבִּי עֲקִיבָא אוֹמֵר, מִנַּיִן שֶׁכָּל מַכָּה וּמַכָּה שֶׁהֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַמִּצְּרִים בְּמִצְּרַיִם הָיְתָה שֶׁל חָמֵשׁ מַכּוֹת וְכוּ', אֱמוֹר מֵעַתָּה וְכוּ'. וְאָת ה' סַלְּקָא בְּאָת י' לְחַמְשִׁין מָחָאן, חָמֵשׁ זִמְנִין חַמְשִׁין, אִינּוּן ר\"ן. וּבְגִין דָּא, וְעַל הַיָּם לָקוּ ר\"ן מַכּוֹת.</p>\n<p>אמר יוסף, כל מיטב ארץ מצרים רעמסס היא, וההיא ארעא אפרישו לדחלן דלהון, לרעיא ולמיהך בכל ענוגין דעלמא. וכל מצראי חשיבון לאינון דרען <Nonei></i>לדחליהון, כדחליהון. ודא שאיל יוסף מפרעה, לשלטאה אחוי על דחלן דמצראי, דאתכפיין תחות ידיה, כעבדים בתר מלכיהון, למהוי כלהו מתכפיין תחות שם יי מסטריהון, ולא שליט בעלמא אלא שם יהוה. ואתכפיין כל ממנן תחות ידיה.</p>\n<p>ולאחזאה לון, דאיהו עתיד לאיתפרעא מנהון, הדא הוא דכתיב, (שמות י״ב:י״ב) ובכל אלהי מצרים אעשה שפטים אני יהוה. כד מטעיין לבריין ועבדין גרמייהו אלוהות. ובגין דטלה ממנא דיליה, איהו רב על כל ממנן דאלהים אחרים, מני קדשא בריך הוא לישראל, (שמות י״ב:ג׳) ויקחו להם איש שה לבית אבות שה לבית, ואשליט לון עליה, ותפשי ליה, תפיש בתפישה דלהון יומא ותרין ותלת. ולבתר דא אפיקו ליה לדינא לעיני כל מצראי, לאחזאה דאלהא דלהון ברשו דישראל למעבד ביה דינא.</p>\n<p>בגין דא, (שמות י״ב:ט׳) אל תאכלו ממנו נא ובשל מבשל במים כי אם צלי אש ראשו על כרעיו ועל קרבו, למהוי דן באש צלי, ומני לזרקא לגרמיה דיליה בשוקא בבזוי. ובגין דא, (שמות י״ב:מ״ו) ועצם לא תשברו בו. ומני ליומא רביעאה, בתר דהוה תפיש ג' יומין קשור, למעבד ביה דינא. ודא קשיא לון מכל מכתשין דמחא לון קדשא בריך הוא, על ידא דרעיא מהימנא. ולא עוד, אלא דמני דלא למיכל ליה בתיאובתא. ומיד דחמאן גרמוי בשוקא, ולא יכלין לשזבא ליה, דא קשיא לון מכלא. ולא עוד, אלא דאתמר בהו, (שמות י״ב:י״א) ומקלכם בידכם, לאתכפייא כל דחלן דמצראי, תחות ידייהו. ובגין דאינהו בכורות ממנן, כתיב (שמות י״ב:כ״ט) ויי הכה כל בכור.</p>\n<p>בָּתַר כָּל דָּא כְּתִיב, (דברים ט״ז:ג׳) לֹא יִאָכֵל חָמֵץ שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עוֹנִי. וּכְתִיב (שמות י״ב:כ׳) כָּל מַחְמֶצֶּת לֹא תֹאכֵלוּ. אָמַר רַעְיָא מְהֵימָנָא, אֲמַאי מָנֵי דְּלָא לְמֵיכַל חָמֵץ שִׁבְעַת יוֹמִין, וּלְמֵיכַל בְּהוֹן מַצָּה. וַאֲמַאי לֹא יִאָכֵל, וַאֲמַאי לֹא תֹּאכֵלוּ. אֶלָּא ז' כֹּכְבֵי לֶכֶת וְאִינּוּן: שצּ\"ם חנכ\"ל. וְאִינּוּן מִסִּטְרָא דְּטוֹב וָרָע, נְהוֹרָא דִּלְגוֹ מַצָּה. קְלִיפָה דִּלְבַר חָמֵץ. וְאִינּוּן חָמֵץ דְּכַר מַחְמֶצֶּת נוּקְבָּא.</p>\n<p>מַצָּה דִּלְגוֹ שְׁמוּרָה. וְאִינּוּן, (אסתר ב׳:ט׳) שֶׁבַע הַנְּעָרוֹת הָרְאוּיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. וְאִתְּמַר עָלַיְיהוּ, <Nonei></i>(שמות י״ב:י״ז) וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת. מַצָּה אִיהִי שְׁמוּרָה לְבַעְלָהּ, דְּאִיהוּ ו'. וּבֵיהּ אִתְעָבִיד מִצְּוָה.</p>\n<p>וּמַאן דְּנָטִיר לָהּ לְגַבֵּי יָהּ, דִּגְנִיזִין בְּמ\"ץ מִן מַצָּה, וְאִינּוּן. י\"ם ה\"ץ. וּמָנֵי קוּדְשָׁא בְּרִיךְ הוּא לְבָרֵךְ לָהּ שֶׁבַע בְּרָכוֹת לֵיל פֶּסַח, דְּאִינּוּן שֶׁבַע הַנְּעָרוֹת דִּילָהּ, שצּ\"ם חנכ\"ל. וּמָנֵי לְאַעְבְרָא מִנְּהוֹן חָמֵץ וּמַחְמֶצֶּת, דְּאִינּוּן עֲנָנִים חֲשׁוּכִין דִּמְכַסְּיָין עַל נְהוֹרִין, דְּשִׁבְעָה כֹּכְבֵי לֶכֶת, דְּאִתְּמַר בְּהוֹן (בראשית מ״א:כ״א) וַתָּבֹאנָה אֶל קִרְבֶּנָּה וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָּה וּמַרְאֵיהֶן רַע, חָשׁוּךְ כַּאֲשֶׁר בַּתְּחִלָּה. דְּכָל כַּךְ חֲשׁוֹכָא דַּעֲנָנִין דִּלְהוֹן, דְּלָא יַכְלִין נְהוֹרִין לְאַנְהָרָא לְהוֹן, וּבְגִין דָּא וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָה. (ע\"כ רעיא מהימנא).</p>"],[9520012614,"<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהילים ס״ח:ל״א) גְּעַר חַיַּת קָנֶה עֲדַת אַבִּירִים בְּעֶגְלֵי עַמִּים. גְּעַר חַיַּת, דָּא חַיָּה דְּאִתְאֲחָד בָּהּ עֵשָׂו. קָנֶה: תָּנֵינָן, דִּבְיוֹמָא דְּנָסַב שְׁלֹמֹה מַלְכָּא בַּת פַּרְעֹה, בָּא גַּבְרִיאֵל, נָעַץ קָנֶה בְּיַמָּא רַבָּא, וְעָלֵיהּ אִתְבְּנֵי קַרְתָּא דְּרוֹמִי. מַאי קָנֶה. דָּא דְּכוּרָא דְּהַאי חַיָּה <Nonei></i>בִּישָׁא, דְּאִית לֵיהּ סִטְרָא זְעֵירָא בְּאַחֲדוּתָא דִּקְדוּשָּׁה. וְדָא אִיהוּ קָנֶה, דְּנָעִיץ בְּיַמָּא רַבָּא. וּבְגִין כָּךְ אִיהִי שַׁלְטָא עַל עָלְמָא, וְעַל שׁוּלְטָנוּ דָּא כְּתִיב, (ישעיהו י״ט:ו׳) קָנֶה וָסוּף קָמֵלוּ. קָנֶה, שׁוּלְטָנוּתָא וְרֹאשׁ לְכָל מַלְכְּוָון. תּוּ קָנֶה, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְתַּבְרָא לֵיהּ כְּקָנֶה דָּא.</p>\n<p>תָּא חֲזֵי, בְּמִצְרַיִם אִיהִי שַׁלְטָא, וּמִנָהּ נַפְקוּ כַּמָה שֻׁלְטָנִין לְזִנַּיְיהוּ, וְכֹלָּא בְּרָזָא דְּחָמֵץ, כֵּיוָן דְּתָבַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, אַפִּיק חָמֵץ וְאָעִיל מַצָּה. בְּמָה. בְּחוּטָא זְעֵירָא מִכֹּלָּא, תָּבַר ח' חָמֵץ, וְאִתְעָבִיד מַצָּה. אִינּוּן אַתְוָון. אֶלָּא דְּתָבַר ח' דְּהַאי חַיָּה, דְּאִקְרֵי חָמֵץ. וְעַל דָּא אִקְרֵי חַיַּת קָנֶה, דְּנוֹחַ לְאַתְבְּרָא כְּקָנֶה דָּא. בְּמָה אִתְּבַּר. בְּחוּטָא זְעֵירָא כְּנִימָא, תָּבַר ח' וְאִתְעֲבָר מֵאֵיתָנָהּ, וַהֲוָה מַצָּה. וְעַל דָּא כְּתִיב, גְּעַר חַיַּת קָנֶה, גָּעַר בָּהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַתְּבַּר ח' חָמֵץ, וְאִתְעָבִיד ה'. (ס\"א ואתעבר ח' חמץ ואתאביד)</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא. לְתַּבְרָא לֵיהּ לְהַהוּא קָנֶה, כְּגַוְונָא דָּא, יַתְבָּר רַגְלֵיהּ דְּק' מִקָנֶה, וְיִשְׁתְּאַר הִנֵּה. (ישעיהו מ׳:י׳) הִנֵּה יְיָ אֱלֹהִים בְּחָזָק יָבֹא וּזְרוֹעוֹ מוֹשְׁלָה לוֹ הִנֵּה שְׂכָרוֹ אִתּוֹ וּפְעוּלָּתוֹ לְפָנָיו. מַאי וּפְעוּלָּתוֹ. דָּא פֹּעַל דְּהַהִיא ק' (ס\"א פעולה דההוא חמץ) דְּיַתְבַּר לָהּ, וְאִיהִי פְּעוּלָה לְפָנָיו, אִיהוּ יַעְבַּר רַגְלֵיהּ, וִיהֵא הִנֵּה (ישעיהו מ״א:כ״ז) רִאשׁוֹן לְצִיּוֹן הִנֵּה הִנָּם וְגוֹ'.</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, גְּעַר חַיַּת קָנֶה עֲדַת אַבִּירִים בְּעֶגְלֵי עַמִּים. גְּעַר חַיַּת קָנֶה, דָּא קָנֶה דְּאִתְאֲחָד בֵּיהּ עֵשָׂו, דְּאִיהִי קַרְתָּא דְּרוֹמִי רַבְּתָא, דְּנָעַץ גַּבְרִיאֵל קָנֶה בְּיַמָּא רַבָּא, וּבָנוּ עָלֶיהָ כְּרָךְ גָּדוֹל דְּרוֹמִי. קָנֶה דְּחָמֵץ. וְכַד יִיתֵי פּוּרְקָנָא לְיִשְׂרָאֵל, יִתְבַּר לֵיהּ. <Nonei></i>הֲדָא הוּא דִכְתִיב גְּעַר חַיַּת קָנֶה עֲדַת. וּמִתְעַבָּר מִיַּד חָמֵץ מֵעָלְמָא. מַחְמֶצֶּת דִּילֵיהּ רוֹמִי. וְיִתְגַּלְיָּא מַצָּה בְּעָלְמָא, דְּאִיהִי בֵּי מַקְדְּשָׁא דְּבַיִת רִאשׁוֹן וּבַיִת שֵׁנִי.</p>\n<p>אָמַר בּוּצִּינָא קַדִּישָׁא (ס\"א רעיא מהימנא), דְּאִינּוּן לָקֳבֵל בַּת עַיִן יָמִין, וּבַת עַיִן שְׂמֹאל. וְאִינּוּן לָקֳבֵל (לחם משנה) רוֹמִי רַבָּתִי, רוֹמִי זְעֵירָא. לָקֳבֵל תְּרֵין עֲנָנִין, דִּמְכַּסְּיָין עַל בַּת עֵינָא יְמִינָא וּשְׂמָאלָא. וְאִינּוּן לָקֳבֵל שְׂאוֹר וְחָמֵץ. וְעַד דְּאִלֵּין יִתְבַּעֲרוּן מֵעָלְמָא בַּל יִרָאֶה וּבַל יִמָּצֵּא חַד מִנַּיְיהוּ, בַּיִת רִאשׁוֹן וְשֵׁנִי לָא יִתְגַּלְיָין בְּעָלְמָא.</p>\n<p>וְאַסְוָותָא דַּעֲנָנָא עֵינָא, דְּאַחֲשִׁיךְ לְבַת עֵינָא יָמִין וּשְׂמֹאל, מַה יְהֵא אַסְוָותָא דִּלְהוֹן. מָרָה דְּעֶגְלָא. וְהַיְינוּ (ישעיהו כ״ז:י׳) שָׁם יִרְעֶה עֵגֶל וְשָׁם יִרְבָּץ. שָׁם יִרְעֶה עֵגֶל, דָּא מָשִׁיחַ בֶּן יוֹסֵף, דְּאִתְּמַר בֵּיהּ (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. וְשָׁם יִרְבָּץ, דָּא מָשִׁיחַ בֶּן דָּוִד. חַד אַעְבָּר רוֹמִי רַבָּתִי. וְחַד אַעְבָּר רוֹמִי זְעֵירְתָּא. וְגַבְרִיאֵ\"ל דְּמִיכָאֵל לָקֳּבְלַיְיהוּ אִינּוּן.</p>\n<p>וּבְגִין דָּא ח', דְּאִיהוּ חוּטָא זְעֵירָא, תָּבַר לָהּ, וְיֵיעוּל ה' בְּאַתְרָהָא. דִּבְקַדְמֵיתָא קָנֶה וָסוּף קָמֵלוּ. קָנֶה שֻׁלְטָנוּתָא דְּרוֹמִי, וָסוּף לְכָל מַלְכִין, דְּעָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְתַּבְרָא לֵיהּ. גְּעַר חַיַּת קָנֶה, גְּעַר חַיָּה בִּישָׁא, ח' מִן חָמֵץ, וְאַתְבַּר רַגְלֵיהּ מִן מַחְמֶצֶּת, דְּאִתְּמַר בָּהּ (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוְת. וְעוֹד גְּעַר חַיַּת קָנֶה, יַתְבַּר רֶגֶל קוֹף מִן קָנֶה, וְיִשְׁתְּאַר הִנֵּה. מִיָּד הִנֵּה יְיָ אֱלֹהִים בְּחָזָק יָבֹא, (ישעיהו מ״א:כ״ז) רִאשׁוֹן לְצִּיּוֹן הִנֵּה הִנָּם וְלִיְרוּשָׁלַם מְבַשֵּׂר אֶתֵּן. הִנֵּה: ס' בָּתַר אֶלֶף וּמָאתָן.</p>"],[9520012615,"<p>וְאָמַר (שמות מט) בּוּצִּינָא קַדִּישָׁא, (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב שִׁשִּׁים וָשֵׁשׁ. שִׁשִּׁים, לְאַתְעָרוּתָא דְּמָשִׁיחַ רִאשׁוֹן. וָשֵׁשׁ, לְאַתְעָרוּתָא דְּמָשִׁיחַ שֵׁנִי. אִשְׁתָּאֲרוּ ו' שָׁנִים לְע\"ב, לְקַיֵּים בְּהוּ, (ויקרא כ״ה:ג׳) שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךָ וְשֵׁשׁ שָׁנִים תִּזְמוֹר כַּרְמֶךָ וְאָסַפְתָּ אֶת תְּבוּאָתָהּ, דְּאִתְּמַר (ירמיהו ב׳:ג׳) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ רֵאשִׁית תְּבוּאָתֹה.</p>\n<p>אִם כֵּן, מַה כְּתִיב לְעֵיל (ירמיהו ל״א:ז׳) רָנוּ לְיַעֲקֹב שִׂמְחָה. אֶלָּא אַרְבַּע גְּאוּלוֹת עֲתִידִין לְמֶהֱוִי, לָקֳבֵל אַרְבַּע כּוֹסוֹת דְּפֶסַח. בְּגִין דְּיִשְׂרָאֵל מְפוּזָרִין בְּאַרְבַּע פִּנּוֹת עָלְמָא, וְאִינּוּן דִּיהוֹן רְחוֹקִין מֵאוּמִין, אַקְדִּימוּ לְרָנוּ. וְתִנְיָינִין, לְשִׁתִּין. וּתְלִיתָאִין, לְשִׁתִּין וְשִׁית. וּרְבִיעָאִין לְע\"ב.</p>\n<p>וּפוּרְקָנִין אִלֵּין, יִהוֹן בְּאַרְבַּע חֵיוָן, בְּשֵׁם יְדוָֹד דְּרָכִיב עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, (חבקוק ג׳:ח׳-ט׳) כִּי תִרְכַּב עַל סוּסֶךָ מַרְכְּבוֹתֶיךָ יְשׁוּעָה. דְּלָקֳבְלַיְיהוּ, יִתְּעַר לְתַתָּא אַרְבַּע דְּגָלִין, וּתְרֵיסָר שְׁבָטִין. בְּרָזָא דַּיְדוָֹד מֶלֶךְ, יְדוָֹד מָלָךְ, (שמות ט״ו:י״ח) יְדוָֹד יִמְלוֹךְ לְעוֹלָם וָעֶד. תְּרֵיסָר אַתְוָון אִינּוּן, לָקֳבֵל תְּרֵיסָר שְׁבָטִין, וְי\"ב אַנְפִּין דִּתְלַת אֲבָהָן, דְּאִתְּמַר עָלַיְיהוּ הָאָבוֹת הֵן הֵן הַמֶרְכָּבָה. וְאִינּוּן עֶשֶׂר שְׁבָטִין, אֶלֶף שְׁנִין. תְּרֵין שְׁבָטִין, מָאתָן שְׁנִין. וּמִּי\"ב אַתְוָון, תַּלְיָין ע\"ב שְׁמָהָן, דְּאִינּוּן ע\"ב שְׁנִין, בָּתַר אֶלֶף וּמָאתָן.</p>\n<p>וְאִינּוּן כ\"ד, לְכָל חַיָּה מִתְּלַת חֵיוָן. כ\"ד רָזָא דִּילֵיהּ, (ישעיה ו) וְקָרָא זְה אֶל זֶה וְאָמַר. וְאִינּוּן תְּלַת כִּתּוֹת, מִן כ\"ד צּוּרוֹת. כַּת אַחַת אוֹמֶרֶת קָדוֹשׁ, וְכַת תִּנְיָינָא אוֹמֶרֶת קָדוֹשׁ, וְכַת תְּלִיתָאָה אוֹמֶרֶת קָדוֹשׁ. מִיַּד אִתְּעַר שְׂמָאלָא בְּמ\"ב אַתְוָון, דְּעָבַד דִּינָא בַּעֲמָלֵק.</p>"],[9520012616,"<p>(דברים כ״ב:ו׳) כִּי יִקָּרֵא קַן צִּפּוֹר לְפָנֶיךָ בַּדֶּרֶךְ מָארֵי מִקְרָא. בְּכָל עֵץ, מָארֵי מִשְׁנָה. דְּאִינּוּן כָּאֶפְרוֹחִים, דִּמְקַנְּנִין בְּעַנְפֵי אִילָנָא. אִית דְּאַמְרֵי, בְּכָל עֵץ, אִלֵּין יִשְׂרָאֵל. <Nonei></i>דְּאִתְּמַר בְּהוּ, (ישעיהו ס״ה:כ״ב) כִּי כִימֵי הָעֵץ יְמֵי עַמִּי. אוֹ עַל הָאָרֶץ, אִלֵּין מָארֵי תּוֹרָה (ד\"א משנה), דְּאִתְּמַר בְּהוּ, עַל הָאָרֶץ תִּישָׁן וְחַיִּי צַּעַר תִּחְיֶה וּבַתּוֹרָה אַתָּה עָמֵל. אֶפְרוֹחִים: אִלֵּין פִּרְחֵי כְּהוּנָה. אוֹ בֵּיצִּים: אִלֵּין דְּזָן לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִקַּרְנֵי רְאֵמִים וְעַד בֵּיצֵּי כֵּנִים. וְהָאֵם רוֹבֶצֶּת עַל הָאֶפְרוֹחִים, בְּזִמְנָא דַּהֲווֹ קְרֵבִין קָרְבְּנִין. מַה כְּתִיב לֹא תִקַח הָאֵם עַל הַבָּנִים.</p>\n<p>חָרַב בֵּי מַקְדְּשָׁא, וּבָטְלוּ קָרְבְּנִין, מַה כְּתִיב, שַׁלֵּח תְּשַׁלַּח אֶת הָאֵם. וְגָלוּ הַבָּנִים, וְהַיְינוּ וְאֶת הַבָּנִים תִּקַּח לָךְ, מִסִּטְרָא דָּא' דְּאָת ו', דְּאִיהוּ עוֹלָם אָרוֹךְ דְּאִתְּמַר בֵּיהּ (דברים כ״ב:ז׳) לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים, לְעוֹלָם שֶׁכֻּלּוֹ אָרוֹךְ.</p>\n<p>וּבַאֲתָר דְּקָרְבְּנִין, תַּקִּינוּ צְּלוֹתִין, וּמְצַּפְצְּפִין בְּקָלִין דְּשִׁירִין. בְּקוֹל דִּקְרִיאַת שְׁמַע, לְגַבֵּי עַמּוּדָא דְּאֶמְצָּעִיתָא דְּאִיהוּ לְעֵילָּא. דְּהָא אִימָּא וּבְרַתָּא בְּגָלוּתָא, וּמִיַּד דְּנָחִית, קַשְׁרִין לֵהּ בִּבְרַתָּא, דְּאִיהִי יַד כֵּהָה, לְמֶהֱוִי קָשִׁיר ו' עִם ה', בְּשִׁית סְפִירָאן. מִיָּד מְלַחֲשִׁין לְגַבֵּי חָכְמָה, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>"],[9520012617,"<p>אֶחָ\"ד כָּבוֹ\"ד, גִימַטְרִיָא מ\"ה מִן חָכְמָה. דְּנָחִית לֵיהּ לְגַבֵּי אִמָּהּ, וּמִיַּד דְּנָחִית, קַשְׁרִין לֵיהּ עַמָּא בְּקִשּׁוּרָא דִּתְפִילִּין דְּרֵישָׁא. וּבְגִין דָּא בְּאַרְבַּע פָּרְשִׁיָין דִּתְפִילִּין, קַדֶּשׁ לִי, חָכְמָה. וְהָיָה כִּי יְבִיאֲךָ, בִּינָה. שְׁמַע יִשְׂרָאֵל תִּפְאֶרֶת, כָּלִיל ו' סְפִירָן, בְּשִׁית תֵּיבִין. וְהָיָה אִם שָׁמוֹעַ, מַלְכוּת, יַד כֵּהָה. צְּלוֹתָא כֶּתֶר כ' עַל רֵישֵׁיהּ, אֵין קָדוֹשׁ כַּידוָֹד, דְּסַנְדַּלְפוֹן קוֹשֵׁר כָּל צְּלוֹתִין, וְעָבִיד לוֹן כֶּתֶר.</p>\n<p>בְּהַהוּא זִמְנָא צָּרִיךְ לְסַדְּרָא מְנוֹרָא (ס\"א פתורא) לִסְעוּדָתָא דְּמַלְכָּא, וּמַשְׁכְּנָא וּמְנַרְתָּא וַאֲרוֹנָא וּמַדְבְּחָא, וְכָל מִינֵי שִׁמּוּשָׁא דְּבֵיתָא דְּמַלְכָּא. וְלָאו בָּתַר פָּתוֹרָא אַזְלֵינָן דְּלָאו עוֹבָדָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא אַזְלֵינָן אֶלָּא בָּתַר פָּתוֹרָא דְּאִיהוּ עוֹבָדֵי יְדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ שְׁכִינְתֵּיהּ. מִשְׁכָּן דִּילֵיהּ, פָּתוֹרָא דִּילֵיהּ, מְנַרְתָּא דִּילֵיהּ, אֲרוֹנָא דִּילֵיהּ, מַדְבְּחָא דִּילֵיהּ, אִיהִי כְּלִילָא מִכָּל מָאנֵי שִׁמּוּשָׁא לְמַלְכָּא עִלָּאָה.</p>"],[9520012618,"<p>אִינְהוּ אִינּוּן דִּמְתַּקְנֵי חַמְרָא וְנָהֲמָא דְּמַלְכָּא עִלָּאָה, דְּאִתְּמַר בְּהוּ אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, דְּלֵית לְקָרְבָא לֵיהּ לְגַבֵּיהּ אֶלָּא אִלֵּין דְּאִתְקְרִיאוּ אִשֵּׁי יְיָ. וּבְגִין דָּא אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. דְּעָלֵיהּ אִתְּמַר, (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְּלַחְמִי. וְאִתְקְרֵי לֶחֶם הַפָּנִים, דְּאִינּוּן י\"ב אַנְפִּין, (במדבר ו׳:כ״ה) יְבָרֶכְךָ יְהוָֹה, יָאֵר יְהוָֹה, יִשָּׂא יְהוָֹה, תְּרֵיסָר אַנְפִּין דִּתְלַת חֵיוָן.</p>\n<p>מַאי לֶחֶם דְּאִלֵּין פָּנִים. דָּא נַהֲמָא דְּאָדָם, דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְאִית לֵיהּ נַהֲמָא בְּאַרְבַּע אַנְפִּין, דְּאִינּוּן אַרְבַּע אַתְוָון יְדוָֹד. הַאי נַהֲמָא דְּפָתוֹרָא דְּמַלְכָּא, אִיהוּ סֹלֶת נְקִיָּה.</p>\n<p>כִּבְשָׁן דִּילֵיהּ, דְּאוֹפֶה בֵּיהּ נַהֲמָא, שְׁכִינְתָּא. תַּמָּן אִתְבְּשַׁל וְאִשְׁתְּלִים. וּבְגִין דָּא, אֵין בּוֹצְּעִין אֶלָּא מֵאֲתָר דְּגָמַר בִּשׁוּלָא. כְּגַוְונָא דִּשְׁלִימוּ דְּפֶרִי, אִיהוּ גְּמַר בִּישׁוּלוֹ. וְהַאי אִיהוּ אֲדֹנָי, גְּמַר וּשְׁלִימוּ דַּיְדוָֹד, דְּאִיהוּ לֶחֶם הַפָּנִים. אֲדֹנָי, כִּבְשָׁן דִּילֵיהּ. דְּאִיהִי כְּבוּשָׁה תְּחוֹת בַּעְלָהּ. וּבְגִינָהּ אִתְּמַר, (שמות י״ט:י״ח) וְהַר סִינַי עָשָׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. וְלֹא כְּכִבְשָׁן דְּאֵשׁ דְּהֶדְיוֹט, אֶלָּא כְּכִבְשָׁן, דְּבֵיהּ כָּבַשׁ רַחֲמָיו לְעַמֵּיהּ, כַּד מְצָּלִין וּבָעוּן בָּעוּתִין, כֵּן יִכְבְּשׁוּ רַחֲמֶיךָ אֶת כַּעַסְךָ. וּבֵיהּ כִּבְשֵׁי דְּרַחֲמָנָא לָמָּה לָךְ.</p>\n<p>וּבְנַהֲמָא דְּאוֹרַיְיתָא, אִית סֹלֶת דִּיְהָב לֵיהּ מַלְכָּא, לְאִינּוּן דְּאִתְּמַר עָלַיְיהוּ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. מֵיכְלָא דְּצַּדִּיקַיָּיא. וְאִית נַהֲמָא דְּאוֹרַיְיתָא, דְּאִיהוּ פְּסוֹלֶת, לְאִינּוּן עַבְדִּין וּשְׁפָחוֹת, דְּבֵי מַלְכָּא. וּבְגִין דָּא בְּמַטְרוֹנִיתָא אִתְּמַר (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ, דְּאִינּוּן מָארֵי מַתְנִיתִין. וּבְגִין דָּא אִתְּמַר בְּמֵיכְלָא דְּמַלְכָּא, וַעֲשִׂירִית הָאֵיפָה סוֹלֶת וַדַּאי, וְדָא יוֹ\"ד מִן אֲדֹנָי, אִיהִי עֲשִׂירִית. וְדָא סֹלֶת דְּהֵיכְלָא דְּמַלְכָּא אַשְׁבְּחַת (ד\"א דמיכלא דמלכא אשתכחת).</p>\n<p>קוּם בּוּצִּינָא קַדִּישָׁא, אַנְתְּ וְרִבִּי אֶלְעָזָר בְּרָךְ, וְרִבִּי אַבָּא, וְרִבִּי יְהוּדָה, וְרִבִּי יוֹסֵי, וְרִבִּי חִיָּיא, וְרִבִּי יוּדָאִי, לְתַקְּנָא דּוֹרוֹנָא לְמַלְכָּא, וּלְקָרְבָא כָּל אֵבָרִין, דְּאִינּוּן יִשְׂרָאֵל, קָרְבְּנִין לְּקוּדְשָׁא בְּרִיךְ הוּא הַהוּא דְּאִתְקְרֵי נְשָׁמָה, לְגַבֵּי אֵבָרִים שְׁכִינְתָּא קַדִּישְׁתָּא, אֵשׁ שֶׁל גָּבוֹהַּ. דְּאָחִיד בְּעֵצִּים, דְּאִתְקְרִיאוּ עֲצֵּי הָעוֹלָה, דְּאִינּוּן עֵץ הַחַיִּים וְעֵץ הַדַּעַת טוֹב וָרָע. עֲצֵּי הַקֹּדֶשׁ אִתְקְרִיאוּ, אִינּוּן מָארֵי תּוֹרָה, דְּאִתְאֲחִידַת בְּהוֹן אוֹרַיְיתָא, דְּאִתְּמַר בָּהּ (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְּבָרִי כָּאֵשׁ נְאֻם יְיָ.</p>"],[9520012619,"<p>וְאִתְּמַר בָּהּ, עוֹלָה לַיְיָ, קָרְבָּן לַיְיָ, אִשֶּׁה לַיְיָ, וְאִתְּמַר אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. וְהָא כְּתִיב דְּלֵית לְקָרְבָא קָרְבָּן אֶלָּא לַיְיָ, מַאי נִיהוּ, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. אֶלָּא אָרְחָא, דְּמַאן דְּקָרִיב דּוֹרוֹנָא, לְמִקְרַב לֵיהּ לְמַלְכָּא, וּלְבָתַר אִיהוּ פָּלִיג לֵיהּ, לְמַאן דְּבָעֵי. אוּף הָכִי יִשְׂרָאֵל, מַקְרִיבִין אוֹרַיְיתָא לְּקוּדְשָׁא בְּרִיךְ הוּא, <Nonei></i>דְּאִיהוּ לַחְמוֹ, וְאִיהוּ יִינוֹ, וְאִיהוּ בָּשָׂר דִּילֵיהּ, וְאִתְּמַר בָּהּ, (בראשית ב׳:כ״ג) עֶצֶּם מֵעֲצָּמַי וּבָשָׂר מִבְּשָׂרִי. בְּשַׂר קֹדֶשׁ, דְּאוֹקְמוּהָ עָלָה מָארֵי מְתִיבְתָּאן, בְּבָשָׂר הַיוֹרֵד מִן הַשָּׁמַיִם עֲסְקֵינָן.</p>"],[9520012620,"<p>קוּדְשָׁא בְּרִיךְ הוּא מַאי עָבִיד מֵהַהוּא דּוֹרוֹנָא. לְמַלְכָּא דְּאָכִיל עַל פָּתוֹרָא. דְּקַרְבִין עַל פָּתוֹרֵיהּ מִכָּל מִין וָמִין, סֹלֶת, וּבֵינוֹנִי, וּפְסוֹלֶת. וְאִיהוּ פָּלִיג מִפָּתוֹרֵיהּ, לְכָל מָארֵי סְעוּדָתָא, לְכָל חַד כַּדְּקָא יָאוּת, עַל יְדֵי מְמָנָן דִּילֵיהּ. וּמֵהַהוּא נַהֲמָא, דְּאִיהוּ סֹלֶת, דְּמַלְכָּא אָכִיל, אִיהוּ מָנֵי לְמֵיהַב לְאִינּוּן דִּרְחִימִין גַּבֵּיהּ. הֲדָא הוּא דִכְתִיב, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִחוֹחִי. דְּהַיְינוּ (דברים י״ח:א׳) אִשֵּׁי יְיָ וְנַחֲלָתוֹ יאכֵלוּן (ודא הוא ההוא דאתמר ביה (משלי ט׳:ה׳) לכו לחמו בלחמי ושתו ביין מסכתי.) הַאי אִיהוּ מִסִּטְרָא דְּאִילָנָא דְּחַיִּי. אֲבָל מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע, מַנִי לְמֵיהַב בֵּינוֹנִי, לְמַלְאָכִים. וּפְסוֹלֶת לַשֵּׁדִין וּמַזִּיקִין, דְּאִינּוּן מְשַׁמְּשִׁין לְסוּסְוָון וּלְפָרַשְׁיָין דְּמַלְכָּא.</p>\n<p>וְאוֹף הָכִי דְּפָרָשִׁין דְּמַלְכָּא, הֲווֹ מָארֵי מִשְׁנָה, דְּאִינּוּן כְּמַלְאָכִים. מְשַׁמְּשִׁין לוֹן שֵׁדִים יְהוּדָאֵי, דְּאִינּוּן רְשִׁימִין בְּאוֹת שַׁדַּי, (ס\"א באות י') וְאִית שֵׁדִּין וּמַזִּיקִין מִסִּטְרָא דִּמְסָאֳבוּ, דְּאִתְקְרִיאוּ שֵׁדִים עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. (קהלת ז׳:י״ד) וְזֶה לְעוּמַת זֶה עָשָׂה הָאֱלֹהִים.</p>\n<p>וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין, דְּאִינּוּן ג' מִינִין מִינַּיְיהוּ, חַד מִין דִּלְהוֹן כְּמַלְאָכֵי הַשָּׁרֵת. וּמִין תִּנְיָינָא, כִּבְנֵי אָדָם. וּמִין תְּלִיתָאי, כִּבְעִירָן. וְאִית בְּהוֹן חַכִּימִין בְּאוֹרַיְיתָא דְּבִכְתָב וְדִבְעַל פֶּה. אִתְקְרֵי יוֹסֵף שִׁידָא, עַל שֵׁם דְּאוֹלִיד לֵיהּ שֵׁד. וְלָאו לְמַגָּנָא אָמְרוּ מָארֵי מַתְנִיתִין, אִם הָרַב דּוֹמֶה לְמַלְאַךְ יְיָ צְּבָאוֹת תּוֹרָה יְבַקְשׁוּ מִפִּיהוּ. וְאַשְׁמְדָאי מַלְכָּא, הוּא וְכָל מִשְׁפַּחְתֵּיהּ, הָא אוֹקִימְנָא דְּאִינּוּן שֵׁדִּין יְהוּדָאִין, דְּאִתְכַּפְיָין בְּאוֹרַיְיתָא, וּבִשְׁמָהָן דְּאוֹרַיְיתָא.</p>\n<p>וּבְנֵי אַהֲרֹן, בְּגִין דַּעֲרִיכוּ קָרְבְּנֵהוֹן, בְּגִין דָּא אִתְעֲנָשׁוּ, דְּכֻלְּהוּ קָרְבְּנִין אַף עַל גַּב דְּאִתְקְרִיבוּ לְגַבֵּי מַלְכָּא, אִיהוּ פָּלִיג לוֹן לְכָל חַד כַּדְּקָא חֲזֵי. וְנָטַל לְחוּלָקֵיהּ מַה דְּאִתְחֲזִי לֵיהּ. (ע\"כ רעיא מהימנא).</p>"],[9520012621,"<p>וּבְחִבּוּרָא קַדְמָאָה (במדבר כ״ח:כ״ו) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה וְגוֹ'. אָמַר רִבִּי אַבָּא, יוֹם הַבִּכּוּרִים, מַאן יוֹם. דָּא נָהָר הַיּוֹצֵא מִעֵדֶן, דְּאִיהוּ יוֹמָא מֵאִינּוּן בְּכוֹרִין עִלָּאִין. וְדָא אִיהוּ דְּאוֹרַיְיתָא תַּלְיָא בֵּיהּ, וְאִיהוּ אַפִּיק כָּל רָזִין דְּאוֹרַיְיתָא. וּבְגִין דְּאִיהוּ אִילָּנָא דְּחַיֵּי, פְּרִי אִילָנִין אִצְטְרִיכוּ לְאַיְיתָאָה.</p>\n<p><Noneb>רעיא מהימנא</b> (במדבר כ״ח:כ״ו) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה וְגוֹ'. רִבִּי אַבָּא אָמַר, יוֹם הַבִּכּוּרִים אִינּוּן בִּכּוּרִים עִלָּאִין דְּאוֹרַיְיתָא. הֲדָא הוּא דִכְתִיב, (שמות כ״ג:י״ט) רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא וְגוֹ'. אָמַר רַעְיָא מְהֵימְנָא, כְּגַוְונָא דִּבְכוֹרִים לְאִמְּהוֹן, אוּף הָכִי אִתְקְרִיאוּ פֵּירוֹת בִּכּוּרִים, דְּפֵירוֹת דְּאִילָנִין, (הושע ט׳:י׳) כְּבִכּוּרָה בַּתְּאֵנָה, הָכִי יִשְׂרָאֵל קַדְמוֹנִים וּבִכּוּרִים לְּקוּדְשָׁא בְּרִיךְ הוּא, מִכָּל אוּמִין דְּעָלְמָא, הֲדָא הוּא דִכְתִיב, (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַיְדוָֹ\"ד וְגוֹ'. וּבְגִין דָּא אִתְּמַר בְּהוֹן, (שמות כ״ג:י״ט) תָּבִיא בֵּית יְהוָֹה אֱלֹהֶיךָ. וּבְגִין דָּא אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּאִתְּמַר בְּהוֹן (ישעיהו ט׳:י״א) וַיֹּאכְלוּ אֶת יִשְׂרָאֵל בְּכָל פֶּה. יֶאֱשָׁמוּ רָעָה תָּבֹא אֲלֵיהֶם.</p>\n<p>אוּף הָכִי ו' דְּכָלִיל שִׁית סְפִירָאָן, וְאִיהוּ בֶּן י\"ד, אִתְקְרֵי בְּכֹ\"ר. וְכָל עַנְפִין דְּנָפְקִין מִנֵּיה דִּבְּהוֹן רָאשִׁין, כְּגַוְונָא דָּא אִתְקְרִיאוּ בִּכּוּרִים. ו' אִיהוּ נָהָר, מֵאִינּוּן בִּכּוּרִים עִלָּאִין, וְהַהוּא נָהָר נָפִיק מִעֵדֶן. וְדָא אִיהוּ דְּאוֹרַיְיתָא תַּלְיָיא בֵּיהּ. וְכַד נָפִיק נַפְקֵי כָּל רָזִין דְּאוֹרַיְיתָא, וּבְגִין דְּאִיהוּ אִילָנָא דְּחַיֵּי אוֹרַיְיתָא, הֲדָא הוּא (נ\"א חדא היא) דִּכְתִּיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וּפִקּוּדִין דִּילָהּ דַּמְיָין לְאִיבָּא פְּרִי דְּאִילָנִין, אִצְטְרִיכוּ לְאַיְיתָאָה.</p>\n<p>אָמַר רַעְיָא מְהֵימָנָא וְאִי תֵּימְרוּן אֲמַאי בִּכּוּרִים, דִּלְהוֹן אִתְקְרִיאוּ מִנְחָה חֲדָשָׁה, מִשִּׁית יַרְחִין לְשִׁית יַרְחִין. וּמִבַּר נָשׁ דְּאִתְּמַר בֵּיהּ (דברים כ׳:י״ט) כִּי הָאָדָם עֵץ הַשָּׂדֶה לִתְשַׁע יַרְחִין, אוֹ לְשִׁבְעָה. וּבְעִירָא אוּף הָכִי, (ויקרא כ״ב:כ״ז) שִׁבְעַת יָמִים יִהְיֶה תַּחַת אִמּוֹ וּמִיּוֹם הַשְּׁמִינִי וָהָלְאָה יֵרָצֶה לְקָרְבַּן אִשֶׁה לַיהוָֹה, לְקָרְבָא קָרְבְּנָא קֳדָם יְיָ. וְעוֹד סְפִירָאן, בְּהוֹן שֵׁם יְהוָֹה, וְכָל כִּנּוּיָין דִּילֵיהּ, אֲמַאי אִתְקְרִיאוּ בְּשֵׁם חֵיוָן.</p>\n<p>אֶלָּא מִנְחָה חֲדָשָׁה בְּאֹרַח רָזָא, דָּא שְׁכִינְתָּא. מִשִּׁית יַרְחִין לְשִׁית יַרְחִין, אִינּוּן שִׁית סְפִירָאן, דְּאִתְקְרִיאוּ שָׁנִים קַדְמוֹנִיּוֹת לִבְרִיאַת עָלְמָא, דְּאִינּוּן שִׁיתָא אַלְפֵי שְׁנִין הֲוִי עָלְמָא, מִסִּטְרָא דְּאִימָּא עִלָּאָה. וּמִסִּטְרָא דְּאִימָּא תַּתָּאָה, אִתְקְרִיאוּ יַרְחִין. וּבְגִין דְּקַדְמוּ לְעָלְמָא, וְכָל בִּרְיָין, אִתְקְרִיאוּ בִּכּוּרִים.</p>\n<p>וּשְׁכִינְתָּא מִנְחָה חֲדָשָׁה, מִסִּטְרָא דְּחַיָּה, דְּאִתְּמַר בָּהּ (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וְאִיהוּ תְּשַׁע לְחֶשְׁבּוֹן זְעֵיר דְּחֲנוֹךְ. אִיהוּ בַּר נָשׁ <Nonei></i>דְּאִתְיְילִיד לִתְשַׁע יַרְחִין דְּעוּבָּרָא, דְּאִיהִי עֲשִׁירָאָה. וּבְדָא כָּלִיל מִכֻּלְּהוּ, וְאִתְקְרֵי בֵּן בּוּכְרָא, עַל שֵׁם אוֹת בְּרִית, דְּאִיהוּ י', טִפָּה קַדְמָאָה דְּאִתְמְשַׁךְ מִנֵּיהּ זֶרַע יוֹרֶה כַּחֵץ. דְּאִיהוּ ו', וְאִיהוּ י', סָלִיק עַל ו', כְּאִיבָּא דְּסָלִיק עַל עַנְפָּא דְּאִילָנָא.</p>\n<p>וְאַף עַל גַּב דְּכַמָּה עַנְפִין אִית בְּאִילָנָא, וְכַמָּה תְּאֵנִים עָלַיְיהוּ, אִינּוּן דְּאַקְדִּימוּ בְּקַדְמִיתָא, אִתְקְרִיאוּ בִּכּוּרִים. אִלֵּין אִינּוּן רֵישִׁין דְּכֻלְּהוּ. כְּגַוְונָא דִּלְהוֹן אִתְּמַר (תהילים כ״ד:ז׳) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. (ישעיהו מ׳:כ״ו) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. (במדבר א׳:ב׳) שְׂאוּ אֶת רֹאשׁ כָּל עֲדַת בְּנֵי יִשְׂרָאֵל.</p>\n<p>שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם. שְׁעָרִים אִלֵּין, אִינּוּן חַמְשִׁין תַּרְעִין דְּבִינָה. דְּאִיהִי מְתִיבְתָּא דִּלְעֵילָּא. וּשְׂאוּ פִּתְחֵי עוֹלָם, דִּמְתִיבְתָּא תַּתָּאָה, דְּכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא לְסוֹף מִתְנַשֵּׂא. הֲדָא הוּא דִכְתִיב, (משלי ל׳:ל״ב) אִם נָבַלְתָּ בְּהִתְנַשֵּׂא. וְאוֹקְמוּהָ מָארֵי מַתְנִיתִין, כָּל הַמְנַבֵּל עַצְמוֹ עַל דִּבְרֵי תּוֹרָה, לְסוֹף מִתְנַשֵּׂא, וְיָבֹא מֶלֶךְ הַכָּבוֹד, וְלֵית כָּבוֹד אֶלָּא תּוֹרָה.</p>\n<p>מֵהָכָא, מַאן דְּיָלִיף אוֹרַיְיתָא דְּאִתְקְרִיאַת כָּבוֹד, אִקְרֵי מֶלֶךְ. וְלָא תֵּימָא בְּהַהוּא עָלְמָא דְּאָתֵי וְלָא יַתִּיר, אֶלָּא מֶלֶךְ בִּתְרֵין עָלְמִין, בְּדִיּוּקְנָא דְּמָארֵיהּ. וּבְגִין דָּא כָּפוּל פְּסוּקָא תְּרֵין זִמְנִין, חַד מִי זֶה מֶלֶךְ הַכָּבוֹד. תִּנְיָינָא מִי הוּא זֶה מֶלֶךְ הַכָּבוֹד. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם, מַאי רָאשֵׁיכֶם תְּרֵין זִמְנִין. אִינּוּן חֵיוָן דְּמֶרְכַּבְתָּא עִלָּאָה, וְחֵיוָן דְּמֶרְכַּבְתָּא תַּתָּאָה. ובְחִבּורָא קַדְמָאָה (ע\"כ רעיא מהימנא).</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח קְרָא וְאָמַר, שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. הַאי קְרָא אוֹקְמוּהָ וְאִתְּמַר. אֲבָל שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם, אִלֵּין אִינּוּן תַּרְעִין עִלָּאִין, תַּרְעִין דְּסָכְלְתָנוּ עִלָּאָה. וְאִינּוּן חַמְשִׁין תַּרְעִין. רָאשֵׁיכֶם, אִינּוּן רָאשִׁים מַאן אִינּוּן. אֶלָּא, כָּל חַד וְחַד, אִית לֵיהּ רֵישָׁא לְאִתְפַּשְׁטָא וּלְמֵיעַל דָּא בְּדָא, וּלְאַכְלְלָא דָּא בְּדָא.</p>\n<p>אַשְׁכַּחְנָא בְּסִפְרָא דְּחֲנוֹךְ, שְׂאוּ שְׁעָרִים, אִלֵּין אִינּוּן תַּרְעִין דִּלְתַּתָּא מֵאֲבָהָן, וְאִינּוּן תְּלָתָא בַּתְרָאִין. רָאשֵׁיכֶם: אִלֵּין אִינּוּן רָאשֵׁי אַלְפֵי יִשְׂרָאֵל, וְאִינּוּן אֲבָהָן עִלָּאֵי, וְאִינּוּן רָאשִׁין דְּאִינּוּן תַּרְעִין. וּבְגִין אִלֵּין דְּאִינּוּן אוֹפַנִּים, דְּסָחֲרָן וְנַטְלִין לוֹן עַל כַּתְפַיְיהוּ, אַמְרֵי שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם, שְׂאוּ לְמַאן. לְרָאשֵׁיכֶם. דְּאִינּוּן רָאשִׁין עָלַיְיכוּ, וְשָׁלְטָנִין עָלַיְיכוּ. וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם. אִלֵּין אִמָּהָן וְאַרְבַּע אִינּוּן דִּלְתַּתָּא.</p>\n<p>וְיָבֹא מֶלֶךְ הַכָּבוֹד, דָּא מַלְכָּא עִלָּאָה דְּכֹלָּא, דְּאִיהוּ מֶלֶךְ מֵהַהוּא כָּבוֹד, דְּנָהִיר לְסִיהֲרָא, וּמַאן אִיהוּ. יְיָ צְבָאוֹת. וַיָּבֹא, לְאָן אֲתָר. לְמֵיעַל אוֹרַיְיתָא בַּאֲרוֹנָא, בְּחִבּוּרָא חֲדָא, כַּדְּקָא יָאוּת. וְכֵיוָן דְּהַאי עָאל לְאַתְרֵיהּ, כַּדִּין אוֹרַיְיתָא עָאל בַּאֲרוֹנָא. וְאִתְחַבָּר חִבּוּרָא חֲדָא, אוֹרַיְיתָא עִלָּאָה, בְּאוֹרַיְיתָא <Nonei></i>דִּבְעַל פֶּה, מִתְחַבְּרוּ לְפָרְשָׁא מִילִּין סְתִימִין.</p>\n<p>אֵימָתַי. בְּשָׁבוּעוֹתֵיכֶם. לְמִנְיָינָא דְּאַתּוּן מוֹנִין. דִּבְכָל שַׁעֲתָא דְּיִשְׂרָאֵל עַבְדִּין חוּשְׁבָּנִין לְיַרְחִין וְזִמְנִין, קוּדְשָׁא בְּרִיךְ הוּא אַתְקִין תֵּיבָה גּוֹ אִינּוּן רְקִיעִין, וְאַעְבַּר כָּרוֹזָא, הָא בָּנָי לְתַתָּא, קַדְשׁוּ יַרְחָא, קַדְשׁוּ זִמְנָא, אִתְקַדָּשׁוּ כֻּלְכוּ לְעֵילָּא. וְעָבִיד לְכָל חֵילֵי דְּבִשְׁמַיָּא, דְּמִתְקַדְּשִׁין כַּחֲדָא בְּעַמָּא קַדִּישָׁא, וְכֻלְּהוּ נַטְרֵי כַּחֲדָא, נְטִירָא חֲדָא, וְעַל דָּא בְּשָׁבוּעוֹתֵיכֶם, לְמִנְיָינָא דְּאַתּוּן מוֹנִין אִינּוּן שֶׁבַע שַׁבָּתוֹת.</p>"],[9520012622,"<p>וּכְדֵין מָשִׁיךְ קוּדְשָׁא בְּרִיךְ הוּא, מְשִׁיכוּ דְּשֶׁבַע דַּרְגִּין לְתַתָּא, בְּהַהוּא דַּרְגָּא דְּאִתְאֲחָד בְּהוּ, בְּאִינּוּן שֶׁבַע שַׁבָּתוֹת. (ס\"א באינון שבע שבתות. וכדין משיך קודשא בריך הוא, משיכו דשבע דרגין דלעילא, בההוא דרגא לתתא דאתאחד באינון שבע שבתות). וְאִי תֵֹּימָֹא, וְהָא שִׁיתָּא אִינּוּן וְלָא יַתִּיר. אֶלָּא כְּדֵין אִימָּא יָתְבָא עַל אֶפְרוֹחִין, וְאִשְׁתְּכָחַת רְבִיעָא עָלַיְיהוּ. וַאֲנָן מְפַרְחִין לָהּ, וְנַטְלִין אִינּוּן שִׁית בְּנִין. בְּהַאי דַּרְגָּא דִּלְתַתָּא, לְקַיְּימָא דִּכְתִּיב, (דברים כ״ב:ז׳) שַׁלֵּח תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים וְגוֹ'.</p>"],[9520012623,"<p>רַב הַמְנוּנָא סָבָא אָמַר, בְּהַאי יוֹמָא, לָא נַטְלִין יִשְׂרָאֵל אֶלָּא חָמֵשׁ בְּנִין, וְאִינּוּן חֲמִשָּׁה חוּמָשֵׁי תּוֹרָה. וְאִי תֵּימָא שִׁית אִינּוּן. אֶלָּא שֶׁבַע אִינּוּן, בְּחַד צִפּוֹרָא דְּאִשְׁכְּחַת בֵּין גַּדְפָהָא דְּאִימָּא. וְיִשְׂרָאֵל, יַדְעֵי לְמֵיצָד צֵידָא טָבָא, רַבָּא וְיַקִּירָא. מַה עָבְדֵי. מַפְּקֵי מִתְּחוֹת גַּדְפָהָא דְּאִמָּהָא, הַהוּא צִפּוֹרָא, בִּלְחִישׁוּ דְּפוּמָא מְלַחֲשׁוּ לְגַבָּהּ, לְחִישׁוּ בָּתַר לְחִישׁוּ.</p>\n<p>וְהַהוּא צִפּוֹרָא דְּחָיִישׁ (ס\"א דרחים) לְאִינּוּן לְחִישִׁין, וּלְאִינּוּן קָלִין, דְּקָא מְלַחֲשֵׁי לְגַבָּהּ. וְאַף עַל גַּב דְּאִיהִי תְּחוֹת גַּדְפֵּי אִמָּהָא, זָקִיף רֵישָׁא וְאִסְתַּכְּלַת לְגַבֵּי הַהוּא לְחִישׁוּ דְּקָלָא, וּפַרְחַת לְגַבַּיְיהוּ, וְנַפְקַת מִתְּחוֹת גַּדְפָהָא דְּאִימָּא. כֵּיוָן דְּיִשְׂרָאֵל נַטְלֵי לָהּ, אַתְקִיפוּ בָּהּ, וְלַחֲשִׁין לָהּ, וְקַשְׁרִין לָהּ בְּקִשּׁוּרָא דְּלָא תִּפְרַח וְתֵזִיל. מִיַּד נַטְלֵי לָהּ יִשְׂרָאֵל בְּהַהוּא קִשּׁוּרָא, וְאִיהִי בָּעָאת לְמִפְרַח וּלְמֵיזַל, וְלָא יָכִילַת לְמֵיזָל לָהּ.</p>\n<p>וּבְעוֹד דְּהִיא קְשִׁירָא בִּידַיְיהוּ, אִינּוּן מְלַחֲשֵׁי בְּקַלֵיהוֹן, וְאִיהִי מְצַפְצְפָא בַּהֲדַיְיהוּ, <Nonei></i>וּפַרְחַת לְעֵילָּא, וְנַחְתַּת. וְכָל אִינּוּן בְּנִין דִּתְחוֹת גַּדְפֵּי אִמְּהוֹן, כֵּיוָן דְּשַׁמְעֵי הַהוּא צִפְצֻפָא דְּאַחֲתְהוֹן, וּלְחִישׁוּ דְּהַהוּא קָלָא, מִיַּד נַפְקֵי מִתְּחוֹת גַּדְפָהָא דְּאִמְּהוֹן, וּפַרְחֵי לְגַבֵּי הַהוּא צִפּוֹרָא, וְיִשְׂרָאֵל נַטְלֵי לוֹן, וְאַחְדֵּי בְּהוּ. וְאִלְמָלֵא הַהוּא צִפּוֹרָא דְּקָא אַחְדֵּי בְּקַדְמִיתָא, אִינּוּן לָא פַּרְחֵי לְגַבַּיְיהוּ לְעָלְמִין, וְלָא יַכְלִין לְאַחֲדָא בְּהוּ.</p>\n<p>הֵיךְ צָדִין צֵידָה דְּהַאי צִפָּרָא קַדִּישָׁא. מְתַקְּנִין לְקָמָא מֵיכְלָא יַקִּירָא בְּחֶדְוָוה, וְכָל עִנּוּגִין, וְעָאלִין לְבֵי כְּנִשְׁתָּא וּלְבֵי מִדְרָשָׁא, וּמְצַפְצְפָן לְגַבָּהּ בְּקַל לְחִישׁוּ כַּדְּקָא יָאוּת. וְאִיהִי דִּמְטַמְּרָא תְּחוֹת גַּדְפָהָא דְּאִימָּא, זַקְפָת רֵישָׁא, וְחָמָאת פָּתוֹרִין מְתֻקְּנָן, וְצִפְצוּפִין לְגַבָּהּ כַּדְּקָא יָאוּת. נַפְקַת וּפַרְחַת לְגַבַּיְיהוּ כְּמָה דְּאִתְּמַר, וּבָה אֲחָדִין כָּל אִינּוּן בְּנִין.</p>\n<p>וּמְשַׁלְּחִין לְהַהוּא דִּרְבִיעָא עָלַיְיהוּ וְאַזְלַת. בְּגִין דְּהָא מִן רְקִיעָא שְׁבִיעָאָה וּלְעֵילָּא, בַּמְכוּסֶּה מִמָּךְ אַל תִּדְרוֹשׁ. שָׁלַח לֵיהּ, דְּלָא תִּיכוֹל לְאַדְבְּקָה וְעַל דָּא כְּתִיב, (דברים כ״ב:ז׳) שַׁלֵּח תְּשַׁלַּח וְגוֹ'.</p>\n<p>מִקְרָא קֹדֶשׁ, דָּא קְרִיאָה וְצִפְצוּפָא, דְּעַבְדִּין לְהַהוּא צִפָּרָא קַדִּישָׁא בְּקַדְמִיתָא. וְכֵיוָן דְּאַחְדִּין בָּהּ שְׁאַר יוֹמִין, אִקְרוּן מִקְרָאֵי קֹדֶּשׁ. הַאי צִפָּרָא אִקְרֵי קֹדֶשׁ, דִּכְתִּיב, כִּי קֹדֶשׁ הִיא לָכֶם. וּבְגִין דְּאִיהִי קֹדֶשׁ, אִיהִי קָרְאָה לְכוּלְהוּ וְאַתְיָין לְגַבָּהּ. וּבְגִין כַּךְ אִקְרוּן מִקְרָאֵי קֹדֶשׁ.</p>\n<p>אִיהִי קָרְאָה, וְיִשְׂרָאֵל מְצַפְצְפָן בַּהֲדָהּ, וּקְרָאָן אוּף הָכִי. וְעַל דָּא אִינּוּן אַתְיָין לְגַבַּיְיהוּ, וְאַחְדֵּי בְּהוּ. בְּגִין כַּךְ (ויקרא כ״ג:ד׳) אֵלֶּה מוֹעֲדֵי יְיָ מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אוֹתָם. מִקְרָאֵי קֹדֶשׁ, בְּצִפְצוּפָא דִּלְּהוֹן, וּבְהַהוּא צִפָּרָא קַדִּישָׁא קֹדֶשׁ, דְּקָרָא לוֹן.</p>"],[9520012624,"<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, מִלִּין אִלֵּין, כַּמָה סְתִימִין אִינּוּן, לְמַאן דְּלָא יָדַע, וְגַלְיָין לְמַאן דְּיָדַע בְּהוּ. וַדַּאי הַהוּא צִּפּוֹרָא אִיהוּ שְׁכִינְתָּא. קֵן דִּילָהּ, דָּא בֵּי מַקְדְּשָׁא. וְיִשְׂרָאֵל אִינּוּן אֶפְרוֹחִין, דְּאִימָּא יָתְבָא עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, (דברים כ״ב:ו׳) וְהָאֵם רוֹבֶצֶּת עַל הָאֶפְרוֹחִים, וְאִינּוּן מָארֵי מִשְׁנָה, דְּפַרְחִין בְּפִקּוּדִין דִּילָהּ. אוֹ בֵיצִּים, אִינּוּן מָארֵי מִקְרָא.</p>\n<p>וּבְזִמְנָא דְּחָבוּ יִשְׂרָאֵל, וְאִתְחָרִיב בֵּי מַקְדְּשָׁא, מַה כְּתִיב. שַׁלֵּח תְּשַׁלַּח אֶת הָאֵם, הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאִינּוּן מָארֵי שִׁיתָא סִדְרֵי מִשְׁנָה כְּתִיב בְּהוּ, וְאֶת הַבָּנִים תִּקַּח לָךְ. דְּאִינּוּן שִׁית, מִסִּטְרָא דְּשִׁית בְּנִין דִּתְחוֹת אִימָּא עִלָּאָה, דְּאִינּוּן בְּשִׁית תֵּיבִין דִּקְרִיאַת שְׁמַע. אוֹ בְּשִׁית סִדְרֵי מִשְׁנָה, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶיְכַוִּין לִבּוֹ לַשָּׁמַיִם. וְקַשְׁרִין לוֹן בְּקִשְׁרִין דִּתְפִלִּין, עַל רֵישָׁא וְעַל דְּרוֹעָא.</p>\n<p>וּבְמַאי נַטְלִין בְּנִין בְּכַמָּה צִּפְצּוּפִין דְּקַלִין דִּקְרִיאַת שְׁמַע. וּלְבָתַר לַחֲשִׁין בִּלְחִישׁוּ בִּצְּלוֹתָא דַּחֲשַׁאי, לְגַבֵּי אִימָּא וּבְרַתָּא, וְאִינּוּן ה' ה', וְנַחְתִּין לְגַבֵּיהּ ו', בְּקֶשֶׁר דִּילֵיהּ דְּאִיהוּ יו\"ד. וְשַׁרְיָא ה' עִלָּאָה, עַל ו', תְּפִלִּין עַל רֵישֵׁיהּ. ה' זְעֵירָא, נָחַת לְגַבֵּי י', דְּאִיהוּ קֶשֶׁר דְּה' עִלָּאָה, עַל רֹאשׁ ו', וְאִיהוּ ו', קֶשֶׁר עִמָּהּ בְּה' דְּיָד כֵּהָה.</p>\n<p>וּבְגִין דָּא, אֶפְרוֹחִים מִסִּטְרָא דְּאָת ו', כָּלִיל ו' סִדְרֵי מִשְׁנָה. אוֹ בֵיצִּים, אִלֵּין. מָארֵי מִקְרָא, דְּאִתְּמַר עָלַיְיהוּ, בֶּן ה' שָׁנִים לְמִקְרֵא, וְדָא ה'. בְּנִין מִסִּטְרָא דְּבֶן יָ\"הּ, אִלֵּין <Nonei></i>מָארֵי קַבָּלָה. עָלַיְיהוּ אִתְּמַר (דברים כ״ב:ו׳) לֹא תִקַּח הָאֵם עַל הַבָּנִים.</p>"],[9520012625,"<p>וּמָארֵי קַבָּלָה, אִינּוּן מָארֵי תַּלְמוּד. וְאִתְּמַר עָלַיְיהוּ, (דברים ו) וְשִׁנַּנְתָּם. וְאוֹקְמוּהָ מָארֵי מָתְנִיתִין, אַל תִּקְרֵי וְשִׁנַּנְתָּם, אֶלָּא וְשִׁלַּשְׁתָּם, דְּאִינּוּן שְׁלִּישׁ בַּמִקְרָא, שְׁלִישׁ בַּמִּשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. וְרָזָא דְּמִלָּה, (דברים כ״ב:ו׳) כִּי יִקָּרֵא קַן צִּפּוֹר לְפָנֶיךָ בַדֶּרֶךְ, בְּמָארֵי מִקְרָא. (שמות כ״ה:ל״א) וְעָשִׂיתָ מְנוֹרַת זָהָב טָהוֹר. הָא אוֹקְמוּהָ, וְעָשִׂיתָ מְנוֹרַת, כְּלָל. זָהָב, פְּרָט. מִקְשָׁה, כְּלָל. וְכַמָּה מִקְרָאִין מָארֵי מַתְנִיתִין, אִינּוּן מַרְבִּין וּמְמַעֲטִין, כְּגוֹן רִיבָּה וּמִיעֵט. אוּף הָכִי, מַרְבִּין, אַל תִּקְרֵי מַה. אֶלָּא מֵאָה. אוּף הָכִי, אַל תִּקְרֵי וְשִׁנַּנְתָּם, וְשִׁלַּשְׁתָּם. אֶלָּא וְדַרְשֵׁינָן מִנֵּיהּ, שְׁלִישׁ בַּמִקְרָא, שְׁלִישׁ בַּמִשְׁנָה, שְׁלִישׁ בַּתַּלְמוּד. כִּדְאִיתָא בְּקִדּוּשִׁין.</p>\n<p>אוּף הָכִי, (במדבר ז׳:א׳) בְּיוֹם כַּלֹּת מֹשֶׁה, כַּלַּת דַּרְשִׁינָן בֵּיהּ. אִי תֵּימָא דְּדַרְשֵׁינָן לוֹן מִנְּהוֹן. כֵּיצַּד מֵאַלְפָא בֵּיתָא, וְלָא מֵעַצְּמָן דְּאִינּוּן לֵית לוֹן רְשׁוּ, לְאוֹסָפָא, וְלָא לְמִגְרַע אוֹת מִנֵּיהּ, (דהיא ו') אוֹ לְאַחְלְפָא אָת דָּא בְּאָת אַחֲרָא. הָא כְּתִיב כַּלוֹת מָלֵּא בְּאוֹרַיְיתָא. מַאן יָהִיב לוֹן רְשׁוּת לְמִגְרַע אוֹת מִנֵּיהּ, דְּהוּא ו', הָא לָא אִית הָכָא מִלָּה דְּאִתְחַלָּיף בְּאַלְפָא בֵּיתָא. אֶלָּא עַל אִלֵּין תֵּיבִין חֲסֵרִין, דְּאִינּוּן מְלֵאִים. וּמְלֵאִים, דְּאִינּוּן חֲסֵרִים. וְעַל כָּל פֵּירוּשִׁין דְּיַכְלִין לְמֶעְבַּד לְקַשְׁטָא כַּלָּה בְּתַכְשִׁיטִין דִּילָהּ, קוּדְשָׁא בְּרִיךְ הוּא מָנֵּי לְמֶעְבַּד, כְּמָה דְּיֵימְרוּן, וּלְמֶהֱוִי מַאֲמִין לוֹן, הֲדָא הוּא דִכְתִיב, (דברים י״ז:י״א) עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ.</p>\n<p>לְאוּמָן דְּחָתַךְ מָאנֵי לְבוּשִׁין דְּמַלְכוּתָא, וְעָבִיד מִנְּהוֹן חֲתִיכָן סַגִּיאִין, אִינּוּן דְּיַדְעִין אַתְרִין דְּחָסֵרִין אִלֵּין חֲתִיכוֹת, אוֹ אִלֵּין דְּמִשְׁתַּאֲרִין, אִינּוּן מְתַקְּנִין אִינּוּן לְבוּשִׁין, וְשָׁוְיָן אִינּוּן חֲתִיכוֹת דְּאִתּוֹסְפָן, בַּאֲתָר דְּמִעוּטִין, וַחֲתִיכוֹת דְּאִינּוּן מְעַטִין, מוֹסִיפִין עָלַיְיהוּ, וְהַאי אִיהוּ עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ.</p>\n<p>וְאִי תֵּימָא, אִי כַּךְ הוּא, מַאי אִיהוּ דִּלְזִמְנִין טָעֵי חַד מִנַּיְיהוּ, וְיֵימָּא הַדְרֵי בִּי. אֶלָּא עַד דְּיָעַבְדֵי הוֹרָאָה מֵהַהִיא מִלָּה דְּחוֹלְקִין עָלָהּ, יָכִיל הַהוּא דְּאַקְשֵׁי עָלָהּ, לְמֵימַר הַדְרֵי בִּי. דְּלָא כָּל מְפָרְקֵי תַּכְשִׁיטִין דְּכַלָּה, יַדְעִין בַּחֲתִיכוֹת לְאָן אַזְלָן, עַד דִּיְהֵא פְּסָק עַל בּוּרְיֵיהּ, פִּרוּקִין דַּהֲלָכוֹת עַל בּוּרְיֵיהוֹן.</p>\n<p>מְנוֹרָה, שֶׁבַע בּוֹצִּינִין דִּילָהּ, (אסתר ב׳:ט׳) אֵת שֶׁבַע הַנְּעָרוֹת הָרְאוּיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ. לָקֳבֵל <Nonei></i>שִׁי\"ן דִּתְלַת רָאשִׁין ש. וְשי\"ן דְּאַרְבַּע רָאשִׁין דִּתְפִילִין. וְאִינּוּן לָקֳבֵל ז' בִּרְכָאן דִּקְרִיאַת שְׁמַע, דְּאִינּוּן בַּשַּׁחַר מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב מְבָרֵךְ שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲרֶיהָ. לְבָתַר, כַּהֲנָא רַבָּא בַּעֲבוֹדָה, דִּמְשַׁמֵּשׁ בְּכַנְפֵי מִצְּוָה, פַּעֲמוֹנִים וְרִמּוֹנִים, אִינּוּן קִשְׁרִין וְחוּלְיָין וְצִּיץ תְּפִילִּין, מִתַּמָּן וְאֵילָךְ (שמות ל׳:א׳) וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת.</p>"],[9520012626,"<p>פָּתַח רַעְיָא מְהֵימָנָא, (ד\"א רבי שמעון) וְאָמַר, כְּתִיב בְּפַרְשְׁתָּא דָּא, וְהִקְרַבְתֶּם אִשֶּׁה עוֹלָה לַיְיָ. וְאוֹקְמוּהָ, דְּעוֹלָה לָאִשִּׁים. וּבְגִין כָּךְ סָמַךְ עוֹלָה לְאִשֶּׁה. וְעוֹד אוֹקְמוּהָ, דְּלֵית עוֹלָה אַתְיָא אֶלָּא עַל הִרְהוּר הַלֵּב.</p>\n<p>וַדַּאי, כָּל קָרְבְּנִין לָא אַתְיָין, אֶלָּא לְכַפְּרָא. כָּל קָרְבְּנָא וְקָרְבְּנָא, עַל כָּל אֵבָרִין דְּבַּר נָשׁ, כְּפוּם הַהוּא חֵטְא דְּהַהוּא אֵבֶר. עַל טִפִּין דְּמוֹחָא, (שמות י״ב:ל״ט) עוּגוֹת מַצּוֹת כִּי לֹא חָמֵץ. אִי זָרִיק טִפִּין קַדְמָאִין, קֹדֶם דְּאַחְמִיצּוּ, בַּאֲתָר דְּלָאו דִּילֵיהּ. וְעַל אִלֵּין דְּאַחְמִיצּוּ, וְזָרִיק לוֹן בַּאֲתָר דְּלָא אִצְּטְרִיךְ, צָּרִיךְ לְאַיְיתָאָה עָלַיְיהוּ לֶחֶם חָמֵץ, וְאִינּוּן לַחְמִי תּוֹדָה הָכִי הֲווֹ, מִנְּהוֹן חָמֵץ, וּמִנְּהוֹן מַצָּה. פָּרִים מִסִּטְרָא דְּדִינָא, כְּבָשִׂים וְאֵילִים וְעַתּוּדִים וְעִזִּים. בְּגִין דְּאִינּוּן אַנְפֵּי דְּשׁוֹר, כֻּלְּהוּ שְׁחִיטָתָן בַּצָּפוֹן, וְקִבּוּל דָּמָן בִּכְלֵי שָׁרֵת בַּצָּפוֹן.</p>\n<p>שְׁחִיטָה וְקַבָּלָה וּזְרִיקָה כֻּלָּם בַּצָּפוֹן. לְבַסְּמָא מִדַּת הַדִּין, דְּאָתֵי לְבֵית דִּין מִסִּטְרָא דִּגְבוּרָה. בֵּית דִּין הַגָּדוֹל מִסִּטְרָא דִּגְבוּרָה, דְּתַמָּן בִּינָה. בֵּית דִּין הַקָּטָן, מִסִּטְרָא דְּמַלְכוּת. וְכָל אִינּוּן שׁוֹפְכֵי דָּמִים לְמִצְּוָה, אִינּוּן מִסִּטְרָא דִּגְבוּרָה.</p>\n<p>וּמַה דְּאוֹקְמוּהָ, עוֹלַת שַׁבַּת בְּשַׁבַּתוֹ וְלָא בְּשַׁבָּת אָחֳרָא, בְּגִין דְּעָבַר יוֹמוֹ בָּטֵל קָרְבָּנוֹ. דְּקָרְבָּן דּוֹחָה שַׁבַּת, וְאַדְלִיק אֵשׁ בְּשַׁבָּת, בְּגִין דְּאִיהוּ אֶשָּׁא קְדוֹשָׁה. דְּכָל אֵשׁ דְּקָרְבְּנִין אִיהוּ קֹדֶשׁ, וְשַׁבָּת קֹדֶשׁ, אֲחִידָן דָּא בְּדָא.</p>\n<p>אֲבָל אֵשׁ דְּחוֹל, אָסִיר לְאַחֲדָא לֵיהּ בַּקֹּדֶשׁ, וּבְגִין דָּא מָנֵי לוֹן לְיִשְׂרָאֵל, (שמות ל״ה:ג׳) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת. דְּהַאי אִיהוּ כִּלְאַיִם דְּטוֹב וָרָע. וּבְשַׁבָּת דְּשַׁלְטָא אִילָנָא דְּחַיִּי, דְּלֵית בֵּיהּ תַּעֲרוֹבֶת, (אסיר לאבערא ביה דחולין, דהאי אש דחולין דטומאה ולא דחולין דטהרה) וְחוּלִין דְּטָהֳרָה אָסִיר לְעָרְבָא בְּאֵשׁ דִּקְדוּשָּׁה. כָּל שֶׁכֵּן חוּלִין דְּטוּמְאָה, דְּאָסִיר לְעָרְבָא לוֹן בִּקְדוּשָּׁה. אוּף הָכִי כָּל קָרְבְּנִין, אִתְקְרִיאוּ בְּשַׂר קֹדֶשׁ. וְכָל קָרְבְּנִין דְּכָל מִין, אִית בְּהוֹן חוּלִין דְּטָהֳרָה, וְאִית בְּהוֹן <Nonei></i>קֹדֶשׁ וְקֹדֶשׁ הַקֳּדָשִׁים.</p>\n<p>וְרָזָא, דְּאִית הֶפְרֵשׁ בֵּין קֹדֶשׁ לְקֹדֶשׁ, הֲדָא הוּא דִכְתִיב, (שמות כ״ו:ל״ג) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקּוֹדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים. אוּף הָכָא אֶשּׁוֹת דְּקָרְבְּנִין, לָאו אִינּוּן שָׁוִין. דְּאֵשׁ שֶׁל גָּבוֹהַּ מְקוּדָּשׁ מֵאֵשׁ דְּקֹדֶשׁ דִּלְתַּתָּא. דְּאִתְקְרֵי אֵשׁ עֲצֵי הַקֹּדֶשׁ, אוֹ אֵשׁ בְּשַׂר הַקֹּדֶשׁ. וְאֶשָּׁא דְּקוּדְשָׁא, אִית בֵּיהּ הַפְרָשָׁה לְבֵין אֵשׁ הֶדְיוֹט. אַף עַל גַּב דְּאוֹקְמוּהָ עָלֵיהּ, דְּמִצְוָה לְהָבִיא מִן הַהֶדְיוֹט, אַף עַל גַּב דְּאִית אֵשׁ דְּקוּדְשָׁא, דְּכָל חַד צָרִיךְ לְאַתְרֵיהּ. וּמַתְלָא אִמְתִּילוּ יִשְׂרָאֵל קַדְמָאֵי לְהַאי רָזָא יִשְׂרָאֵל.</p>\n<p>(נ\"א ישראל אמתילו להאי. דהא ישראל בכלל) אִתְקְרִיאוּ מְלָכִים כְּמָה דְּאוֹקְמוּהָ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. אֲבָל כַּד הֲווֹ עָאלִין לְבֵי מַקְדְּשָׁא, כָּל חַד שַׁרְיָיא בְּאַתְרֵיהּ, כַּדְּקָא יָאוּת לֵיהּ. אוּף הָכִי כָּל קָרְבְּנִין לָאו אִינּוּן שָׁוִין, דְּאַף עַל גַּב דִּבְכוּלְּהוּ כְּתִיב קָרְבָּן לַיְיָ, אִיהוּ פָּלִיג כֹּלָּא כָּל חַד וְחַד כַּדְּקָא יָאוּת. וְרָזָא דָּא, אִשְׁתְּמוֹדַע בְּפָרֵי הֶחָג, דַּהֲווֹ קְרִיבִין לוֹן יִשְׂרָאֵל קֳדָם יְיָ.</p>"],[9520012627,"<p>אָמַר בּוּצִינָא קַדִּישָׁא, קוּם רַעְיָא מְהֵימָנָא מִשְּׁנָתָךְ, דְּאַנְתְּ וַאֲבָהָן יְשֵׁנֵי עָפָר אִתְקְרוּן, דְּעַד כְּעַן הֲוִיתוּן מִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, בְּאִינּוּן יְשֵׁנִים בַּמִשְׁנָה, דְּאִתְּמַר בְּהוֹן עַל הָאָרֶץ תִּישָׁן. וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה לַיהוָֹה. אַתּוּן אִינּוּן (בני) בִּכּוּרִים דִּשְׁכִינְתָּא, וּבְעוֹבָדִין דִּלְכוֹן, אִיהִי אִתְחַדְּשַׁת בִּצְלוֹתִין דַּאֲבָהָן בְּכָל יוֹמָא. דְּאוֹקְמוּהָ מָארֵי מַתְנִיתִין, תְּפִלּוֹת כְּנֶגֶד אָבוֹת תִּקְנוּם. וּבְקְרִיאַת שְׁמַע דְּאָמַר רַעְיָא מְהֵימָנָא שְׁמַע יִשְׂרָאֵל, וְאוֹקְמוּהָ כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע בְּכָל יוֹם, כְּאִלּוּ הוּא מְקַיֵּים (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה.</p>\n<p>ודַּאי בִּצְלוֹתִין דִּלְכוֹן, בִּקְרִיאַת שְׁמַע דִּלְכוֹן, שְׁכִינְתָּא אִיהִי אִתְחַדְּשַׁת קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין דָּא, וְהִקְרַבְתֶּם מִנְחָה חֲדָשָׁה לַיהוָֹה. בִּצְלוֹתִין דְּאִינּוּן בַּאֲתָר דְּקָרְבְּנִין. בְּאָן קָרְבְּנִין דִּצְלוֹתִין אִיהִי מִתְחַדֶשֶׁת. בְּשָׁבוּעוֹתֵיכֶם. דְּהַיְינוּ שָׁבוּעוֹת, דְּבֵיהּ מַתַּן תּוֹרָה, וְאִתְקְרֵי חֲמִשִּׁים יוֹם לָעוֹמֶר. וּבֵיהּ שִׁבְעָה שָׁבוּעוֹת, מִסִּטְרָא דְּהַהוּא דְּאִתְּמַר בֵּיהּ, (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ, וְאִיהִי מַלְכוּת כַּלָּה. כְּלִילָא מִשְּׁבַע סְפִירָן, כְּלִילָא בַּבִּינָה, דְּאִיהִי אִתְפַּשְּׁטַת בְּה' סְפִירָאן לְחַמְשִׁין.</p>\n<p>יְסוֹד כָּל, כָּלוּל מֵאִלֵּין חַמְשִׁין. כַּלָּ\"ה: כָּ\"ל ה'. כְּלִילָא מֵחֲמִשִׁים, כֻּלְּהוּ נִבְלָעִים בְּגוֹ חֲמִשִּׁים, חָכְמָה דְּאִיהִי, י' עִלָּאָה, מוּבְלַעַת בְּגוֹ חַמְשִׁין. ה' זִמְנִין עֶשֶׂר. ה' בִּינָה. י' חָכְמָה. עֶשֶׂר זִמְנִין ה' הַיְינוּ חַמְשִׁין וּבְחוּשְׁבָּן כָּ\"ל. וּבְחוּשְׁבָּן יָ\"ם. וְאִיהוּ יַם הַתּוֹרָה. מְקוֹרָא דִּילֵיהּ כֶּתֶר, דְּלֵית לֵיהּ סוֹף. שְׁאַר סְפִירָאן, אִתְקְרִיאוּ עַל שְׁמָהּ שִׁבְעַת יָמִים. וּמַלְכוּת יַם סוּף, סוֹף דְּכָל יָמִים.</p>\n<p>וּבְגִין דָּא דְּאִינּוּן חַמְשִׁין, שֶׁבַע שָׁבוּעוֹת, מִנְחָתָם שְׁלֹשָׁה עֶשְׂרוֹנִים, וּשְׁנֵי עֶשְׂרוֹנִים. חֲמֵשׁ, דְּאִינּוּן חֲמֵשׁ זִמְנִין עֶשֶׂר. הֲדָא הוּא דִכְתִיב, וּמִנְחָתָם סֹלֶת בְּלוּלָה בַשֶּׁמֶן שְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר הָאֶחָד וּשְׁנֵי עֶשְׂרוֹנִים לָאַיִל הָאֶחָד עִשָּׂרוֹן עִשָּׂרוֹן לַכֶּבֶשׂ הָאֶחָד לְשִׁבְעַת הַכְּבָשִׂים. וְשִׁבְעַת הַכְּבָשִׂים, לָקֳבֵל (ויקרא כ״ג:ט״ו) שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת תִּהְיֶינָה. כָּל חַד עִם שִׁית יוֹמִין דִּילֵיהּ.</p>"],[9520012628,"<p>(במדבר כ״ט:א׳) וּבֶעָשׂוֹר לַחוֹדֶשׁ הַשְּׁבִיעִי, דְּאִיהוּ תִּשְׁרֵי. מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם, דָּא יוֹם הַכִּפּוּרִים. דְּאִיהוּ עֲשִׂירִי י', כָּלִיל מֵעֲשֶׂרֶת יְמֵי תְּשׁוּבָה. וְתַקִּינוּ בֵּיהּ ה' צְלוֹתִין, לְחַבְּרָא לָּהּ עִם ה'. (מאי מקרא קדש. יהיה לכם דא יום הכפורים דאיהי עשירי י', כליל מעשרת ימי תשובה. ותקינו ביה ה' צלותין, לחברא עם ה') מַאי מִקְרָא קֹדֶשׁ. לְאַפְרְשָׁא לֵיהּ מִשְּׁאַר יוֹמִין, דְּאִית בְּהוּ פּוּלְחָנָא דְּחוֹל. וּבְגִין דָּא, כָּל מְלֶאכֶת עֲבוֹדָה לֹא תַעֲשׂוּ.</p>\n<p>דְּיוֹמִין דְּאִית בְּהוֹן מְלֶאכֶת חוֹל, אִינּוּן מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע. דְּאִתְהַפָּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָחָשׁ לְמַטֶּה. לְכָל חַד כְּפוּם עוֹבָדוֹי, וְדָא מְטַטְרוֹן מַטֶּה, נָחָשׁ, סָמָאֵל. אֲבָל בְּהַאי יוֹמָא דְּאִיהוּ יוֹם הַכִּפּוּרִים דְּאִתְקְרֵי קֹדֶשׁ, שַׁלְטָא אִילָנָא דְּחַיֵּי, דְּלָא אִשְׁתְּתַּף עִמֵּיהּ שָׂטָן וּפֶגַע רָע. וּמִסִּטְרֵיהּ (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. וּבְגִין דָּא, בֵּיהּ נַיְיחִין עַבְדִּין בְּאִילָנָא דְּחַיֵּי, (נ\"א ואשתתפן גביה) וּבֵיהּ נַפְקָן לְחֵירוּת, בֵּיהּ נַפְקֵי מִשֻׁלְשְׁלֵיהוֹן.</p>\n<p>אִינּוּן דְּאִית עָלַיְיהוּ גְּזַר דִּין, בְּנֶדֶר וּבִשְׁבוּעָה, וּבְגִין דָּא תַּקִּינוּ לְמֵימַר בֵּיהּ, כָּל נִדְרֵי וְאֵיסָרֵי וְכוּ', כּוּלְהוֹן יְהוֹן שְׁבִיתִין וּשְׁבִיקִין לָא שְׁרִירִין וְלָא קַיָּימִין. וּבְגִין דָּא נֵדֶר דַּיְדוָֹ\"ד, דְּאִיהוּ תִּפְאֶרֶת. וּשְׁבוּעָה דַּאֲדֹנָי, דְּאִיהוּ מַלְכוּת. דְּעַבְדּוּ עַל גָּלוּתָא דִּלְהוֹן, בְּחָכְמָה וּבִינָה יְהוֹן שְׁבִיקִין וּשְׁבִיתִין לָא שְׁרִירִן וְלָא קַיָּימִין, (במדבר ט״ו:כ״ו) וְנִסְלַח לְכָל עֲדַת בְּנֵי יִשְׂרָאֵל. דְּחֶסֶד אִיהוּ מַיִם. גְּבוּרָה אֵשׁ. תִּפְאֶרֶת אַוִּיר. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, הֵתֶּר נְדָרִים פּוֹרְחִים בַּאֲוִיר.</p>\n<p>וּבְגִין דִּשְׁבוּעָה מִמַּלְכוּת, דְּאִיהִי לְתַתָּא מִינֵּיהּ. אוֹקְמוּהָ, נְדָרִים עַל גַּבֵּי שְׁבוּעוֹת עוֹלִים. וְעוֹד אוֹקְמוּהָ, כָּל הַנִּשְׁבַּע כְּאִילּוּ נִשְׁבַּע בַּמֶּלֶךְ עַצְמוֹ. וְכָל הַנּוֹדֵר כְּאִילּוּ נוֹדֵר בְּחַיֵּי הַמֶּלֶךְ. הַמֶּלֶךְ עַצְמוֹ, אֲדֹנָי. חַיֵּי הַמֶּלֶךְ, יְדוָֹ\"ד. וּבְגִין דָּא (במדבר ל׳:ג׳) כִּי יִדּוֹר נֶדֶר לַיְדוָֹ\"ד.</p>\n<p>וְאוֹף הָכִי אִית רָזָא אַחֲרָא, חַיֵּי <Nonei></i>הַמֶּלֶךְ, חָכְמָה. הֲדָא הוּא דִכְתִיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. כָּל הַנּוֹדֵר בַּיְהוָֹה, דְּאִיהוּ תִּפְאֶרֶת. כְּאִילּוּ נוֹדֵר בַּחָכְמָה, דְּאִיהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, חַיֵּי הַמֶּלֶךְ. וְכָל הַנִּשְׁבַּע בַּאדֹנָי, כְּאִילּוּ נִשְׁבַּע בַּמֶּלֶךְ עַצְמוֹ. עַצְמוֹ דָּא אִימָּא עִלָּאָה, כְּאִילּוּ נִשְׁבַּע בָּהּ, דְּאִיהִי (שמות כ״ד:י׳) עֶצֶם הַשָּׁמַיִם לָטוֹהַר. מִסִּטְרָא דְּחֶסֶד, (בראשית ב׳:כ״ג) עֶצֶם מֵעֲצָמַי. וּבָשָׂר מִבְּשָׂרִי, מִסִּטְרָא דִּגְבוּרָה, דָּא מַלְכוּת. וּבְחָכְמָה דְּאִיהִי חַיֵּי תִּפְאֶרֶת, אִיהוּ סָלִיק לְאִתְקְרֵי אָדָם, הֲדָא הוּא דִכְתִיב, (ישעיה מד) כְּתִפְאֶרֶת אָדָם.</p>\n<p>וְאִתְּמַר בְּיוֹם הַכִּפּוּרִים. (ויקרא ט״ז:ל״א) וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם. וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם. תַּקִּינוּ בֵּיהּ ה' עִנּוּיִים, בְּגִין דְּתִתְלַבֵּן ה' זְעֵירָא בְּה' עִלָּאָה, דְּאִיהוּ ה' צְלוֹתִין. לְקַיֵּים בְּיִשְׂרָאֵל, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהַאי אִיהוּ רָזָא דְּלָשׁוֹן שֶׁל זְהוֹרִית, בְּגִין דְּכָל חוֹבִין דְּיִשְׂרָאֵל מָטוּן לְגַבֵּי מַלְכוּת. וּתְשׁוּבָה דְּאִיהִי בִּינָה, מְלַבֶּנֶת לוֹן. בְּגִין דְּאִתְּמַר בָּהּ, (ויקרא ט״ז:ט״ז) הַשּׁוֹכֵן אִתָּם בְּתוֹךְ טוּמְאוֹתָם. וְד' בִּגְדֵי לָבָן, וְד' בִּגְדֵי זָהָב לְמִלְבַּשׁ, יְאֲהדוָֹנָהי.</p>\n<p>וְתַקִּינוּ לִתְקוֹעַ שׁוֹפָר בְּיוֹם הַכִּפּוּרִים, לְסַלְּקָא קוֹל דְּאִיהוּ ו', לְחֵרוּת. דְּאִתְּמַר בָּהּ, (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר, בְּא', וּבְו', קְרֵי וּכְתִיב. וַעֲבוֹדַת יוֹם הַכִּפּוּרִים אִיהִי בַּאֲרִיכוּת, וְאִיהִי כְּלִילָא מִתְּלַת דַּרְגִּין, בְּמַחֲשָׁבָה דִּבּוּר וּמַעֲשֶׂה.</p>"],[9520012629,"<p>(ויקרא כ״ג:ל״ד) בַּחֲמִשָּׁה עָשָׂר יוֹם לַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', דְּאִיהִי תִּשְׁרֵי, מִקְרָא קֹדֶשׁ יִהְיֶה לָכֶם כָּל מְלֶאכֶת עֲבוֹדָה לֹא תַעֲשׂוּ וְחַגּוֹתֶם אוֹתוֹ חַג לַיְיָ שִׁבְעַת יָמִים וְגוֹ'. בַּחֲמִשָּׁה עָשָׂר, מִסִּטְרָא דְּיָ\"הּ. וְחַגּוֹתֶם אוֹתוֹ, דָּא אוֹת ו', עַמּוּדָא דְּאֶמְצָעִיתָא. (ח\"ג חסד גבורה) שִׁבְעַת יָמִים, מִסִּטְרָא דְּבַת שֶׁבַע, דְּאִיהִי מַלְכוּת. אֲבָהָן, וְרַעְיָא מְהֵימָנָא, וְאַהֲרֹן, דָּוִד וּשְׁלֹמֹה, הָא אִינּוּן שֶׁבַע, לָקֳבֵל שֶׁבַע סְפִירָאן. אֲנָא בָּעֵינָא לְתַקְּנָא לְכוֹן סֻכָּה, דְּאִיהִי אִימָּא עִלָּאָה, לְסַכְּכָא עָלַיְיהוּ, כְּאִמָּא עַל בְּנִין.</p>\n<p>וּבְגִין ז' סְפִירָאן אָמַר קְרָא, (ויקרא כ״ג:מ״ג) כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל, בְּמַפְקָנוּתְהוֹן מֵאַרְעָא דְּמִצְרַיִם, בְּז' עֲנָנֵי כָּבוֹד. סוּכָּה (אית באת ו', בסוכות חסר ו', דאתמר בה בסכת תשבו שבעת ימים, איהי אימא אבל סוכה) בְּאָת ו', אִיהוּ בְּרָזָא (דתיבין) דִּתְרֵין בְּנִין, יְדוָֹד אֲדֹנָי. וְהָכִי סָלִיק סוּכָּ\"ה בְּחוּשְׁבַּן יְאֲהדוָֹנָהי. תְּרֵין כְּרוּבִים, דְּהֵם (שמות כ״ה:כ׳) סוֹכְכִים בְּכַנְפֵיהֶם עַל הַכַּפּוֹרֶת וּפְנֵיהֶם אִישׁ אֶל אָחִיו.</p>\n<p>וְאִית עַשְׂרָה טְפָחִים בַּכְּרוּבִים מִתַּתָּא לְעֵילָּא, מֵרַגְלֵיהוֹן עַד רֵישֵׁיהוֹן, וּמֵרֵישֵׁיהוֹן וְעַד רַגְלֵיהוֹן, וְשַׁרְיָין עַל טֶפַח דְּאִיהוּ י'. וְעַשְׂרָה עַשְׂרָה מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא, הַיְינוּ יוֹ\"ד. וּבְגִין כָּךְ, שִׁיעוּרָא דְּסֻּכָּה אָמְרוּ רַבָּנָן, לֹא פָּחוּת מֵעֲשָׂרָה, וְלֹא לְמַעְלָה מֵעֶשְׂרִים. סֻכָּה הַעֲשׂוּיָה כְּכִבְשָׁן מִסִּטְרָא דְּאִימָּא, עָלָהּ אִתְּמַר, (שמות י״ט:י״ח) וְהַר סִינַי עָשָׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. (ואוקמוה מאי (יחזקאל א׳:י״ד) והחיות רצוא ושוב, כאור היוצא מפי הכבשן) וְכֹלָּא חַד.</p>\n<p>(ישעיהו ד׳:ו׳) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם, דִּסְכַךְ בָּעֵינָן. וּסְכַךְ אִתְעָבִיד לַצֵל. דְּאִתְּמַר בֵּיהּ, (תהילים צ״א:א׳) בְּצֵל שַׁדַּי יִתְלוֹנָן. וְלֹא בְּצֵל סֻכַּת הֶדְיוֹט, דְּאָגִין עַל גּוּפָא מִשִׁמְּשָׁא. אֶלָּא צֵל לְאַגָּנָא עַל נִשְׁמְתָא. (שיר השירים ב׳:ג׳) בְּצִלּוֹ חִמַּדְתִּי וְיָשַׁבְתִּי. (איכה ד׳:כ׳) אֲשֶׁר אָמַרְנוּ בְּצִלּוֹ נִחְיֶה בַגּוֹיִם. צֵל עִם ם', אִיהִי צֶלֶם. דְּאִתְּמַר בֵּיהּ, (תהילים ל״ט:ז׳) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ. ם' סְתוּמָה אִית לָהּ אַרְבָּעָה דְּפָנוֹת.</p>\n<p>וּמַה דְּאוּקְמוּהָ שְׁתַּיִם כְּהִלְכָתָן וּשְׁלִישִׁית אֲפִילּוּ טֶפַח. וּלְמַאן דְּאָמַר שְׁלֹשָׁה כְּהִלְכָתָן וּרְבִיעִית אֲפִילּוּ טֶפַח. וְאִינּוּן בְּגִין דָּא, תְּרֵין, תְּלַת, אַרְבַּע, הָא תֵּשַׁע, טֶפַח אִיהִי עֲשִׁירָאָה, לְאַשְׁלְמָא כָּל חֶסְרוֹן. וּבְגִין דָּא, שִׁיעוּר סֻכָּה לֹא פָּחוּת מֵעֶשֶׂר, דְּאִיהִי מַלְכוּת, עֲשִׁירָאָה דְּכָל דַּרְגִּין. וְלָא לְמַעְלָה מֵעֶשְׂרִין, דְּאִיהִי כ', כֶּתֶר עֶלְיוֹן, דְּלָא שַׁלְטָא בֵּיהּ עֵינָא. כָּבוֹד עִלָּאָה, עָלֵיהּ אָמַר מֹשֶׁה, (שמות ל״ג:י״ח) הַרְאֵנִי נָא אֶת כְּבוֹדֶךָ. וְאָתִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לֹא תּוּכַל לִרְאוֹת אֶת פָּנָי. וְלֵית כָּבוֹד, בְּלָא כ'.</p>\n<p>וּבְגִין דָּא שִׂעֵרוּ מָארֵי מַתְנִיתִין לָקֳבְלַיְיהוּ, סֻכָּה הַעֲשׂוּיָה כְּמָבוֹי, מִסִּטְרָא דְּאָת ב', כְּמִין גא\"ם, מִסִּטְרָא דְּאָת ג'. כְּמִין צְרִיף, מִסִּטְרָא דְּאָת ד'. וְשֶׁבַע אַתְוָון אִינּוּן, בְּגִין דָּא כּפר\"ת. כ', כִּבְשָׁן. ב', בּוּרְגָנִין. וּשְׁאַר סֻכּוֹת. וְכֻלְּהוּ רְמִיזֵי לְגַבֵּי מָארֵי מַתְנִיתִין. וְלֵית לְאַרָכָא בְּהוֹן.</p>\n<p>וְאִינּוּן לָקֳבְלַיְיהוּ שִׁבְעָה כֹּכְבֵי לֶכֶת, וְאִינּוּן דְּכַר וְנוּקְבָּא. וּבְגִין דָּא אִתְקְרִיאוּ ז' כְּפוּלוֹת. כְּגוֹן שִׁבְעָה שַׁרְגִּין דִּמְנַרְתָּא, דְּאִתְּמַר בָּהּ (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ. הָכִי (זכריה ד׳:ב׳) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת. הָכִי שִׁבְעָה סְפִירָאן כְּפוּלוֹת. וְשִׁבְעָה יוֹמֵי בְּרֵאשִׁית לְתַתָּא, שִׁבְעָה לְעֵילָּא, (קהלת א׳:ט׳) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ.</p>\n<p>לוּלָב דָּא צַדִּיק. דְּדָמֵי לְחוּט הַשִּׁדְרָה, דְּבֵיהּ ח\"י חוּלְיָין, לָקֳבֵל ח\"י נִעְנוּעִין דְּלוּלָב. וְאִינּוּן לָקֳבֵל ח\"י בִּרְכָאן דִּצְלוֹתָא. לָקֳבֵל שְׁמֹנֶה עֲשַׂר אַזְכָּרוֹת, (תהילים כ״ט:א׳) דְּהָבוּ לַיְיָ בְּנֵי אֵלִים. לָקֳבֵל שְׁמֹנֶה עֲשַׂר אַזְכָּרוֹת דִּקְרִיאַת שְׁמַע. וְנִעְנוּעַ לְשִׁית סִיטְרִין, בְּחוּשְׁבַּן ו'. תְּלַת נִעְנוּעִין בְּכָל סִטְרָא, אִינּוּן ח\"י.</p>\n<p>לוּלָב בַּיָּמִין, כָּלִיל שִׁשָׁה מִינִין (דאינון) ג' <Nonei></i>הֲדַסִּין, גְּדוּלָּה גְּבוּרָה תִּפְאֶרֶת. וְדַמְיָין לִתְלַת גְּוָונֵי עֵינָא. ב' בַּדֵּי עֲרָבוֹת, נֶצַח וְהוֹד. וְדַמְיָין לִתְרֵין שִׂפְוָון. לוּלָב, יְסוֹד, דּוֹמֶה לַשִּׁדְרָה. דְּבֵיהּ קִיּוּם דְּכָל גַּרְמִין. וְעָלֵיהּ אָמַר דָּוִד, (תהילים ל״ה:י׳) כָּל עַצְמוֹתַי תֹּאמַרְנָּה יְיָ מִי כָמוֹךָ. אֶתְרוֹג, מַלְכוּת. דּוֹמֶה לְלִבָּא. דְּבֵיהּ הִרְהוּרִין.</p>\n<p>וְנִעְנוּעִין דְּהַלֵל, אִינּוּן מְשׁוּתָּפִין בְּנִעְנוּעִין דִּנְטִילַת לוּלָב, וְאִינּוּן ח\"י בְּאָנָא. ח\"י ח\"י, בְּהוֹדוּ תְּחִלָּה וָסוֹף. ח\"י דִּנְטִילַת לוּלָב, הֲרֵי ע\"ב. וּבְגִין דָּא לוּלָב בְּחוּשְׁבַּן ח\"ס, וְד' מִינִין דְּלוּלָב, הָא חֶסֶד, דְּרוֹעָא יְמִינָא. וּבְגִין דָּא תַּקִּינוּ לוּלָב בַּיָּמִין, לְסִטְרָא דְּחֶסֶד. אֶתְרוֹג לְסִטְרָא דִּגְבוּרָה, לִשְׂמָאלָא לִבָּא. וּבְגִין דָּא אֶתְרוֹג הַדּוֹמֶה לַלֵּב, תַּקִּינוּ לְמֶהֱוִי בְּיַד שְׂמֹאל. כְּמָה דְּאוּקְמוּהָ, לוּלָב בַּיָּמִין, וְאֶתְרוֹג בִּשְׂמֹאלוֹ. אִינּוּן לָקֳבֵל זָכוֹר וְשָׁמוֹר. וּמַאן נָטִיל תַּרְוַויְיהוּ. עַמּוּדָא דְּאֶמְצָעִיתָא. לוּלָב בִּימִינֵיהּ, וְאֶתְרוֹג בִּשְׂמָאלֵיהּ.</p>\n<p>אָתוּ אֲבָהָן, וְרַעְיָא מְהֵימָנָא, וְאַהֲרֹן וְדָוִד וּשְׁלֹמֹה, וּבָרִיכוּ לֵיהּ, וְאָמְרוּ לֵיהּ, אַנְתְּ בּוּצִינָא קַדִּישָׁא, וְחַבְרַיָּיא דִּילָךְ דְּאִינּוּן שִׁית, לָקֳבֵל אִינּוּן ז'. וְאַנְתְּ בּוּצִינָא קַדִּישָׁא נֵר מַעֲרָבִי בְּאֶמְצַע, דְּכָל שִׁית נֵרוֹת נְהִרִין מִנָךְ. בְּכָל חַד אִתְּמַר בֵּיהּ, (משלי כ׳:כ״ז) נֵר יְיָ נִשְׁמַת אָדָם. וְרַעְיָא מְהֵימָנָא נָהִיר בָּךְ, וְאַנְתְּ בְּחַבְרַיָּיא דִּילָךְ, וְכֹלָּא חַד, בְּלָא פִּרוּדָא כְּלָל. וּמִתַּמָּן וְאִילָךְ מִתְפַּשְּׁטִין עַנְפִין לְכָל מָארֵי חָכְמְתָא, אַשְׁלִים מִלִּין דַּחֲבוּרָא קַדְמָאָה דִּילָךְ לְאַעְטְּרָא לוֹן.</p>\n<p>פָּתַח בּוּצִינָא קַדִּישָׁא וְאָמַר, בְּחִבּוּרָא קַדְמָאָה אִתְּמַר (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וְגוֹ'. מַאי בּוּז. יוֹמָא תִּנְיָינָא, וְיוֹמָא שְׁתִיתָאָה, וְיוֹמָא שְׁבִיעָאָה דְּסוּכּוֹת. דִּבְהוֹן הֲווֹ מְנַסְּכִים מַיִם וְיַיִן.</p>\n<p>דְּשֶׁבַע יוֹמִין דְּסוּכּוֹת, בְּהוֹן הָיוּ מַקְרִיבִין יִשְׂרָאֵל שִׁבְעִים פָּרִים, לְכַפְּרָא עַל שִׁבְעִין מְמָנָן, בְּגִין דְּלָא יִשְׁתְּאַר עָלְמָא חָרוּב מִנַּיְיהוּ. הֲדָא הוּא דִכְתִיב, וּבַחֲמִשָּׁה עָשָׂר יוֹם וְהִקְרַבְתֶּם עוֹלָה אִשֶּׁה לְרֵיחַ נִיחֹחַ לַיְיָ פָּרִים בְּנֵי בָקָר שְׁלֹשָׁה עָשָׂר תְּמִימִים. וּבַיּוֹם הַשֵּׁנִי פָּרִים י\"ב. וּבַיּוֹם הַשְּׁלִישִׁי י\"א. וּבַיּוֹם הָרְבִיעִי עֲשָׂרָה. וּבַיּוֹם הַחֲמִישִׁי פָּרִים תִּשְׁעָה. וּבַיּוֹם הַשִּׁשִּׁי פָּרִים שְׁמֹנֶה. וּבַיּוֹם הַשְּׁבִיעִי שִׁבְעָה. וְכֻלְּהוּ שִׁבְעִין. וּבְכָל יוֹמָא הֲווֹ חָסֵרִים. אֲמַאי חָסֵרִים.</p>\n<p>אֶלָּא הָכָא קָא רָמִיז, (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי. וּמַה הָתָם בְּימֵי טוֹפָנָא, (בראשית ח׳:ד׳) וְהַמַּיִם הָלְכוּ הָלוֹךְ וְחָסוֹר. אוּף הָכִי בְּתִשְׁרֵי, דְּאִיהוּ יַרְחָא שְׁבִיעָאָה, דְּבֵיהּ כַּמָה פִּקוּדִין, רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, סֻכָּה וְלוּלָב אֶתְרוֹג, מִינִין דְּלוּלָב שׁוֹפָר. שְׁכִינְתָּא עִלָּאָה שַׁרְיָיא עַל יִשְׂרָאֵל, דְּאִיהִי תְּשׁוּבָה, סוּכָּה. אֶתְרוֹג, וְקוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ לוּלָב. מִיַּד וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, מִתְמַעֲטִין חוֹבִין דְּיִשְׂרָאֵל, אוּף הָכִי מִתְמַעֲטִין מְמָנָן דְּאִינּוּן מַלְאֲכֵי חַבָּלָה, דִּמְמָנָן עָלַיְיהוּ, דְּדַמְיָין לְמֵי טוֹפָנָא. כְּמָה דְּאוֹקְמוּהָ, עָשָׂה עֲבֵרָה אַחַת קָנָה לוֹ קַטֵיגוֹר אֶחָד. בְּהַהוּא זִמְנָא דְּמִתְמָעֲטִין חוֹבִין, מִתְמַעֲטִין פָּרִים דִּלְהוֹן, מִתְמַעֲטִין מְמָנָן דְּע' אוּמִין, מִתְמַעֲטִין ע' אוּמִין, מִתְמַעֵט טוּבָא דִּלְהוֹן.</p>\n<p>תֵּיבַת נֹחַ, מָנֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאַעֲלָא עִמֵּיהּ (בראשית ז׳:ג׳) שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה זָכָר וּנְקֵבָה, לְקָרְבָּנָא, לְאַגָּנָא עַל נֹחַ, וְעַל כָּל אִינּוּן דְּעָאלִין עִמֵּיהּ לַתֵּיבָה. אוּף הָכִי אִלֵּין דִּמְנַטְּרִין חַגִּין וּזְמַנִין, דְּאִינּוּן יָמִים טוֹבִים, שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה, שְׁנַיִם שְׁנַיִם תְּרֵין יוֹמִין דְרֹאשׁ הַשָּׁנָה, וּתְרֵין יוֹמִין דְּשָׁבוּעוֹת, וּבְגִין דְּאִינּוּן תְּרֵין מִנַּיְיהוּ בְּסָפֵק, הָא אִית שְׁנֵי יְמֵי הַפּוּרִים בְּאַתְרַיְיהוּ. שִׁבְעָה שִׁבְעָה, ז' יוֹמִין דְּפֶסַח, ז' יוֹמִין דְּסוּכּוֹת. נֹחַ לָקֳבֵל יוֹם הַשַּׁבָּת, וְהַאי אִיהוּ מִכָּל הַחַי.</p>\n<p>סֻכָּה קָא אֲגִינָת עָלַיְיהוּ דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (ישעיהו ד׳:ו׳) וְסֻכָּה תִּהְיֶה לְצֵל יוֹמָם מֵחֹרֶב. סֻכָּה קָא אֲגִינָת. מַה תֵּיבַת נֹחַ לְאַגָּנָא, אוּף הָכִי סֻכָּה לְאַגָּנָא. (תיקונין ב ע\"א) וְעוֹד מִכָּל הַחַי, ח\"י בִּרְכָאן דִּצְלוֹתָא, מֵאִינּוּן ט' ט', בִּרְכָתָא דְּמִינִין בָּהּ אִשְׁתְּלִימוּ י' סְפִירָאן מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. וְאִיהוּ לָקֳבֵל נֹחַ.</p>\n<p>וְעוֹד מִכָּל הַחַי, שְׁכִינְתָּא אֲגִינָת עַל אִלֵּין דְּנַטְרִין י', אוֹת שַׁבָּת בִּתְחוּמָא דִּילֵיהּ, דְּאִיהוּ ח' אֲלָפִים, תְּרֵין אַלְפִין לְכָל צַד. וְעוֹד, מִכָּל הַחַי, אִלֵּין דְּנַטְרִין י' אוֹת בְּרִית, דְּאִיהוּ בְּח' יוֹמִין, דְּאִתְּמַר עָלַיְיהוּ, (ויקרא י״ב:ג׳) וּבַיּוֹם הַשְּׁמִינִי יִמּוֹל בְּשַׂר עָרְלָתוֹ. וְעוֹד, מִכָּל הָחַי, אִלֵּין דְּנַטְרִין אוֹת י', תְּפִלִּין בִּתְמַנְיָיא פָּרַשְׁיָין.</p>\n<p>שְׁכִינְתָּא דְּאִיהִי סוּכָּה, אֲגִינָת עָלַיְיהוּ, וּפְרִישַׁת גַּדְפָּאָה עָלַיְיהוּ, כְּאִמָּא עַל בְּנִין, וּבְגִין דָּא תַּקִּינוּ לְבָרְכָא, הַפּוֹרֵס סוּכַּת שָׁלוֹם עָלֵינוּ. וּבְגִין דָּא בְּיַרְחָא שְׁבִיעָאָה, דְּבֵיהּ כָּל פִּקּוּדִין אִלֵּין, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. עַם יִשְׂרָאֵל בַּאֲבוּהוֹן שֶׁבַּשָּׁמַיִם. וְלֵית מַיִם רַבִּים, אֶלָּא כָּל אוּמִין וּמְמָנָן דִּלְהוֹן. אִם יִתֵּן אִישׁ, דְּאִיהוּ סָמָאֵל, כָּל מַה דְּאִית לֵיהּ בְּעָלְמָא דֵּין, בְּגִין <Nonei></i>דְּיִשְׁתָּתַּף בְּאִלֵּין פִּקוּדִין עִם יִשְׂרָאֵל, בּוֹז יָבוּזוּ לוֹ.</p>"],[9520012630,"<p>וּבַיּוֹם הַשְּׁמִינִי עֲצֶרֶת פַּר אֶחָד אַיִל אֶחָד, הָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, לְמַלְכָּא דְּזַמִּין אוּשְׁפִּיזִין, לְבָתַר דְּשָׁלַח לוֹן, אָמַר לְאִלֵּין בְּנֵי בֵּיתָא דִּילֵיהּ, אֲנָא וְאַתּוּן נַּעְבִיד סְעוּדָה קְטַנָּה. וּמַאי עֲצֶרֶת. כְּמָה דְאַתְּ אָמֵר, (שמואל א ט׳:י״ז) זֶה יַעְצוֹר בְּעַמִּי, וְלֵית עֶצֶר אֶלָּא מַלְכוּת. מִסִּטְרָא דִּשְׁכִינְתָּא עִלָּאָה, עָבִיד סְעוּדָתָא רַבְרְבָא, וּמִסִּטְרָא דְּמַלְכוּתָא, סְעוּדָתָא זְעֵירָא. וְנוֹהֲגִין לְמֶעְבַּד יִשְׂרָאֵל עִמָּהּ חֶדְוָה, וְאִתְקְרִיאַת שִׂמְחַת תּוֹרָה. וּמְעַטְּרָן לְסֵפֶר תּוֹרָה בְּכֶתֶר דִּילֵיהּ, רֶמֶז סֵפֶר תּוֹרָה לְתִפְאֶרֶת, שְׁכִינְתָּא עֲטֶרֶת תִּפְאֶרֶת.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אַבָּא, אֲמַאי מִסִּטְרָא דְּאִמָּא עִלָּאָה, זַמִּין לְכָל מְמָנָן דְּכָל אוּמִין, וּמִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה, לָא זַמִּין אֶלָּא לְאוּמָה יְחִידָה, לָקֳבֵל פַּר יְחִידָא.</p>\n<p>אָמַר לֵיהּ בְּרִי, שַׁפִּיר שְׁאִילַת. בְּגִין דְּמַלְכוּת אִיהִי רְמִיזָא לִבְרַתָּא, דְּאִיהִי צְנוּעָה בְּבֵית אָבִיהָ וְאִמָּהּ. וְאִיהִי אֲרוּסָה וְלָא נְשׂוּאָה. לָאו אוֹרַח אַרְעָא, לְמֵיכַל עִם אוֹשְׁפִּיזִין. אֲבָל אִימָּא דְּהִיא נְשׂוּאָה, אוֹרַח אַרְעָא אִיהוּ (למיכל עם אורחי) בָּתַר דִּמַזְמִּין בַּעְלָהּ אוֹשְׁפִּיזֵי, לְמֵיכַל עַל פָּתוֹרָא עִם בַּעְלָהּ. וְאִי אִינּוּן אוּשְׁפִּיזִין נֻכְרָאִין, לָא אַכְלֵי עִמְּהוֹן, לָא אַבָּא, וְלָא אִמָּא, וְכָל שֶׁכֵּן בְּרַתָּא. וּבְגִין כַּךְ בִּסְעוּדָתָא דְּשִׁבְעִין מְמָנָן, לָא אִשְׁתְּתַּף לְמֵיכַל עִמְּהוֹן, חַד מִן מָארֵי מַלְכָּא, בְּגִין דְּאִינּוּן נוּכְרָאִין. אָמַר לֵיהּ ודַּאי כְּעַן אִתְיַישְּׁבַת מִלָּה בְּלִבָּאִי, עַל בּוּרְיֵיהּ.</p>"],[9520012631,"<p>עוֹלַת תָּמִיד, דָּא שְׁכִינְתָּא, דִּסְלִיקַת לְעֵילָּא בְּהַהוּא דַּרְגָּא, דְּאִתְּמַר בָּהּ עֶרֶב וָבוֹקֶר בְּכָל יוֹם תָּמִיד, וְאוֹמְרִים פַּעֲמַיִם שְׁמַע יִשְׂרָאֵל. וְאִיהִי סְלִיקַת בְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ תָּדִיר עִמָּהּ בְּלָא פִּרוּדָא כְּלָל.</p>\n<p>וּלְאָן סְלִיקַת. לְאֲתָר דְּאִתְגְּזָרַת מִתַּמָּן, דְּאִיהוּ אֵין סוֹף, וְאִיהוּ גָּבוֹהַּ מִכָּל סְפִירָאן. וּבְגִין דָּא אוֹקְמוּהָ. עוֹלָה כֻּלָהּ לַגָּבוֹהַּ סַלְּקָא. וְכַד אִיהִי סְלִיקַת, אֲחִידָן בָּהּ כָּל סְפִירָן, וְאִינּוּן סַלְּקִין עִמָּהּ. וּמַאי סְלִיקוּ דִּילָהּ. לְרֵיחַ נִיחֹחַ, לְמֵיהַב רֵיחָא טָבָא קֳדָם יְיָ, וּלְבָתַר אִתְּמַר בָּהּ, (ויקרא ט׳:כ״ב) וַיֵּרֶד מֵעֲשׂוֹת הַחַטָּאת וְהָעוֹלָה. נַחְתַּת מַלְיָא כַּפָּרָה מִכָּל חוֹבִין דְּיִשְׂרָאֵל.</p>\n<p>וְהָא סְלִיקוּ דִּילָהּ אִיהוּ, בְּעַמּוּדָא דְּאֶמְצָעִיתָא. אוּף הָכִי נְחִיתוּ דִּילָהּ אִיהוּ בֵּיהּ, וְכָל חַיָּילִין דִּילָהּ, וּבְגִין דָּא אִקְרֵי סֻלָּם, דְּבֵיהּ כָּל הַוָויָין (נ\"א כנויין) סַלְּקִין וְנַחְתִּין, דְּאִינּוּן תַּלְיָין מִן יְדוָֹד. וּבְגִין דָּא, כָּל קָרְבְּנִין וְעִלָּוָון אִינּוּן לַיְדוָֹד. וְאִתְקְרִיאַת קָרְבָּן, עַל שֵׁם דְּאִתְקְרִיבוּ בָּהּ כָּל כִּנּוּיִין לַיְדוָֹד.</p>\n<p>וּבְגִין דָּא אִתְּמַר עָלָהּ, (במדבר ז׳:י״ט) קָרְבָּנוֹ קַעֲרַת כֶּסֶף אַחַת. לֵית דַּרְגָּא דְּאִתְקְרִיב לְגַבֵּי יְדוָֹד, פָּחוּת מִנָּהּ. וְלֵית צְלוֹתָא וּפִקּוּדָא מִכָּל פִּקוּדִין דְּאוֹרַיְיתָא, וְכָל קָרְבְּנִין וְעִלָּוָון, דְּאִינּוּן לְבַר מִנָּהּ. בְּכָל דַּרְגִּין דִּסְפִירָאן לָא מִתְקַבְּלָן קֳדָם יְדוָֹד, לְבַר מִנָּהּ. וּבְגִין דָּא אִתְּמַר עָלָהּ, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. וּבְגִין דָּא אָמַר נָבִיא, (ירמיהו ט׳:כ״ג) כִּי אִם בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל.</p>\n<p>אִיהִי שְׁלָמִים, שְׁלִימוּ דִּשְׁמָא דַּיְדוָֹד, בְּכָל דַּרְגָּא וְדַרְגָּא. אִיהִי ה'. אֲדֹנָי. י' דַּיְדוָֹד. אִיהִי ה' מִן אֱלֹהִים. אִיהִי ה' מִן אֶהְיֶה. י' מִן שַׁדַּי. סוֹף דְּכָל הֲוָיָה וְכִנּוּי. וּבְגִין דָּא אִתְּמַר בָּהּ, (קהלת י״ב:י״ג) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹהִים יְרֵא וְאֶת מִצְוֹתָיו שְׁמוֹר. אִיהִי סוֹף מֵעֶשֶׂר סְפִירָאן, יַם סוּף. שְׁלִימוּ דְּעִלָּאִין וְתַתָּאִין. אִיהוּ תַּרְעָא לְאַעֲלָא לְכָל חָכְמְתָא, לְכָל כִּנּוּי וַהֲוָיָה, וּלְאַעֲלָא בְּכָל סְפִירָה וּסְפִירָה, יְדִיעָה דְּכֹלָּא. וּפָחוּת מִינָהּ, לֵית רְשׁוּ לְשׁוּם בִּרְיָה, לְאַשְׁגָּחָא לְשׁוּם יְדִיעָה בָּעוֹלָם. עָלָהּ אִתְּמַר, (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ צַדִּיקִים יָבֹאוּ בוֹ.</p>\n<p>אִיהוּ שֵׁם מ\"ב אַתְוָון, דִּבְהוֹן אִתְבְּרִיאוּ עִלָּאִין וְתַתָּאִין. (ואלין אינון אתוון כנויין לאתוון דהוויין דבהון אתבריאו עלאין) אִיהִי אִתְקְרִיאַת עַיִן מִסִּטְרָא דִּימִינָא, (תהילים ל״ג:י״ח) הִנֵּה עֵין יְדוָֹד אֶל יְרֵאָיו. וְאִתְקְרִיאַת אֹזֶן מִסִּטְרָא דִּשְׂמָאלָא, (דניאל ט׳:י״ח) הַטֵּה אֱלֹהַי אָזְנְךָ וּשֲׁמָע. וְאִתְקְרִיאַת רֵיחַ מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִתְקְרִיאַת פֶּה, מִגַּרְמָהּ. הֲדָא הוּא דִכְתִיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.</p>\n<p>אִתְקְרִיאַת פִּקּוּדָא קַדְמָאָה אָנֹכִי, מִסִּטְרָא דְּכֶתֶר, דְּאִיהוּ אַיִ\"ן מֵאֱלֹהֵינוּ. אָנֹכִי בֵּיהּ כ', כֶּתֶר. וּבֵיהּ אַיִן. וְכֶתֶר אִתְקְרֵי מִסִּטְרָא דְּאִימָּא עִלָּאָה. דְּאִדְכַּר לְגַבָּהּ חַמְשִׁין זִמְנִין יְצִיאַת מִצְרַיִם בְּאוֹרַיְיתָא. וְאִיהִי בַּ\"ת מִן בְּרֵאשִׁית, דִּכְלִילָא עֶשֶׂר אֲמִירָן, מִסִּטְרָא דְּחָכְמָה בַּת י', (משלי ג׳:י״ט) בְּחָכְמָה יָסַד אֶרֶץ. בְּאַבָּא יָסַד בְּרַתָּא. וְאִיהוּ (איוב כ״ח:ז׳) נָתִיב לֹא יְדָעוֹ עָיִט, דְּכָלִיל ל\"ב נְתִיבוֹת, דְּאִינּוּן ל\"ב אֱלֹהִים מִסִּטְרָא דְּאִימָּא עִלָּאָה, דְּאִתְקְרֵי כָּבוֹד. וְכַד אִתְכְּלִילָן בִּבְרַתָּא, אִתְקְרֵי ל\"ב. וּבְגִין דָּא כָּבוֹד לְעֵילָּא, ל\"ב לְתַתָּא.</p>\n<p>וְי' דִּבְּרָן אִתְיְיהִיבוּ. חֲמֵשׁ בְּלוּחָא חֲדָא, וַחֲמֵשׁ בְּלוּחָא תִּנְיָינָא. אִיהִי כָּלִיל לוֹן, ה' מִכֶּתֶר עַד גְּבוּרָה. וְה' מֵעַמוּדָא דְּאֶמְצָעִיתָא, עַד <Nonei></i>בְּרַתָּא. וְאִינּוּן ה' ה'. וְכִי אִית לְמַלְּלָא בַּעֲשַׂרָה פִּיּוֹת. אֶלָּא כָּלִיל לוֹן בְּבַת יְחִידָה י' וְאִתְעָבִידוּ כֻּלְּהוּ חֲדָא. אוּף הָכִי ו', אִתְקְרֵי קוֹל, וְלָא אִשְׁתְּמוֹדְעִין בֵּיהּ, עַד דְּאִשְׁתָּתַּף עַד (ס\"א עם) דִּבּוּר. וּבְגִין דָּא, (דברים ד׳:י״ב) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים.</p>\n<p>אִיהִי פִּקּוּדָא תִּנְיָנָא מִסִּטְרָא דִּגְבוּרָה, יִרְאָה בְּחוּשְׁבָּן. וּרְמִיזָא בְּמִלַּת בְּרֵאשִׁית, יָרֵא בֹּשֶׁת. וְאוֹקְמוּהָ, מַאן דְּלֵית לֵיהּ בֹּשֶׁת פָּנִים, וַדַּאי דְּלָא עָמְדוּ אֲבָהֲתוֹי עַל טוּרָא דְּסִינַי.</p>\n<p>אִיהִי פִּקּוּדָא תְּלִיתָאָה, דְּאִתְקְרֵי אַהֲבַת חֶסֶד. הֲדָא הוּא דִכְתִיב, (ירמיהו ל״א:ג׳) אַהֲבַת עוֹלָם אַהֲבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד. אַהֲבָה כְּלִילָא מֵאֲבָהָן, דְּאִתְקְרֵי בְּהוֹן בַּכֹּל מִכֹּל כֹּל. וְרָזָא דְּמִלָּה, (ירמיהו ב׳:ב׳) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתָיִךְ.</p>\n<p>וְאִיהִי פִּקּוּדָא רְבִיעָאָה, יִחוּד, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, שְׁמַע יִשְׂרָאֵל. וְאִיהִי כ\"ה כ\"ה אַתְוָון, עִמֵּיהּ בְּשִׁית תֵּיבִין, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל. וּבְגִינָהּ אָמַר אַבְרָהָם (בראשית כ״ב:ה׳) נֵלְכָה עַד כ\"ה וְנִשְׁתַּחֲוְה. (שמות י״ט:ג׳) כֹּ\"ה תֹאמַר לְבֵית יַעֲקֹב.</p>\n<p>אִיהוּ א\"ח, עַמּוּדָא דְּאֶמְצָעִיתָא, וְאִיהִי ד', שְׁלִימוּ דְּיִחוּדָא דִּילֵיהּ, לְאַשְׁלְמָא בֵּיהּ אֶחָד. א\"ח, כָּלִיל ט' סְפִירָאן, דְּאִינּוּן א' אֵין סוֹף. ח' תְּמַנְיָא סְפִירָאן, מֵחָכְמָה עַד יְסוֹד. ד' מַלְכוּת, קוֹצָא דִּילָהּ, בָּהּ אִשְׁתְּלִימוּ לְעֲשַׂרָה, דְּאִינּוּן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. ד' כְּלִילָא מְד' אַתְוָון יְדוָֹד.</p>\n<p>פִּקּוּדָא חֲמִישָׁאָה, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. אִיהִי אוֹרַיְיתָא דְּבִכְתָב מִסִּטְרָא דְּחֶסֶד. וְאוֹרַיְיתָא דִּבְעַל פֶּה מִסִּטְרָא דִּגְבוּרָה. דִּבְהוֹן חָכְמָה וּבִינָה. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, הָרוֹצֶה לְהַחְכִּים יַדְרִים. לְהַעֲשִׁיר יַצְפִּין. וְעַמּוּדָא דְּאֶמְצָעִיתָא כָּלִיל תַּרְוַויְיהוּ, וּבְגִין דָּא אִתְקְרֵי שָׁמַיִם, כָּלִיל אֵשׁ וּמַיִם, אֵשׁ דִּגְבוּרָה, וּמַיִם דְּחֶסֶד.</p>\n<p>וּבְגִין דָּא כֶּתֶר, (תיקונין קל\"ד) דְּאִיהִי כַּף, (במדבר ז׳:פ״ו) עַשָׂרָה עַשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. דְּאִינּוּן יה\"ה, תְּלַת אַתְוָון, אִתְעָבִידוּ כַּף, עַל ו'. וְהַיְינוּ כְּנֶגֶד כֶּתֶר תּוֹרָה, ו' הַיְינוּ סֵפֶר תּוֹרָה, כַּף עֲטָרָה עַל רֵישֵׁיהּ. וְכֹלָּא יְדוָֹ\"ד, כ\"ו בְּחוּשְׁבַּן.</p>\n<p>פִּקּוּדָא שְׁתִּיתָאָה, אִיהִי תְּפִלָּה שֶׁל יַד, בִּדְרוֹעָא שְׂמָאלָא. וּמִסִּטְרָא דִּגְבוּרָה ה' דְּיַד כֵּהָה, מִכֶּתֶר וְעַד גְּבוּרָה, ה' סְפִירָאן, וְאִינּוּן תְּפִילִּין דְּרֵישָׁא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאִיהִי קֶשֶׁר תְּלַת רְצוּעוֹת, דְּאִינּוּן נֶצַח הוֹד יְסוֹד.</p>\n<p>וְאִיהִי פִּקּוּדָא שְׁבִיעָאָה, מִצְוַת צִיצִית, כָּלִיל תְּכֵלֶת וְלָבָן, דִּינָא וְרַחֲמֵי. בְּנוּרָא, אֶשָּׁא חִוָּורָא לָא אָכִיל. תְּכֵלָא, אָכִיל וְשָׁצֵי, (מלכים א י״ח:ל״ח) וַתֹּאכַל אֶת הָעוֹלָה. חִוָּור מִימִינָא, תְּכֵלֶת מִשְּׂמָאלָא, עַמּוּדָא דְּאֶמְצָעִיתָא, יִחוּד בֵּין תַּרְוַויְיהוּ, יָרוֹק. בְּגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחְרִין מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. וּבְגִין דָּא תַּקִּינוּ פָּרָשַׁת צִיצִית, לְמִקְרֵי לָהּ בְּיִחוּדָא.</p>\n<p>וְאִיהִי פִּקּוּדָא תְּמִינָאָה, מְזוּזָה. שְׁכִינְתָּא אִתְקְרִיאַת מְזוּזָה, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּאַתְוָון דַּיְדוָֹ\"ד. וּמִסִּטְרָא דְּצַדִיק, רָזָא דִּבְרִית, אִתְקְרֵי שַׁדַּי. שַׁדַּי חוֹתָמָא דְּמַלְכָּא, דְּאִיהוּ יְדוָֹד.</p>\n<p>פִּקּוּדָא תְּשִׁיעָאָה, שְׁכִינְתָּא אִתְקְרִיאַת אוֹת בְּרִית, מִסִּטְרָא דְּצַדִּיק יְסוֹד עוֹלָם. (בראשית ט׳:י״ב) זֹאת אוֹת הַבְּרִית. (שמות לא) בֵּינִי, עַמּוּדָא דְּאֶמְצָעִיתָא, וּבֵין בְּנֵי יִשְׂרָאֵל, נֶצַח הוֹד. אוֹת, דָּא צַדִּיק. הִיא, דָּא שְׁכִינְתָּא. כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָּׁמַיִם, מִכֶּתֶר עַד עַמּוּדָא דְּאֶמְצָעִיתָא. דְּלֵית שִׁית בְּכָל אֲתָר, אֶלָּא מִסִּטְרָא דְּאָת ו'. וְלֵית שְׁבִיעִי, אֶלָּא מִסִּטְרָא דְּאָת י', עֲטָרָה עַל רֵישֵׁיהּ חָכְמָה עִלָּאָה. אוֹת הוּא. חָכְמָה תַּתָּאָה, אוֹת הִיא.</p>\n<p>וְתַקִּינוּ לְמִגְזַר לִתְמַנְיָא, דְּאִינּוּן ח', מִן חָכְמָה עַד יְסוֹד. לְקַבְּלָא בְּהוֹן י' זְעֵירָא, לְסַלְּקָא לָהּ עַד כֶּתֶר, לְמֶהֱוִי עֲטָרָה עַל רֵאשֵׁיהוֹן. וְתַקִּינוּ לְשָׁוּוּיָא לַעָרְלָה בְּמָנָא דְּעַפְרָא, לְקַיֵּים (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ.</p>\n<p>פִּקּוּדָא עֲשִׁירָאָה, (שמות ל״א:ט״ז) וְשָׁמְרוּ בְּנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. שְׁכִינְתָּא אִתְקְרִיאַת שַׁבָּת, מִסִּטְרָא דִּתְלַת דַּרְגִּין עִלָּאִין דְּאִינּוּן ש', ג' כִּתְרִין: כֶּתֶר, חָכְמָה, וּבִינָה. וְאִיהִי בַּת, רְבִיעָאָה לוֹן. שִׁית יוֹמִין, מֵחֶסֶד עַד יְסוֹד, בְּהוֹן תַּעֲשֶׂה מְלָאכָה, בְּגִין דְּבִנְיָינָא מַתְחִיל מֵחֶסֶד, הֲדָא הוּא דִכְתִיב, (תהילים פ״ט:ג׳) עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִבִּינָה וּלְעֵילָּא, אִיהִי מְנוּחָה וְעֹנֶג וּשְׁבִיתָה לְכָל עוֹבָדָא.</p>\n<p>פִּקּוּדָא חַד סָר, אִיהִי אִתְקְרִיאַת צְלוֹתָא דְּשַׁחֲרִית מִנְחָה עַרְבִית, מִסִּטְרָא דִּתְלַת אֲבָהָן, וְאִיהִי תְּפִלַּת כָּ\"ל פֶּ\"ה, לֵית כָּל, אֶלָּא צַדִּיק דִּכְתִּיב, (דברי הימים א כ״ט:י״א) כִּי כֹל בַּשָׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם יוֹנָתָן בֶּן עוּזִיאֵל, דְּאָחִיד בִּשְׁמַיָּיא וּבְאַרְעָא. פֶּ\"ה כְּחוּשְׁבַּן מִילָה. וּמַה בְּרִית בֵּיהּ מִתְיַחֲדִין דְּכַר וְנוּקְבָּא דִּלְתַּתָּא, אוּף בַּיְסוֹד, מִתְיַיחֵד חָתָן וְכַלָּה דִּלְעֵילָּא, הוּא חַי עָלְמִין כָּלִיל חַ\"י בִּרְכָאן, הֲדָא הוּא דִכְתִיב, (משלי י׳:ו׳) בְּרָכוֹת לְרֹאשׁ צַדִּיק.</p>\n<p>וּבְגִין דָּא, כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ וְכָל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם. דָּא שְׁכִינְתָּא, בְּשֵׁם דַּיְדוָֹ\"ד, בֵּיהּ צָרִיךְ לְזַקְפָא שְׁכִינְתָּא. הַהִיא דְּאִתְּמַר בָּהּ, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף <Nonei></i>קוּם בְּתוּלַת יִשְׂרָאֵל, עַל יְדֵי דַּרְגָּא אַחֲרָא, וּבְגִין דָּא (עמוס ט׳:י״א) בַּיוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת. הַהוּא דְּאִתְּמַר בֵּיהּ, (תהילים קמ״ו:ד׳) יְדוָֹ\"ד זוֹקֵף כְּפוּפִים.</p>\n<p>פִּקּוּדָא תְּרֵיסָר, אִיהִי אִתְקְרִיאַת חַג הַמַּצּוֹת, וְחַג הַשָּׁבוּעוֹת, וְחַג הַסֻּכּוֹת, מִסִּטְרָא דְּג' אֲבָהָן. ורֹאשׁ הַשָּׁנָה מִסִּטְרָא דִּילָהּ, דִּינָא דְּמַלְכוּתָא דִּינָא. וְאִית דְּיֵימָא, פֶּסַח דְּרוֹעָא יְמִינָא. שָׁבוּעוֹת, מַתַּן תּוֹרָה, דְּאִתְיְיהִיבַת בְּמַדְבְּרָא, דְּאִיהוּ מְמָנָא עָלֵיהּ שׁוֹר, מִסִּטְרָא דִּגְבוּרָה. סֻכּוֹת (בראשית ל״ג:י״ז) וְיַעֲקֹב נָסַע סֻכּוֹתָה. פִּקּוּדָא תְּלֵיסַר, קְרִיאַת שְׁמַע.</p>"],[9520012632,"<p>וְאִית לְמִנְדַּע, דְּאִיהוּ אִתְקְרֵי חָכָם בְּכָל מִינֵי חָכְמוֹת. וּמֵבִין, בְּכָל מִינֵי תְּבוּנוֹת. וְחָסִיד, בְּכָל מִינֵי חֲסָדִים. וְגִבּוֹר, בְּכָל מִינֵי גְּבוּרוֹת. וְיוֹעֵץ, בְּכָל מִינֵי עֵצוֹת. וְצַדִּיק, בְּכָל מִינֵי צְדָקוֹת. וָמֶלֶךְ, בְּכָל מִינֵי מַלְכוּת. עַד אֵין סוֹף. עַד (ס\"א כתר) אֵין חֵקֶר. וּבְכָל אִלֵּין דַּרְגִּין, בְּחַד אִקְרֵי רַחֲמָן. וּבְחַד אִקְרֵי דַּיָּין. וְהָכִי בְּכַמָּה דַּרְגִּין, עַד אֵין סוֹף. אִי הָכִי שִׁנּוּי אִית, בֵּין רַחֲמָן לְדַּיָּין. אֶלָּא קוֹדֶם דְּבָרָא עָלְמָא, אִתְקְרֵי הוּא בְּכָל אִלֵּין דַּרְגִּין, עַל שֵׁם בִּרְיָין דַּהֲווֹ עֲתִידִין לְהִבָּרְאוֹת, דְּאִי לָאו בִּרְיָין דְּעָלְמָא, אֲמַאי אִתְקְרֵי רַחוּם דַּיָּין, אֶלָּא עַל שֵׁם בִּרְיָין דַּעֲתִידִין.</p>\n<p>וּבְגִין דָּא, כָּל שְׁמָהָן, אִינּוּן כִּנּוּיִין דִּילֵיהּ. עַל שֵׁם עוֹבָדִין דִּילֵיהּ. כְּגַוְונָא דָּא, בָּרָא נִשְׁמְתָא, בְּדִיּוּקְנָא דִּילֵיהּ, דְּאִתְקְרִיאַת עַל שֵׁם פְּעוּלוֹת דִּילָהּ, בְּכָל אֵבֶר וְאֵבֶר דְּגוּפָא, דְּאִתְקְרֵי עָלְמָא זְעֵירָא. כְּגַוְונָא דְּמָארֵי עָלְמָא, אִתְנְהִיג בְּכָל בִּרְיָין. וּבְכָל דָּרָא, כְּפוּם עוֹבָדוֹי. כַּךְ נִשְׁמְתָא, כְּפוּם עוֹבָדוֹי דְּכָל אֵבֶר וְאֵבֶר. הַהוּא אֵבֶר דְּעָבִיד בֵּיהּ פִּקּוּדָא, אִתְקְרֵי נִשְׁמְתָא, לְגַבֵּי חֶמְלָה וְחִסְדָּא חִנָּא וְרַחֲמֵי. וּבְהַהוּא אֵבֶר דְּעָבִיד בֵּיהּ עֲבֵירָה, אִתְקְרֵי נִשְׁמְתָא לְגַבֵּי, דִּינָא וְחֵימָה וָכָעַס. אֲבָל לְבַר מִן גּוּפָא, לְמַאן תְּהֵא חֶמְלָה, אוֹ אַכְזָרִיוּת.</p>\n<p>אוּף הָכִי מָארֵי עָלְמָא, קֹדֶם דְּבָרָא עָלְמָא, וּבָרָא בִּרְיָין דִּילֵיהּ, לְמַאן אִתְקְרֵי רַחוּם וְחַנּוּן אוֹ דַּיָּין. אֶלָּא כָּל שְׁמָהָן דִּילֵיהּ, אִינּוּן כִּנּוּיִין, וְלָא אִתְקְרֵי בְּהוֹן, אֶלָּא עַל שֵׁם בִּרְיָין דְּעָלְמָא, וּבְגִין דָּא, כַּד מָארֵי דָּרָא אִינּוּן טָבִין, אִיהוּ אִתְקְרֵי לְגַבַּיְיהוּ, יְהוָֹ\"ה בְּמִדַת רַחֲמִים. וְכַד מָארֵי דָּרָא אִינּוּן חַיָּיבִין, אִתְקְרֵי אֲדֹנָ\"י בְּמִדַת הַדִּין. לְכָל דָּרָא, וּלְכָל בַּר נָשׁ, כְּפוּם מִדָּה דִּילֵיהּ. אֲבָל לָאו דְּאִית לֵיהּ מִדָּה וְלָא שֵׁם יְדִיעַ.</p>\n<p>כְּגַוְונָא דִּסְפִירָאן, דְּכָל סְפִירָה אִית לָהּ שֵׁם יְדִיעַ, וּמִדָּה, וּגְבוּל, וּתְחוּם. וּבְאִלֵּין שְׁמָהָן מָארֵי עָלְמָא אִיהוּ אִתְפְּשַּׁט, וְאַמְלִיךְ בְּהוֹן, וְאִתְקְרֵי בְּהוֹן, וְאִתְכַּסֵּי בְּהוֹן, וְדָר בְּהוֹן, כְּנִשְׁמְתָא לְגַבֵּי אֵבָרִים דְּגוּפָא. וּמַה רִבּוֹן עָלְמִין, לֵית לֵיהּ שֵׁם יְדִיעַ וְלָא אֲתָר יְדִיעַ, אֶלָּא בְּכָל סִטְרָא שׁוּלְטָנוּתֵיהּ. אוּף הָכִי לֵית לָהּ לְנִשְׁמְתָא שֵׁם יְדִיעַ, וְלָא אֲתָר יְדִיעַ, בְּכָל גּוּפָא אֶלָּא בְּכָל סְטָר שׁוּלְטָנוּתֵיהּ, וְלֵית אֵבֶר פָּנוּי מִנָּהּ.</p>\n<p>וּבְגִין דָּא, לֵית לְרַשְּׁמָא לָהּ בְּחַד אֲתָר, דְּאִי לָאו הָא חָסֵר שׁוּלְטָנוּתָא בִּשְׁאַר אֵבָרִים. וְלָא לְאִתְקְרֵי לָהּ בִּשְׁמָא חַד, אוֹ בִּתְרֵין, אוֹ בְּג'. לְמֵימָר דְּאִיהִי חָכְמָה מִבִּינָה, וְאִית לָהּ דַּעַת, וְלָא יַתִּיר. דְּאִי עָבִיד הָכִי, הָא חָסֵר לָהּ מִשְּׁאַר דַּרְגִּין.</p>\n<p>כָּל שֶׁכֵּן לְמָארֵי עָלְמָא, דְּלֵית לְרַשְׁמָא לֵיהּ בַּאֲתָר יְדִיעַ, אוֹ לְאִתְקְרֵי לֵיהּ בִּשְׁמָהָן, אוֹ לְשַׁנָּאָה לֵיהּ בְּהוֹן, אוֹ (ס\"א לשלשא) לְשַׁלְּטָאָה לֵיהּ כְּגוֹן דַּרְגָּא דְּמֶרְכַּבְתָּא, דְּאִתְּמַר בָּהּ קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ, דְּכָל דַּרְגִּין דְּכָל מַרְכְּבוֹת דִּילֵיהּ, אִינּוּן מְשׁוּלָּשִׁים, כְּגוֹן הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, דְּאִינּוּן דְּמוּת אַרְיֵה שׁוֹר נֶשֶׁר, דְּאִינּוּן מֶרְכָּבָה לְאָדָם. דְּאִתְּמַר עָלֵיהּ, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּמִסִּטְרָא דְּנוּקְבָּא, אִינּוּן שַׁלְטִין עַל אָדָם, וְנוּקְבָּא אִיהִי מֶרְכָּבָה לְגַבַּיְיהוּ. וּבְגִין דָּא אִתְּמַר עָלָהּ, קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ.</p>\n<p>וְאוֹף הָכִי אַתְוָון, דְּאִינּוּן אַנְפִּין דְּחֵיוָן, מְשׁוּלָּשִׁין, כְּגַוְונָא דָּא: יד\"ו. הו\"י. וה\"י. ה' רְבִיעָאָה, קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ. אִיהִי שְׁלָמִים דְּכֻלְּהוּ, לְאַשְׁלְמָא בְּכֻלְּהוּ שֵׁם יְדוָֹ\"ד. אֲבָל לְמָארֵיהּ דְּכֹלָּא, לֵית לְשַׁלְּשָׁא בֵּיהּ בִּשְׁמָהָן, וְלָא בְּאַתְוָון, אֶלָּא אִיהוּ אִתְקְרֵי בְּכָל שְׁמָהָן, וְלֵית לֵיהּ שֵׁם יְדִיעַ. וְכָל שֵׁם וְשֵׁם אַסְהִיד עָלֵיהּ, דְּאִיהוּ אֲדוֹן כָּל עָלְמִין. אַסְהִיד עָלֵיהּ אֲדֹנָי.</p>\n<p>וְלֵית דְּיַדְעִין דְּאִית בַּר נָשׁ, דְּיָרִית ג' מֵאָה וְעֶשֶׂר עָלְמִין, הֲדָא הוּא דִכְתִיב, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֶשׁ. כְּפוּם דַּרְגָּא דִּילֵיהּ, דְּאִתְקְרֵי יֵשׁ מֵאַיִן. וְדָא חָכְמָה עִלָּאָה. וְאִית בַּר נָשׁ דְּלָא יָרִית אֶלָּא עָלְמָא חַד, כְּפוּם דַּרְגָּא דִּילֵיהּ, כְּמָה דְּאוֹקְמוּהָ, כָּל צַדִּיק וְצַדִּיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ. וְהָכִי יָרִית עָלְמִין כָּל בַּר נָשׁ מִיִשְׂרָאֵל, כְּפוּם דַּרְגָּא דִּילֵיהּ לְעֵילָּא. אֲבָל לְמָארֵי עָלְמָא, לֵית לְרַשְׁמָא לֵיהּ עָלְמִין בְּחוּשְׁבָּן, אֶלָּא אֲדוֹן כָּל עָלְמִין, וְאֲדֹנָ\"י קָא סָהִיד עָלֵיהּ.</p>\n<p>אוּף הָכִי יְהוָֹ\"ה, מִנֵּיהּ תַּלְיָיא כָּל הֲוָיָין, וְאִיהוּ וְכָל הֲוָיָין דִּילֵיהּ, סָהֲדִין עַל מָארֵי עָלְמָא, דְּאִיהוּ הֲוָה קֹדֶם כָּל הֲוָיָין. וְאִיהוּ בְּתוֹךְ כָּל הֲוָיָה. וְאִיהוּ לְאַחַר כָּל הֲוָיָה. וְדָא רָזָא, דְּסָהֲדִין הַוָיָין עָלֵיהּ, הָיָה, הוְֹה, וְיִהְיֶה.</p>\n<p>דִּינָא, בְּהִפּוּךְ אַתְוָון אֲדֹנָ\"י. וּבְגִין דָּא אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, דִּינָא דְּמַלְכוּתָא דִּינָא. שֵׁם אֵ\"ל סָהִיד עַל מָארֵי דְּכֹלָּא, דְּלֵית יְכוֹלֶת לְכָל שֵׁם, וַהֲוָיָה וְדַרְגָּא. כָּל שֶׁכֵּן לִשְׁאַר בִּרְיָין, פָּחוּת מִנֵּיהּ. הֲדָא הוּא דִּכְתִּיב, (דניאל ד׳:ל״ב) כְּלָא <Nonei></i>חֲשִׁיבָין וּכְמִצְבְּיֵהּ עָבֵּיד בְּחֵיל שְׁמַיָא וְגוֹ'. אֱלֹהִי\"ם, סָעִיד עַל אֱלָהוּת דִּילֵיהּ, דְּאִיהוּ אֱלֹהִי\"ם וִאלהֵי הָאֱלֹהִים, וְאִיהוּ אֱלוֹהַּ עַל כֹּלָּא, וְלֵית אֱלוֹהַּ עָלֵיהּ. צְבָאוֹ\"ת, סָהִיד עָלֵיהּ כְּדִכְתִיב, וּכְמִצְבְּיֵיהּ עָבִיד בְּחֵיל שְׁמַיָא. שַׁדַּ\"י, סָהִיד עָלֵיהּ, דְּכַד אִיהוּ אָמַר לְעוֹלָם דַּי עָמַד בִּתְחוּמֵיהּ, וְלָא אִתְפְּשָּׁט יַתִּיר. וְאוּף לְמַיָּא וְרוּחָא וְאֶשָּׁא.</p>\n<p>וְאוֹף הָכִי, כָּל הֲוָיָה, וְשֵׁם, סָהֲדִין עָלֵיהּ. דְּכַד הֲוָה אִיהוּ יָחִיד קוֹדֶם דְּבָרָא עָלְמָא, אֲמַאי הֲוָה אִיהוּ צָרִיךְ לְאִתְקְרֵי בִּשְׁמָהָן אִלֵּין, אוֹ בִּשְׁאַר כִּנּוּיִין, כְּגוֹן (שמות ל״ד:ו׳) רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְגוֹ', דַּיָּין אַמִּיץ חָזָק. וְסַגִּיאִין בְּכָל אִינּוּן שְׁמָהָן וְכִנּוּיִין, אִתְקְרֵי עַל שֵׁם כָּל עָלְמִין וּבִרְיָין דִּלְהוֹן, לְאַחֲזָאָה שׁוּלְטָנוּתֵיהּ עָלַיְיהוּ.</p>\n<p>אוּף הָכִי נִשְׁמְתָא, (תיקונין כ\"ד ע\"א) עַל שׁוּלְטָנוּתָא דְּכָל אֵבָרִים דְּגוּפָא, אַמְתִּיל לָהּ לְגַבֵּיהּ. לָאו דְּאִיהִי אַדְמְיָא לֵיהּ אִיהִי בְּעַצְמָהּ, דְּהוּא בָּרָא לָהּ, וְלֵית לֵיהּ אֱלוֹהַ עָלֵיהּ דְּבָרָא לֵיהּ. וְעוֹד, נִשְׁמְתָא אִית לָהּ כַּמָה שִׁנּוּיִים וּמִקְרִים וְסִבּוֹת, דְּאִתְקְרִיאוּ לָהּ. מַה דְּלָאו הָכִי לְמָארֵי כֹּלָּא. וּבְגִין דָּא הִיא אַדְמְיָא בְּשָׁלְטָנוּתָא דִּילָהּ עַל כָּל אֵבָרֵי גּוּפָא, אֲבָל לָא בְּמִלָּה אַחֲרָא.</p>"],[9520012633,"<p>וְעוֹד, (דברים ו) שְׁמַע יִשְׂרָאֵל, שֵׁם ע' רַבָּתִי, ד' מִן אֶחָ\"ד רַבָּתִי, הַיְינוּ עֵ\"ד, בֵּין שֵׁ\"ם מִן שְׁמַע, א\"ח מִן אֶחָ\"ד. (שמואל א י״ב:ה׳) עֵד יְיָ בָּכֶם. וְעַל כָּל אֶחָד וְאֶחָד דִּמְיַחֵד אוֹתוֹ בָּעוֹלָם. וְעַל כֵּן אָמַר דָּוִד, (תהילים ק״ד:ל״ד-ל״ה) אָנֹכִי אֶשְׂמַח בַּיְיָ, (עיין לעיל רל\"ו ע\"ב) ש\"מ מִן שְׁמַע, א\"ח מִן אֶחָ\"ד, הֲרֵי אֶשְׂמַח.</p>\n<p>וְעוֹד. ד' רַבָּתִי, ד' בָּתֵּי תְּפִילִּין, דְּמָנַח לְהוֹן א\"ח, וְאִתְעֲטָּר בְּהוּ, וְאִינּוּן פְּאֵר עַל רֵישֵׁיהּ. וְאִינּוּן יהו\"ה (ס\"א יהה\"ו), י' עֲטָרָא עַל ה', דְּאִיהִי בְּרַתָּא, וְהַיְינוּ (משלי ג׳:י״ט) יְדוָֹ\"ד בְּחָכְמָה יָסַד אָרֶץ, אַבָּא יָסַד בְּרַתָּא. ה', אִמָּא עִלָּאָה, עֲטָרָה עַל ו', דְּאִיהוּ בְּרָא, וְהַיְינוּ (משלי ג׳:י״ט) כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בְּאִמָּא כּוֹנֵן בְּרָא. וְהַאי אִיהוּ דְּעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם.</p>"],[9520012634,"<p>וּבְרַתָּא אִיהִי תְּפִלָּה שֶׁל יַד, כֵּהָ\"ה. י' קֶשֶׁר דִּילֵיהּ. ה' עִלָּאָה אִימָּא, תְּפִלִּין דְּרֵישָׁא עַל רֹאשׁ תִּפְאֶרֶת. תְּפִלִּין דִּילֵיהּ, כְּסֵדֶר יְדוָֹ\"ד, דְּאִיהוּ קַדֶּשׁ לִי. וְהָיָה כִּי יְבִאֲךָ. שְׁמַע. וְהָיָה אִם שָׁמוֹעַ. אֲבָל בְּעָלְמָא דְּאָתֵי, הֲוָיוֹת בְּאֶמְצַע, דְּאִינּוּן ה' ה'. וּבְגִין דָּא אָמַר הַנָבִיא, (ירמיהו ט׳:כ״ג) בְּזֹאת יִ\"תְהַלֵּל הַ\"מִתְהַלֵּל הַ\"שְׂכֵּל וְ\"יָדוֹעַ אוֹתִי כִּי אֲנִי יְדוָֹ\"ד. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּאִית בְּרֵישָׁא אֲתָר, לְאָנָחָא תְּרֵי זּוּגֵי דִּתְפִלֵּי. וְדָא זָכֵי לִתְרֵין פִּקוּדִין, דְּאוֹקְמוּהָ עָלַיְיהוּ, לֹא כָּל אָדָם זוֹכֶה לִשְׁתֵּי שׁוּלְחָנוֹת.</p>\n<p>י' חָכְמָה. ה' בִּינָה. ו' עַמּוּדָא דְּאֶמְצָעִיתָא. ה' מַלְכוּת קַדִּישָׁא. רֵישָׁא דְּאִתְעַטָּר בְּאַרְבַּע אַתְוָון, דָּא כֶּתֶר רִיהֲטָא דְּרֵישָׁא דְּאַסְחַר לוֹן, וְכַסֵּי לוֹן. אַהֲבָה חֶסֶד קְרִיאַת שְׁמַע, דִּשְׁקִילָא לְאוֹרַיְיתָא, דְּאִתְיְיהִיבַת מִימִינָא. תְּפִלִּין עֹז, מִשְּׂמָאלָא דִּגְבוּרָה. עַמּוּדָא דְּאֶמְצָעִיתָא, כָּלִיל כֹּלָּא, כַּנְפֵי דְּמִצְוָה, נֶצַח וְהוֹד, תְּכֵלֶת וְלָבָן. מְזוּזָה רָשִׁים שַׁדַּי, צַדִּיק. וּשְׁכִינְתָּא תַּרְעָא דִּמְזוּזָה, זֶה הַשַּׁעַר לַיְדוָֹ\"ד.</p>\n<p>וְעוֹד ש' תְּלַת רְצוּעוֹת. ד' קֶשֶׁר שֶׁל תְּפִילִּין מֵאֲחוֹרוֹי. י' קֶשֶׁר דִּתְפִלִּין דְּיָד. וּבְגִין דָּא שַׁדַּ\"י מִלְּבַר, יְדוָֹ\"ד מִלְּגוֹ, דְּאִיהִי ד' פָּרְשִׁיָין. דד' רָאשִׁין רֶמֶז לד' בָּתֵּי דִּתְפִילִּין, שַׁדַּ\"י אוֹת דִּילֵיהּ עוֹלֶה מטטרו\"ן.</p>\n<p>וְעוֹד. י' חָכְמָה קַדֶּשׁ לִי. ה' בִּינָה, וְהָיָה כִּי יְבִיאֲךָ. ו' שְׁמַע, שִׁית תֵּיבִין, רְמִיזָא לְשִׁית סְפִירָן, שִׁית עַנְפִין דְּאִילָנָא, דְּכָלַל לוֹן תִּפְאֶרֶת. ה' וְהָיָה אִם שָׁמוֹעַ מַלְכוּת. אִלֵּין אִינּוּן דְּרֵישָׁא, דְּאִיהוּ כֶּתֶר, כ', (שמואל א ב׳:ב׳) אֵין קָדוֹשׁ כַּיְיָ כִּי אֵין בִּלְתֶּךָ.</p>\n<p>שַׁדַּי, רָמִיז רְצוּעֵי וּבָתֵי וְקִשְׁרֵי דִּתְפִלִּין מִלְּבַר. אוּף הָכִי בַּמְּזוּזָה, יְדוָֹ\"ד מִלְּגוֹ, שַׁדַּ\"י מִלְּבַר, דְּאַרְבַּע רָאשִׁין עִם ד' רָמִיז לד' בָּתֵּי וּלְקֶשֶׁר תְפִלִּין מֵאָחוֹר ד' כְּפוּלָה אוּף הֲכִי ש' כְּפוּלָה, י' קֶשֶׁר דְיָד כֵּהָה דְּאִיהוּ בֵּיתָא חֲמִישָׁאָה ד' (ס\"א י') דְּשַׁדַּ\"י אִיהוּ מוֹחָא דּאוּקְמוּהַ עָלֵיהּ בַּמָּקוֹם שְׁמוֹחוֹ שֶׁל תִינוֹק רוֹפֶס בּוֹ, וְדָא תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ שַׁדַּ\"י.</p>\n<p>תְּפִלִּין דְּמָארֵי עָלְמָא, כֶּתֶר. וּמַאי נִיהוּ כֶּתֶר דְּמָארֵי עָלְמָא. יְדוָֹ\"ד. דְּאִיהוּ: י' חָכְמָה. ה' בִּינָה. ו' תִּפְאֶרֶת. כָּלִיל שִׁית סְפִירָין. ה' מַלְכוּת. וּבְגִין דָּא (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ כְּיִשְׂרָאֵל (דברים ד׳:ז׳) כִּי מִי גּוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרוֹבִים אֵלָיו, כַּיְיָ אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. אַרְבַּע קְרָאֵי, כֻּלְּהוּ רְשִׁימִין בְּכ', רָזָא דְּאָת כ': י' י'. דְּאִיהִי י' י' מִן יְאֲהדוָֹנָהי, (במדבר ז׳:פ״ו) עַשָׂרָה עַשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ, כּ' מִן כֶּתֶר, כְּלִילָא מֵעֶשֶׂר סְפִירָאן, כְּלִילָן מֵעֵילָּא לְתַתָּא, וּמֵעֶשֶׂר סְפִירָאן מִתַּתָּא לְעֵילָּא.</p>\n<p>וְאִלֵּין אִינּוּן, (תהילים קמ״ח:ד׳) וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם, מַיִם עֶלְיוֹנִים זְכָרִים, מַיִם תַּחְתּוֹנִים נְקֵבוֹת. וְעָלַיְיהוּ אָמַר רִבִּי עֲקִיבָא לְתַלְמִידָיו, כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר, אַל תֹּאמְרוּ מַיִם מַיִם, שֶׁמָא תִּסְתַּכְּנוּ בְּנַפְשְׁכֶם. דְּלָאו אִינּוּן מַיִם כְּמַשְׁמָעָן. אֶלָּא אִיהוּ אוֹר נוֹבֵעַ. וּבְגִין דָּא, אִדְּמוּ לְמַיִם נוֹבְעִים. וְהַאי נְהוֹרָא לֵית לֵיהּ פְּסָק, וְלֹא קִצוּץ, וּפִרוּד. וּבְגִין דְּאִינּוּן מִכֶּתֶר, אִתְקְרִיאָן שֶׁאֵין לָהֶם סוֹף, דְּכֶתֶר אֵין סוֹף אִתְקְרֵי. (ע\"כ רעיא מהימנא).</p>"],[9520012635,"<p><Nonei></i>(במדבר כ״ח:כ״ז) וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַיְיָ. תָּא חֲזֵי, בְּפֶסַח כְּתִיב, וְהִקְרַבְתֶּם אִשֶּׁה עוֹלָה לַיְיָ. וְהָכָא לָא כְּתִיב אִשֶּׁה, (דהא ביומא דא אשה לא כתיב ביה) אֶלָּא וְהִקְרַבְתֶּם עוֹלָה. מַאי טַעְמָא. יוֹמָא דָּא, יוֹמָא דְּעַיְילַת כַּלָּה לְחוּפָּה אִיהוּ. וְיִשְׂרָאֵל מָנוּ יוֹמִין דְּדַכְיוּ. יוֹמִין וְשָׁבוּעִין, וְאִתְכְּלִילוּ וְעָאלוּ בְּיוֹמִין דְּדַכְיוּ. וְהִיא נַפְקַת מִכָּל סִטְרָא בִּישָׁא, וְנַטְרַת יוֹמֵי דַּכְיוּ כַּדְּקָא חֲזֵי. וְרָזָא דָּא, מַלְכָּא טַעַם בְּתוּלָה טָעִים. בְּגִין כָּךְ לָא כְּתִיב בֵּיהּ אִשֶּׁה, דְּהָא אַחֲרָא לָא קָרִיב לְמַשְׁכְּנָא, וְהָא אִתְרְחַק מִתַּמָּן. וְעַל דָּא אִשִּׁים לָאו הָכָא, וְלָאו אִצְטְרִיכוּ לְהָכָא, וְיִשְׂרָאֵל מְרַחֲקָן אִינּוּן מִן סִטְרָא בִּישָׁא. (ומנן יומין דדכיו, יומין ושבועין, ואתכלילו ועאלו ביומין דדכיו). אָמַר רִבִּי אַבָּא, עֲדַיִין צְרִיכִין אֲנָן לְפִתְחָא דָּא לְמִפְתַּח.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֲרִימִית יְדַי בְּצַלּוּ לְמַאן דְּבָרָא עָלְמָא, וְרָזָא דָּא, אַשְׁכְּחָן בְּסִפְרֵי קַדְמָאֵי, אִשִּׁים אִינּוּן בְּאֶמְצָעִיתָא, וְאַתְיָין בְּסִטְרָא דָּא וּבְסִטְרָא דָּא, אִדַבְּקוּ בְּאִילָנָא דְּדַעַת טוֹב וָרָע, אִדַבְּקָן בְּרָע, וְאִדַבְּקָן בְּטוֹב. וּבְגִין כָּךְ, בִּשְׁאַר יוֹמִין כְּתִיב בְּהוּ אִשֶּׁה עוֹלָה. אֲבָל בְּהָנֵי יוֹמָא, דְּאִילָנָא דְּחַיֵּי קַיְּימָא, וְלָא אַחֲרָא, לֵית אֲנָן צְרִיכִין לְאִשֶּׁה, וְלָא אִצְטְרִיךְ לְמֶהֱוִי תַּמָּן. וְיוֹמָא דָּא, יוֹמָא דְּאִילָנָא דְּחַיֵּי אִיהוּ, וְלָא דְּדַעַת טוֹב וָרָע. וּבְגִין דָּא, וְהִקְרַבְתֶּם עוֹלָה לְרֵיחַ נִיחֹחַ לַיְיָ, וְלָא אִשֶׁה לַיְיָ עוֹלָה. וְעוֹלָה, לָשׁוֹן (נ\"א לשם) עוֹלֶה, כְּמָה דְּאִתְּמַר, וְהָא אִתְּעַרְנָא מִלֵּי דְּפָרִים בְּנֵי בָּקָר, וְכָל הַהוּא קָרְבָּן.</p>\n<p>(במדבר כ״ט:א׳) וּבַחֹדֶשׁ הַשְּׁבִיעִי, כְּמָה דְּאִתְּמַר, יוֹמָא דְרֹאשׁ הַשָּׁנָה, דִּינָא דְּכָל עָלְמָא, דִּינָא תַּקִּיפָא, וְדִינָא רַפְיָא. וַעֲשִׂיתֶם עוֹלָה, וְהִקְרַבְתֶּם מִבָּעֵי לֵיהּ, כִּשְׁאַר כָּל יוֹמִין, מַאי וַעֲשִׂיתֶם. אֶלָּא בְּיוֹמָא דָּא, (בראשית כ״ז:ד׳) וַעֲשֵׂה לִי מַטְעַמִּים כְּתִיב. כַּמָה מַטְעַמִּים וְתַבְשִׁילִים עָבְדוּ יִשְׂרָאֵל בְּהָנֵי יוֹמֵי, בְּעוֹד דִּמְקַטְרְגָא אָזִיל לְפַשְׁפְּשָׁא בְּחוֹבִין דְּעָלְמָא. וְעַל דָּא לָא כְּתִיב וְהִקְרַבְתֶּם, אֶלָּא וַעֲשִׂיתֶם עוֹלָה. וְלָא אִשֶּׁה עוֹלָה. וְכֵן בְּכָל שְׁאַר יוֹמִין, (ס\"א בקרבנין) לָא כְּתִיב אִשֶּׁה, דְּלֵית לוֹן חוּלָקָא בְּכָל הָנֵי יוֹמֵי. כָּל שֶׁכֵּן בְּהַאי יוֹמָא, דַּאֲנָן עַבְדִּין מַטְעַמִּים וְתַבְשִׁילִים בְּלָא דַּעְתָּא דְּסִטְרָא אַחֲרָא, דְּהָא יִצְחָק מְשַׁדֵּר לֵיהּ לָצוּד צֵידָה דְּחוֹבִין דִּבְנֵי עָלְמָא, וּלְאַיְיתָאָה לְגַבֵּיהּ.</p>\n<p>וּבְעוֹד דְּאִיהוּ אָזִיל, יִשְׂרָאֵל נַטְלֵי עֵיטָא בְּרִבְקָה, וְעַבְדִין כָּל אִינּוּן פּוּלְחָנִין, כָּל אִינּוּן צְלוֹתִין, מְזַמְּנֵי שׁוֹפָר וְתַקְעִין לֵיהּ, בְּגִין לְאַתְּעָרָא רַחֲמֵי. וְהָא אוֹקִימְנָא, (בראשית כ״ז:כ״ה) וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ, דְּאָתֵי (ס\"א דאכל) מֵרָחוֹק, מִגּוֹ אֲתָר דְּחַמְרָא עַתִּיקָא, וְשָׁתֵי. וְאַטְעִים לֵיהּ, וְחַדֵּי. וְאַחַר כַּךְ מְבָרֵךְ לֵיהּ בְּכַמָּה בִּרְכָאן, וְאַעְבַּר עַל חוֹבוֹי. מַה כְּתִיב, (בראשית כ״ז:ל׳) וַיְהִי אַךְ יָצוֹא יָצָא יַעֲקֹב וְעֵשָׂו אָחִיו בָּא מִצֵּדוֹ, טָעִין מִכַּמָּה טוֹעֲנֵי כְּמָה דְּאִתְּמַר, וְהָא אוֹקִימְנָא מִלָּה.</p>\n<p>וּבְגִין כָּךְ אִיהוּ יוֹמָא דִּיבָבָא, וְקָרְבְּנָא אִיהוּ עוֹלָה. אַיִל אֶחָד, כְּמָה דְּאִתְּמַר, בְּגִין אֵילוֹ דְּיִצְחָק. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת, שׁוֹחַד לְסַמָאֵל לְכַפְּרָה (לתברא) אַנְפּוֹי, בְּהַהוּא בִּכְיָה דְּאִיהוּ בָּכֵי בְּהַאי יוֹמָא, כֵּיוָן דְּחָמֵי דְּלָא אִתְעָבִיד רְעוּתֵיהּ, וְהָא לְמַגָּנָא צַד צֵידָה. כְּמָה דְּאִתְּמַר. כְּגַוְונָא דָּא יוֹמָא דְּכִפּוּרֵי, וְהָא כְּתִיב בְּפָּרָשַׁת אֱמוֹר.</p>"],[9520012636,"<p>(במדבר כ״ט:י״ב) וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ'. רִבִּי אַבָּא פָּתַח, (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', תָּא חֲזֵי, כָּל הָנֵי יוֹמִין, אַזְלַת אִימָּא עַל בְּנַיָּיא, בְּגִין דְּלָא יִשְׁלוֹט סִטְרָא אַחֲרָא עָלַיְיהוּ, וּבְגִין לְשֵׁזָבָא לוֹן. כֵּיוָן דְּאִשְׁתְּזִיבוּ בְּנָהָא, וְהָא יַתְבִין בַּסֻּכּוֹת, מִתְנַטְּרִין בִּנְטוּרָא. יוֹמָא קַדְמָאָה, וְיוֹמָא תִּנְיָנָא, פַּקְדַת לוֹן לְיִשְׂרָאֵל, לְמֶעְבַּד סְעוּדָתָא לִמְּמָנָן דִּשְׁאַר עַמִּין, וְאִיהִי לָא שַׁרְיָא תַּמָּן. בְּיוֹמָא תְּלִיתָאָה, דְּאִיהוּ י\"ז לַחֹדֶשׁ, שָׁרִיאַת לְמִשְׁרֵי עָלַיְיהוּ. הֲדָא הוּא דִכְתִיב, וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט, טוּרִין דְּכָל לְוָוטִין וּמְרָדִין שָׁרָאן בְּגַוַויְיהוּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, יוֹמָא קַדְמָאָה דְּחַג, לָא שַׁרְיָא עָלַיְיהוּ, וְלָא יוֹמָא תִּנְיָינָא, אֶלָּא יוֹמָא תְּלִיתָאָה, דְּאוֹסִיף וְגָרַע שַׁרְיָא עָלַיְיהוּ, אוֹסִיף אַתְוָון, וְגָרַע קָרְבְּנִין. דִּכְתִּיב עַשְׁתֵּי עָשָׂר וְגוֹ'. וְהָכִי אִתְחֲזֵי לְרַע עַיִן, בְּגִין דְּיוֹמָא קַדְמָאָה וְיוֹמָא תִּנְיָינָא חֶדְוָה דִּבְנָהָא, וְאִינּוּן מְפַלְגֵּי עִדָּאָן לוֹן. מִיּוֹמָא תְּלִיתָאָה וּלְהָלְאָה, דְּאִיהִי שַׁרְיָא עָלַיְיהוּ, מַה כְּתִיב. (בראשית ח׳:ה׳) וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר עַד הַחֹדֶשׁ הָעֲשִׂירִי בָּעֲשִׂירִי בְּאֶחָד לַחֹדֶשׁ נִרְאוּ רָאשֵׁי הֶהָרִים <Nonei></i>וְהַמַּיִם הָיוּ הָלוֹךְ וְחָסוֹר, אִלֵּין קָרְבְּנִין, דְּאַזְלִין וּמִתְמַעֲטִין. וּכְמָה דְּאִינּוּן מִתְמַעֲטִין, הָכִי נָמֵי אִתְמְעַט טוּבָא דִּלְהוֹן.</p>"],[9520012637,"<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, תָּא חֲזֵי, מִיּוֹמָא תִּנְיָינָא שָׁרִיאוּ מַיָּיא לְאִתְחֲזָאָה, כֵּיוָן דְּשָׁרִיאוּ מַיִם, מִיּוֹמָא תְּלִיתָאָה אִיהִי שָרַת עָלַיְיהוּ, וְאִינּוּן מַיִם לָא הֲווֹ יַדְעֵי בַּבְלָאֵי (ס\"א בכולא), אֲמַאי רְשִׁימִין הָכָא, דְּהָא טוּבָא דְּיִשְׂרָאֵל לָא הֲוִי בַּאֲתָר דְּמִעוּטָא, אֶלָּא בַּאֲתָר דְּרִבּוּיָיא. וּבְגִין דְּאִלֵּין מַיִין דִּרְשִׁימִין הָכָא אִתְמַעֲטָן, אָתֵי קְרָא לְאַשְׁמְעִינָן דִּכְתִּיב, וְהַמַּיִם אִינּוּן דִּיְדִיעָן בְּיוֹמֵי דְּחַג, אִינּוּן דִּרְשִׁימִין גּוֹ קָרְבְּנִין, דְּאִינּוּן טוּרֵי לְוָוטִין, הָיוּ הָלוֹךְ וְחָסוֹר טוּבָא דִּלְהוֹן, וּנְגִידוּ דְּאַנְגִּיד עָלַיְיהוּ, הָיוּ הָלוֹךְ וְחָסוֹר, וּבְגִין דְּאִינּוּן מַיִם דִּלְהוֹן הוּא, לָא אִתְחַבְּרָן אַתְוָון, דְּלָא יִתְחַבָּר טוּבָא דִּלְהוֹן, אֶלָּא זְעֵיר זְעֵיר.</p>\n<p>אֲבָל לְיִשְׂרָאֵל, דְּאִינּוּן מְּקוּדְשָׁא בְּרִיךְ הוּא, מַה כְּתִיב. (תהילים ל״ד:י״א) וְדוֹרְשֵׁי יְיָ לֹא יַחְסְרוּ כָּל טוֹב. רֵישֵׁיהּ דִּקְרָא, כְּפִירִים רָשׁוּ וְרָעֵבוּ, אִלֵּין מְמָנָן דִּשְׁאַר עַמִּין. וְדוֹרְשֵׁי יְיָ, אִלֵּין יִשְׂרָאֵל, לֹא יַחְסְרוּ כָּל טוֹב, אִלֵּין אַזְלִין וְאִסְתַּלָּקוּ לְעֵילָּא לְעֵילָּא. וּבְגִין כָּךְ, טוּבָא דִּלְהוֹן דְּאִינּוּן מַיִם, הָיוּ הָלוֹךְ וְחָסוֹר. עַד הַחֹדֶשׁ הָעֲשִׂירִי. דָּא טֵבֵת, דְּהָא כְּדֵין יְמֵי הָרָעָה הֲווֹ, וְאִתְעֲרַת הַהִיא רָעָה וְאִתְתַּקְפַת, וְכַלָּה קַדִּישָׁא לָא אַנְהִירַת מִגּוֹ שִׁמְשָׁא, כְּדֵין נִרְאוּ רָאשֵׁי הֶהָרִים, אִלֵּין אִינּוּן הֲרֵי חֲשׁוֹכָא, טוּרִין דִּלְוָוטִין אִתְחָזוּן וְאִתְתְּקָפוּ, וְעַבְדִין בִּישִׁין בְּעָלְמָא.</p>\n<p>בְּיוֹמִין אִלֵּין, אִשֶּׁה בְּהַאי עוֹלָה, דְּהָא כְּדֵין הָנֵי אִשִּׁים אָכְלֵי חוּלָקֵיהוֹן. שִׁבְעִים פָּרִים אִלֵּין, אִינּוּן לָקֳבֵל שִׁבְעִים מְמָנָן, דְּשַׁלְטוּ עַל שִׁבְעִין עַמִּין. וְסַלְּקִין בְּיוֹמָא קַדְמָאָה, וְנַחְתֵּי בְּכָל יוֹמָא וְיוֹמָא, וְאִקְרוּן פָּרִים מְנַגְּחִין בְּיוֹמִין דִּלְהוֹן. אֵילִם, (חסר) אַרְבֵּיסָר, תְּרֵין בְּכָל יוֹמָא אִינּוּן יָ\"ד יְהוָֹ\"ה. יְדָא דְּשָׁלִיטָא עָלַיְיהוּ תָּדִיר, בְּכָל יוֹמָא וְיוֹמָא. אַמְרִין בְּנֵי שָׁנָה, מִנְיָינָא דִּלְהוֹן חֵ\"ץ.</p>\n<p>וְאִי תֵּימָא אִי הָכִי, רַע עַיִן הֲוִינָן לְגַבַּיְיהוּ. אִין, דְּהָא כְּתִיב, (משלי כ״ה:כ״ב) כִּי גֶּחָלִים אַתָּה חוֹתֶה עַל רֹאשׁוֹ. אֲבָל אֲנָן לָא יַהֲבֵינָן אֶלָּא בְּחֶדְוָותָא, דְּלֵית בְּיוֹמֵי שַׁתָּא, חֶדְוָותָא, כְּאִלֵּין יוֹמִין. וּבְגִין דַּאֲנָן יָהֲבִין בְּטוּב לִבָּא, וּבְחֶדְוָותָא דִּרְעוּתָא, אִתְהַפָּךְ עָלַיְיהוּ גֶּחָלִים עַל רֵישֵׁיהוֹן, גּוּמְרִין מְלַהֲטָן, דְּחֶדְוְותָא דִּילָן, עַבְדֵי לוֹן בִּישׁ. י\"ד, (ס\"א ה') ע', וחץ. כַּךְ סַלְּקִין בְּחוּשְׁבָּנָא דִּילְהוֹן.</p>\n<p>וְכָל דָּא אִיתֵּימָא מַאן יָהִיב לָן לְאַקְרְבָא עָלַיְיהוּ, דִּלְמָא אִינּוּן לָא בָּעָאן כָּל דָּא. אֶלָּא לֵית חֶדְוָוה לְכָל אִינּוּן מְמָנָן, בְּכָל אִינּוּן תּוֹרִים אֵילִים וְאִמְרִין כְּהָנֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל יַהֲבֵי לוֹן סְעוּדְתִּין אִלֵּין. וְעִם כָּל דָּא לָא מִתְקַרְבוּ כֹּלָּא, אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, וְאִינּוּן מִתְקָרְבֵי תַּמָּן, וְאִיהוּ פָּלִיג לוֹן. וְעַל דָּא כְּתִיב, (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם, אִלֵּין אִינּוּן קָרְבְּנִין דְּחָג. וְאִם צָמֵא הַשְׁקֵהוּ מָיִם, אִלֵּין מַיִם דִּרְשִׁימִין הָכָא בְּיוֹמֵי דְּחָג. וּבְיוֹמָא תִּנְיָינָא, וּבְיוֹמָא שְׁתִּיתָאָה וּשְׁבִיעָאָה, וְסִימָן (שיר השירים ח׳:ז׳) בּוֹ\"ז יָבוּזוּ לוֹ.</p>\n<p>מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, אִלֵּין אִינּוּן מַיִם, דִּי מְנַסְּכֵי יִשְׂרָאֵל, בְּחֶדְוָה וּבִרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (ישעיהו י״ב:ג׳) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן. וּנְהָרוֹת לֹא יִשְׁטְפוּהָ, אִלֵּין אִינּוּן נַהֲרֵי דְּאֲפַרְסְמוֹנָא דַּכְיָא, דְּכֻלְּהוּ דַּבְקֵי וּמִתְקַשְּׁרֵי בִּרְחִימוּ דָּא. אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בְּאַהֲבָה בּוֹז יָבוּזוּ, דָּא סַמָאֵל, בְּאַהֲבָה דְּיִשְׂרָאֵל, לְמֶהֱוִי לֵיהּ חוּלָקָא בַּהֲדַיְיהוּ, בְּאִינּוּן מַיִם דִּרְשִׁימִין הָכָא בְּפַרְשְׁתָּא, דִּכְתִּיב אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בְּאַהֲבָה בּוֹז יָבוּזוּ, סִימָנָא דְּאִינּוּן מַיִם בּוֹ\"ז, יָבוּזוּ לוֹ וַדַּאי, דְּהָא כֻּלְּהוּ אִתְחֲשִׁיבוּ לְגַבָּן, חֶרֶשׂ נִשְׁבָּר, דְּלֵית לֵיהּ תְקָנָה לְעָלְמִין.</p>\n<p>מַיִם דִּלְהוֹן אִתְפְּלִיגוּ בְּיוֹמִין בּוֹ\"ז, אִשְׁתָּאֲרוּ שְׁאַר יוֹמִין, דְּאִינּוּן ג' ד' ה' (נוטריקון) חֲמִישִׁי רְבִיעִי שְׁלִישִׁי, וְסִימָן, (ישעיהו מ״ה:ט׳) חֶרֶ\"שׂ אֶת חַרְשֵׂי הָאֲדָמָה, וְלֵית לוֹן תִּקּוּנָא בַּהֲדָן, וְלָא לְעָלְמִין. וְאִי תֵּימָא בּוֹז יָבוּזוּ לוֹ כְּתִיב. הָתָם (תהילים כ״ב:כ״ה) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת.</p>\n<p>יוֹמָא קַדְמָאָה מַאי עָבִיד לֵיהּ. אֶלָּא לָא אִקְרֵי רִאשׁוֹן, וְלָא אִקְרֵי אֶחָד, אֶלָּא חֲמִשָּׁה עָשָׂר סְתָם, בְּלָא רְשׁוּמָא כְּלַל. אֲבָל שֵׁירוּתָא דִּרְשִׁימוּ דְּמַיִין, מִיּוֹם שֵׁנִי הֲוִי. וְהָכִי אִתְחֲזֵי, בְּגִין דְּלֵית טוֹב בַּשֵּׁנִי, וּבְגִין כָּךְ, לָא רְשִׁים רִאשׁוֹן וְלָא אֶחָד כְּלַל, וַהֲוִי בִּסְתָם, וְשָׁרֵי רְשִׁימוּ דְּיוֹמִין, בְּיוֹם שֵׁנִי. וְאִתְפְּלָגוּ מַיִם בְּבוּ\"ז, וְאִשְׁתָּאָרוּ בְּיוֹמִין חֶרֶ\"שׂ, כְּמָה דְּאִתְּמַר, וְכֹלָּא כַּדְּקָא יֵאוֹת.</p>\n<p>זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּיַדְעֵי <Nonei></i>לְאַעְלָאָה לְגוֹ מוֹחָא דֶּאֱגוֹזָא. וּבְגִין לְמֵיעָאל לְגוֹ מוֹחָא, מְתַבְּרִין קְלִיפִין אִלֵּין, וְעָאלִין. מַה כְּתִיב לְבָתַר כָּל הַאי. בַּיוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. לְבָתַר דְּתַבְרוּ כָּל הָנֵי קְלִיפִין, וְתַבְרוּ כַּמָה גְּזִּיזִין, וְכַמָּה נְחָשִׁים קַטְלוּ, וְכַמָּה עַקְרַבִּים דַּהֲווֹ לוֹן בְּאִינּוּן טוּרֵי דַּחֲשׁוֹכָא, עַד דְּאַשְׁכָּחוּ אֲתָר דִּישׁוּבָא, וְקַרְתָּא קַדִּישָׁא, מַקְפָּא שׁוּרִין סְחוֹר סְחוֹר, כְּדֵין עָאלוּ לְגַבָּהּ, לְמֶעְבַּד נַיְיחָא תַּמָּן, וּלְמֵחדֵי בָּהּ. וְהָא אוֹקִימְנָא מִלָּה.</p>\n<p>וְדָא אִיהוּ עֲצֶרֶת, כְּנִישׁוּ. אֲתָר דְּמִתְכְּנַשׁ כֹּלָּא לְגַבָּהּ. תִּהְיֶה לָכֶם, וְלָא לְאַחֲרָא, לְמֶחְדֵּי אַתּוּן בְּמָארֵיכוֹן, וְאִיהוּ בַּהֲדַיְיכוּ. וְעַל דָּא כְּתִיב, (תהילים ל״ב:י״א) שִׂמְחוּ בַּיְיָ וְגִילוּ צַדִּיקִים וְהַרְנִינוּ כָּל יִשְׁרֵי לֵב. אמר ר' שמעון כל מאן דחדי וכו' עד שלא עשו חסד עם העניים (נדפס בהקדמת בראשית דף י' ע\"ב)</p>"],[9520012638,"<p>(במדבר ל״א:י״ח) וְכָל הַטַּף בַּנָּשִׁים אֲשֶׁר לָא יָדְעוּ מִשְׁכַּב זָכָר. תַּמָּן תָּנֵינָן, אָמַר רִבִּי יְהוּדָה, אֵין הָעוֹלָם מִתְנַהֵג אֶלָּא בִּתְרֵי גַּוְונִין, דְּאָתוּ מִסְּטַר אִתְּתָא דְּאִשְׁתְּכָחַת חַכִּימַת לִבָּא. הֲדָא הוּא דִכְתִיב, (שמות ל״ה:כ״ה) וְכָל אִשָׁה חַכְמַת לֵב בְּיָדֶיהָ טָווּ וַיָּבִיאוּ מַטְוְה אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן. וּמַאי מַתְיָּין. אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן, גַּוְונִין דִּכְלִילָן בְּגוֹ גְּוָונֵי.</p>\n<p>הֲדָא הוּא דִּכְתִּיב, (משלי ל״א:י״ג-י״ד) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים וַתַּעַשׂ בְּחֵפֶץ כַּפֶיהָ. וּכְתִיב בְּיָדֶיהָ טָווּ, מַאי טָווּ. אָמַר רִבִּי יְהוּדָה, טָווּ בְּדִינָא, טָווּ בְּרַחֲמֵי. אָמַר רִבִּי יִצְחָק, אֲמַאי אִתְקַרְיָא אִשָּׁה. אָמַר לֵיהּ דִּכְלִילָא בְּדִינָא, וּכְלִילָא בְּרַחֲמֵי.</p>\n<p>תָּא חֲזֵי, דְּאָמַר רִבִּי אֶלְעָזָר, כָּל אִתְּתָא בְּדִינָא אִתְקַרְיָא, עַד דְּאַטְעֲמָא טַעֲמָא דְּרַחֲמֵי. דְּתַנְיָא, מִסִּטְרָא דְּבַּר נָשׁ, אָתֵי חִוָּורָא. וּמִסִּטְרָא דְּאִתְּתָא, אָתֵי סוּמָקָא. טַעֲמָא (ס\"א אתתא) דְּאִתְּתָא מֵחִוָּורָא, וְחִוָּורָא עָדִיף.</p>\n<p>וְתָּא חֲזֵי אֲמַאי אֲסִירָן נְשֵׁי שְׁאַר עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּיַדְעֵי מִשְׁכְּבֵי דְּכוּרָא. מִשּׁוּם דְּתָנֵינָן, אִית יְמִינָא, וְאִית שְׂמָאלָא. יִשְׂרָאֵל, וּשְׁאַר עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְגַּן עֵדֶן, וְגֵיהִנָם. עָלְמָא דָּא, וְעָלְמָא דְּאָתֵי. יִשְׂרָאֵל לָקָבְלֵי דְּרַחֲמֵי, וּשְׁאַר עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לָקֳבְלֵי דְּדִינָא. וּתְנָן, אִתְּתָא דְּאַטְעֲמָא טַעֲמָא דְּרַחֲמֵי, רַחֲמֵי נַצְחָא. אִתְּתָא דְּטַעֲמָא טַעֲמָא דְּדִינָא, דִּינָא בְּדִינָא אִתְדַּבְּקַת, וְעָלַיְיהוּ אִתְקְרֵי (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה.</p>\n<p>וְעַל דָּא תָּנֵינָן, הַנִּבְעֶלֶת לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת קְשׁוּרָה בּוֹ כַּכֶּלֶב. מַה כַּלְבָּא תַּקִּיפָא בְּרוּחֵיהּ חֲצִיפָא. אוּף הָכָא דִּינָא בְּדִינָא, חֲצִיפָא בְּכֹלָּא. הַנִּבְעֶלֶת לְיִשְׂרָאֵל, תָּנֵינָן, כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְכֶם הַיּוֹם. מַאי טַעְמָא. מִשּׁוּם דְּנִשְׁמְתָא דְּיִשְׂרָאֵל, אַתְיָיא מֵרוּחָא דֶּאֱלֹהִים חַיִּים. דִּכְתִיב (ישעיהו נ״ז:ט״ז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף, מַשְׁמַע דִּכְתִיב מִלְּפָנַי. וּבְגִין כָּךְ, אִתְתָא דְּהִיא בְּתוּלְתָא, וְלָא אִתְדְּבָקַת בְּדִינָא קַשְׁיָא דִּשְׁאַר עַמִּין, וְאִתְדְּבָקַת בְּיִשְׂרָאֵל, רַחֲמֵי נַצְחָא וְאִתְכְּשָׁרַת.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. מַאי חֶסֶד. הוּא חַד מִכִּתְרֵי עִלָּאֵי דְּמַלְכָּא, דְּנִשְׁמְתָא דְּיִשְׂרָאֵל קָרָא לָהּ קוּדְשָׁא בְּרִיךְ הוּא חֶסֶד. עַל תְּנַאי דְּיִתְבְּנֵי, וְלָא יִשְׁתֵּיצֵי חֶסֶד מֵעָלְמָא. מַשְׁמַע דִּכְתִיב יִבָּנֶה. בְּגִין כָּךְ תָּנֵינָן, מַאן דְּשֵׁצֵי חֶסֶד מֵעָלְמָא, אִשְׁתֵּיצֵי הוּא לְעָלְמָא דְּאָתֵי. וְעַל דָּא כְּתִיב, (דברים כ״ה:ה׳) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה, בְּגִין לְמֶעְבַּד חֶסֶד עִם מִיתָא. וְאִתְעָבִיד בִּנְיָינָא, דִּכְתִּיב, (תהילים פ״ט:ג׳) עוֹלָם חֶסֶד יִבָּנֶה.</p>"],[9520012639,"<p><Nonei></i> (דברים ג׳:כ״ג-כ״ד) וָאֶתְחַנַּן אֶל יְיָ' בָּעֵת הַהִיא לֵאמֹר. אֲדֹנָ\"י ידִֹוִ\"ד אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ וְגוֹ'. רִבִּי (בראשית י\"א) יוֹסֵי פָּתַח, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל יְיָ'. תָּא חֲזֵי, כַּמָּה הוּא חֵילָא תַּקִּיפָא דְּאוֹרַיְיתָא, וְכַמָּה הוּא עִלָּאָה עַל כֹּלָּא. דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, לָא דָּחִיל מֵעִלָּאֵי וְתַתָּאֵי. וְלָא דָּחִיל מֵעִרְעוּרִין בִּישִׁין דְּעָלְמָא. בְּגִין דְּאִיהוּ אָחִיד בְּאִילָנָא דְּחַיֵּי, וְאָכִיל מִנֵּיהּ בְּכָל יוֹמָא.</p>\n<p>דְּהָא אוֹרַיְיתָא אוֹלִיף לֵיהּ לְבַּר נָשׁ, לְמֵיהַךְ בְּאֹרַח קְשׁוֹט. אוֹלִיף לֵיהּ עֵיטָא הֵיךְ יְתוּב קַמֵּי מָארֵיהּ (לבטלה לההיא גזרה). וַאֲפִילּוּ יִתְגְּזָר עָלֵיהּ מוֹתָא, כֹּלָּא יִתְבָּטַּל וְיִסְתְּלַּק מִנֵּיהּ, וְלָא שַׁרְיָא עֲלוֹי. (עיטא דבר נש בהאי עלמא) וְעַל דָּא בָּעֵי לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, וְלָא יִתְעֲדֵי מִנַהּ, הֲדָא הוּא דִכְתִיב, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְאִי אַעְדֵי מִינֵּיהּ אוֹרַיְיתָא, אוֹ אִתְפְּרַשׁ מִנַּהּ, כְּאִלּוּ אִתְפְּרַשׁ מִן חַיֵּי.</p>\n<p>תָּא חֲזֵי, עֵיטָא דְּבַּר נָשׁ כַּד אִיהוּ סָלִיק בְּלֵילְיָא עַל עַרְסֵיהּ, בָּעֵי לְקַבְּלָא עָלֵיהּ עוֹל מַלְכוּתָא דִּלְעֵילָּא, בְּלִבָּא שְׁלִים. וּלְאַקְדְמֵי לְמִימְסַר גַּבֵּיהּ פִּקְדּוֹנָא דְּנַפְשֵׁיהּ. וְהָא אוּקְמוּהָ, בְּגִין דְּכָל עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא, דְּהָא אִילָנָא דְּמוֹתָא שַׁרְיָא בְּעָלְמָא, וְכָל רוּחֵי דִּבְנֵי נָשָׁא נָפְקִין, וְסַלְּקִין וְאִתְטַמְּרָן (ס\"א ואתמסרו) גַּבֵּיהּ. וּבְגִין דְּאִינּוּן בְּפִקְדּוֹנָא, כֻּלְּהוּ תַּיְיבִין לְאַתְרַיְיהוּ.</p>"],[9520012640,"<p>תָּא חֲזֵי, כַּד אִתְּעַר רוּחַ צָפוֹן בְּפַלְגּוּת לֵילְיָא, וְכָרוֹזָא נָפִיק. וְקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, כְּדֵין מִתְכָּוְונֵי (נ\"א מתערי) כָּל בְּנֵי מַטְרוֹנִיתָא, וְכָל בְּנֵי הֵיכָלָא, לְשַׁבְּחָא לֵיהּ לְמַלְכָּא קַדִּישָׁא. וּכְדֵין כָּל אִינּוּן פִּקְדּוֹנִין דְּרוּחִין דְּאִתְמַסְּרָן בִּידָהּ, כֻּלְּהוּ אָתִיב לְמָארֵיהוֹן. וְרוּבָּא דִּבְנֵי עָלְמָא מִתְעָרִין בְּהַהִיא שַׁעֲתָא, וְהָא פִּקְדוֹנֵיהּ דְּכֻלְּהוּ אָתִיב לְגַבַּיְיהוּ.</p>\n<p>אִינּוּן דִּבְנֵי הֵיכָלָא עִלָּאָה קַיְימֵי בְּקִיּוּמַיְיהוּ, מִתְעֲרֵי מִשְׁתַּדְּלֵי בְּתוּשְׁבַּחְתָּא דְּאוֹרַיְיתָא, וּמִשְׁתַּתְּפֵי בִּכְנֶסֶת יִשְׂרָאֵל, עַד דְּנָהִיר יְמָמָא. כַּד אָתֵי צַפְרָא, הִיא, וְכָל בְּנֵי הֵיכָלָא (דמלכא) כֻּלְּהוּ אַתְיָין לְגַבֵּי מַלְכָּא קַדִּישָׁא, וְאִינּוּן אִקְרוּן בְּנִין דְּמַלְכָּא וּמַטְרוֹנִיתָא. וְהָא אוּקְמוּהָ.</p>\n<p>כַּד אָתֵי צַפְרָא, בָּעֵי לְנַקָּאָה גַּרְמֵיהּ בְּכֹלָּא, וּלְמֵיזַן זַיְינֵיהּ, לְאִשְׁתַּדְּלָא עִם מַלְכָּא קַדִּישָׁא, דְּהָא בְּלֵילְיָא אִשְׁתְּדַּל בְּמַטְרוֹנִיתָא. הַשְׁתָּא אַתְיָא עִם מַטְרוֹנִיתָא, לְזַוְּוגָא לָהּ עִם מַלְכָּא.</p>\n<p>אָתֵי לְבֵי כְּנִישְׁתָּא, מַדְכֵּי גַּרְמֵיהּ בְּקָרְבְּנִין, מְשַׁבַּח בְּתוּשְׁבַּחְתַּיְיהוּ דְּדָוִד מַלְכָּא. אָחִיד תְּפִילִין בְּרֵישֵׁיהּ, (ס\"א בידיה וברישיה) וְצִיצִית בְּגַדְפֵיהּ, אוֹמֵר תְּהִלָּה לְדָוִד. וְהָא אוּקְמוּהָ, צַלֵּי צְלוֹתָא קַמֵּי מָארֵיהּ, בִּצְלוֹתָא בָּעֵי לְמֵיקָם, כְּגַוְונָא (ס\"א בזווגא) דְּמַלְאֲכֵי עִלָּאֵי, לְאִתְחַבְּרָא בַּהֲדַיְיהוּ, דְּאִינּוּן אִקְרוּן הָעוֹמְדִים, כְּמָה דְאַתְּ אָמֵר, (זכריה ג׳:ז׳) וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים. וּלְכַוְּונָא רְעוּתֵיהּ קַמֵּי מָארֵיהּ, וְיִתְבַּע בָּעוּתֵיהּ.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּבַּר נָשׁ קָאִים בְּפַלְגּוּת לֵילְיָא מֵעַרְסֵיהּ, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כָּרוֹזָא קָארֵי עָלֵיהּ וְאָמַר, (תהילים קל״ד:א׳) הִנֵּה בָּרְכוּ אֶת יְיָ' כָּל עַבְדֵי יְיָ' הָעוֹמְדִים בְּבֵית יְיָ' בַּלֵּילוֹת. הַשְׁתָּא כַּד אִיהוּ קָאִים בִּצְלוֹתָא קַמֵּי מָארֵיהּ, הַהוּא כָּרוֹזָא קָּארֵי עָלֵיהּ וְאָמַר, וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶּה.</p>\n<p>בָּתַר דִּמְסַיֵּים צְלוֹתָא בִּרְעוּ (וקאים בעיטא) קַמֵּי מָארֵיהּ, הָא אוּקְמוּהָ, דְּבָעֵי לְמִימְסַר נַפְשֵׁיהּ בִּרְעוּתָא דְּלִבָּא, לְהַהוּא אֲתָר דְּאִצְטְרִיךְ. וְכַמָּה עֵיטִין אִית לֵיהּ לְבַר נָשׁ בְּכֹלָּא. <Nonei></i> וּבְשַׁעֲתָא דִּצְלוֹתָא קַיְּימָא (ס\"א סיימא), כָּל אִינּוּן מִלִּין דְּאַפִּיק בַּר נָשׁ מִפּוּמֵיהּ בְּהַהִיא צְלוֹתָא, כֻּלְּהוּ סַלְּקִין לְעֵילָּא, וּבָקְעִין אֲוִירִין וּרְקִיעִין, עַד דְּמָטוּ לְהַהוּא אֲתָר דְּמָטוּ וּמִתְעַטְּרוּ בְּרֵישָׁא דְּמַלְכָּא, וְעָבִיד מִנַּיְיהוּ עֲטָרָה. וְהָא אוֹקְמוּהָ חַבְרַיָּיא, צְלוֹתָא דְּבָעֵי בַּר נָשׁ לְקוּדְשָׁא בְּרִיךְ הוּא, לְכַוְּונָא דִּיהֵא צְלוֹתָא תַּחֲנוּנִים. מְנָלָן. מִמֹּשֶׁה, דִּכְתִּיב וָאֶתְחַנַּן אֶל יְיָ'. דָּא אִיהוּ צְלוֹתָא מֵעַלְיָא.</p>"],[9520012641,"<p>תָּא חֲזֵי, מַאן דְּקָאִים בִּצְלוֹתָא, בָּעֵי לְכַוְּונָא רַגְלוֹי, וְאוֹקְמוּהָ. וּבָעֵי לְחַפְּיָא רֵישֵׁיהּ, כְּמַאן דְּקָאִים קַמֵּי מַלְכָּא. וּבָעֵי לְמִכְסְיָיה (למכסייא) (ס\"א לאסתמא) עֵינוֹי, בְּגִין דְּלָא יִסְתָּכַּל בִּשְׁכִינְתָּא. וּבְסִפְרָא דְּרַב הַמְנוּנָא סָבָא אָמַר, מַאן דְּפָקַח עֵינוֹי בְּשַׁעֲתָא דִּצְלוֹתָא, אוֹ דְּלָא מָאִיךְ עֵינוֹי בְּאַרְעָא, אַקְדִּים עָלֵיהּ מַלְאַךְ הַמָּוֶת, וְכַד תִּיפּוּק נַפְשֵׁיהּ, לָא יִסְתָּכַּל בִּנְהִירוּ דִּשְׁכִינְתָּא, וְלָא יָמוּת בִּנְשִׁיקָה. מַאן דִּמְזַלְזֵל בִּשְׁכִינְתָּא מִתְּזַלְזֵּל הוּא בְּהַהוּא שַׁעֲתָא דְּאִצְטְרִיךְ בֵּיהּ, הֲדָא הוּא דִכְתִיב, (שמואל א ב׳:ל׳) כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ.</p>\n<p>הַאי מַאן דְּאִסְתָּכַּל בִּשְׁכִינְתָּא, בְּשַׁעֲתָא דְּאִיהוּ מְצַלֵּי. וְהֵיךְ יָכִיל לְאִסְתַּכְּלָא בִּשְׁכִינְתָּא. אֶלָּא לִינְדַע דְּוַדַּאי שְׁכִינְתָּא קַיְּימָא קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר, דְּתַמָּן שָׁארֵי שְׁכִינְתָּא. בְּגִין כָּךְ לָא בַּעְיָא לְמֶהֱוֵי חוֹצֵץ בֵּינוֹ וּבֵין הַקִּיר, וְאוֹקְמוּהָ.</p>\n<p>מַאן דְּקָאִים בִּצְלוֹתָא, בָּעֵי לְסַדְּרָא שְׁבָחָא דְּמָארֵיהּ בְּקַדְמִיתָא, וּלְבָתַר יִתְבַּע בָּעוּתֵיהּ. דְּהָא מֹשֶׁה הָכִי אָמַר בְּקַדְמִיתָא, אַתָּה הַחִלּוֹתָ וְגוֹ'. וּלְבַסּוֹף אֶעְבְּרָה וְגוֹ'. רִבִּי יְהוּדָה אָמַר, מַאי שְׁנָא הָכָא דִּכְתִּיב אֲדֹנָ\"י בְּקַדְמִיתָא, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד, וּלְבַסּוֹף ידו\"ד, וְקָרֵינָן אֱלֹהִי\"ם. אֶלָּא סִדּוּרָא הָכִי הוּא מִתַּתָּא לְעֵילָּא, וּלְאַכְלְלָא מִדַּת יוֹם בַּלַּיְלָה, וּמִדַּת לַיְלָה בַּיוֹם וּלְזַוְּוגָא כֹּלָּא כַּחֲדָא כַּדְּקָא יָאוּת.</p>"],[9520012642,"<p>(דברים ג׳:כ״ד) אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְּךָ. מַאי שֵׁירוּתָא הָכָא. אֶלָּא וַדַּאי מֹשֶׁה שֵׁירוּתָא הֲוָה בְּעָלְמָא, לְמֶהֱוֵי שְׁלִים בְּכֹלָּא. וְאִי תֵּימָא יַעֲקֹב שְׁלִים הֲוָה, וְאִילָנָא אִשְׁתְּלִים לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. הָכִי הוּא וַדַּאי, אֲבָל מַה דְּהֲוָה לְמֹשֶׁה, לָא הֲוָה לְבַּר נָשׁ אַחֲרָא, דְּהָא אִתְעֲטָּר בִּשְׁלִימוּ יַתִּיר, בְּכַמָּה אֶלֶף וְרִבְּבָן מִיִּשְׂרָאֵל, בְּאוֹרַיְיתָא, בְּמַשְׁכְּנָא, בְּכֹהַנִין, בְּלֵיוָאֵי, בִּתְרֵיסַר שְׁבָטִין, רַבְרְבִין מְמָנָן עָלַיְיהוּ, בְּשִׁבְעִין סַנְהֶדְרִין. הוּא אִשְׁתְּלִים בְּגוּפָא שְׁלִים. אַהֲרֹן לִימִינָא, נַחְשׁוֹן לִשְׂמָאלָא, הוּא בֵּינַיְיהוּ.</p>\n<p>בְּגִין כַּךְ אֶת גָּדְלְךָ, מִימִינָא, דָּא אַהֲרֹן. וְאֶת יָדְךָ הַחֲזָקָה, מִשְּׂמָאלָא, דָּא נַחְשׁוֹן. וְהָא אִתְּמַר. בְּגִין כָּךְ מֹשֶׁה שֵׁירוּתָא בְּעָלְמָא הֲוָה. וְאִי תֵּימָא מַאן הֲוָה סִיּוּמָא (דהא משה שירותא הוה). סִיּוּמָא מַלְכָּא מְשִׁיחָא הוּא, דְּהָא כְּדֵין יִשְׁתְּכַּח שְׁלִימוּ בְּעָלְמָא, מַה דְּלָא הֲוָה כֵּן לְדָרֵי דָּרִין. בְּהַהוּא זִמְנָא יִשְׁתְּכַּח שְׁלִימוּ לְעֵילָּא וְתַתָּא, וְיֵהוֹן עָלְמִין כֻּלְּהוּ בְּזִוּוּגָא חַד, כְּדֵין כְּתִיב (זכריה י״ד:ט׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>(דברים ד') וַיֹּאמֶר יְיָ' אֵלַי רַב לָךְ אַל תּוֹסֶף וְגוֹ'. אָמַר רִבִּי חִיָּיא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, מֹשֶׁה, רַב לָךְ דְּאִזְדַּוְּוגַת בִּשְׁכִינְתָּא, מִכָּאן וּלְהָלְאָה אַל תּוֹסֶף, רִבִּי יִצְחָק אָמַר, רַב לָךְ בִּנְהִירוּ דְּשִׁמְשָׁא דְּהֲוָה גַּבָּךְ, אַל תּוֹסֶף, דְּהָא זִמְנָא דְּסִיהֲרָא מָטָא, וְסִיהֲרָא לָא יָכִיל לְאַנְהָרָא, עַד דְּיִתְכְּנִישׁ שִׁמְשָׁא. אֲבָל וְצַו אֶת יְהוֹשֻׁעַ וְחַזְּקֵהוּ וְאַמְּצֵהוּ. אַנְתְּ דְּהוּא שִׁמְשָׁא, בָּעֵי לְאַנְהָרָא לְסִיהֲרָא, וְהָא אִתְּמַר.</p>\n<p>(דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם וְגוֹ'. רִבִּי יוֹסֵי אָמַר (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ וְגוֹ'. זַכָּאָה עַמָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּחַר בְּהוּ מִכָּל עַמִּין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְסָלִיק לוֹן לְעַדְבֵיהּ, וּבָרִיךְ לוֹן בְּבִרְכָתָא דִּילֵיהּ בְּבִרְכָתָא דִּשְׁמֵיהּ, הֲדָא הוּא דִּכְתִּיב, (ישעיהו ס״א:ט׳) כִּי הֵם זֶרַע בֵּרַךְ יְיָ', בֵּרַךְ יְיָ' מַמָּשׁ.</p>\n<p>תָּא חֲזֵי, כָּל שְׁאַר עַמִּין דְּעָלְמָא, יָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְרַבְרְבֵי מְמָנָן, דְּשַׁלְטִין עָלַיְיהוּ. וְיִשְׂרָאֵל אָחִיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְעַדְבֵיהּ, לְחוּלָקֵיהּ, לְאִתְאַחֲדָא בֵּיהּ מַמָּשׁ. וְיָהִיב לוֹן אוֹרַיְיתָא קַדִּישָׁא, בְּגִין לְאִתְאַחֲדָא בִּשְׁמֵיהּ, <Nonei></i> וְעַל דָּא וְאַתֶּם הַדְּבֵקִים בַּיְיָ', וְלָא בִּמְמָנָא אַחֲרָא כִּשְׁאַר עַמִּין, וְהָא אוֹקְמוּהָ בְּכַמָּה אֲתָר.</p>"],[9520012643,"<p>(דברים ד׳:י״ב) וַיְדַבֵּר יְיָ' אֲלֵיכֶם מִתּוֹךְ הָאֵשׁ קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וְגוֹ'. אָמַר רִבִּי אֶלְעָזָר, הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, קוֹל דְּבָרִים, מַאי קוֹל דְּבָרִים. אֶלָּא קוֹל דְּאִקְרֵי דִּבּוּר, דְּכָל דִּבּוּרָא בֵּיהּ תַּלְיָא. וְעַל דָּא כְּתִיב, וַיְדַבֵּר ה' אֲלֵיכֶם, דְּהָא דִּבּוּר בַּאֲתָר דָּא תַּלְיָא, לְהַאי אִקְרֵי קוֹל דְּבָרִים.</p>\n<p>אַתֶּם שׁוֹמְעִים, דִּשְׁמִיעָה לָא תַּלְיָא אֶלָּא בְּהַאי. בְּגִין דִּשְׁמִיעָה בְּדִבּוּר תַּלְיָא. וּבְּגִין כָּךְ אַתֶּם שׁוֹמְעִים. (ס\"א אתם שומעים, ושמיעה בדבור תליא) וְהָא אוֹקְמוּהָ, (שמות כ״א:ו׳) וְרָצַע אֲדוֹנָיו אֶת אָזְנוֹ בַּמַּרְצֵעַ, בְּגִין דְּפָגִים אַתְרָא דְּאִקְרֵי שְׁמִיעָה, וְהוּא דִּבּוּר וְהוּא שְׁמִיעָה.</p>\n<p>קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים וּתְמוּנָה אֵינְכֶם רוֹאִים. מַאי וּתְמוּנָה. כְּמָה דְאַתְּ אָמֵר (במדבר יב) וּתְמוּנַת יְיָ' יַבִּיט. דָּבָר אַחֵר וּתְמוּנָה, דָּא קוֹל פְּנִימָאָה, דְּלָא הֲוָה מִתְחֲזֵי כְּלַל. זוּלָתִי קוֹל, דָּא קוֹל אַחֲרָא דְּקָאַמְרָן. וּתְמוּנָה, אֲמַאי אִקְרֵי הָכִי. בְּגִין דְּכָל תִּקּוּנָא דְּגוּפָא מִינֵּיהּ נָפְקָא.</p>\n<p>וְאִי תֵּימָא אַחֲרָא אִקְרֵי הָכִי נָמֵי. אִין. דְּהַאי אַחֲרָא תִּקּוּנָא דִּלְתַתָּא מִינֵּיהּ נָפְקָא, וּבְּגִין כָּךְ, ה' עִלָּאָה ה' תַּתָּאָה, ה' עִלָּאָה, קוֹל גָּדוֹל וְלָא יָסָף, דְּלָא פַּסְקֵי מַבּוּעֵי לְעָלְמִין, וְכָל אִינּוּן קוֹלוֹת תַּמָּן אִשְׁתְּכָחוּ כַּד אִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל. וְכֹלָּא נָפְקָא מֵהַהוּא קוֹל פְּנִימָאָה דְּכֹלָּא, בְּגִין דְּבֵיהּ תַּלְיָא מִלְּתָא.</p>\n<p>הַאי דְּאִקְרֵי מִשְׁנֵה תּוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אַמָרָן. וְהָא אוֹקִימְנָא מִלָּה. אֲמַאי הָכִי. אֶלָּא חָכְמָה עִלָּאָה, כְּלָלָא דְּאוֹרַיְיתָא אִתְקְרֵי, וּמִנָהּ נָפְקָא כֹּלָּא, בְּהַהוּא קוֹל פְּנִימָאָה. לְבָתַר מִתְיַשְּׁבָא כֹּלָּא וְאִתְאֲחָד, בַּאֲתָר דְּאִקְרֵי עֵץ הַחַיִּים, וּבֵיהּ תַּלְיָא כְּלַל וּפְרָט, תּוֹרָה שֶׁבִּכְתָּב ושֶׁבְּעַל פֶּה, וְהוּא אִקְרֵי תּוֹרָה וּמִשְׁנֵה תּוֹרָה. בְּקַדְמִיתָא גְּבוּרָה דְּלָא פָּסִק, וְהַשְׁתָּא כֹּלָּא כַּחֲדָא. בְּגִין כָּךְ הָכָא בְּאִלֵּין י' הַדִּבְּרוֹת, כֹּלָּא רָשִׁים בְּוָא\"ו, וְלֹא תִּנְאָף, וְלֹא תִּגְנוֹב, וְלֹא תַעֲנֶה, וְלֹא תַחְמוֹד, וְלֹא תִתְאַוֶּה, וְהָא אוֹקְמוּהָ.</p>\n<p>אָמַר רִבִּי יוֹסֵי, מַאי וְלֹא תִתְאַוֶּה, כֵּיוָן דִּכְתִּיב וְלֹא תַחְמוֹד, דְּהָא בְּהַאי סַגֵּי. אָמַר לֵיהּ, זַכָּאִין אִינּוּן מָארֵי קְשׁוֹט. חֲמִידָה חַד דַּרְגָּא. תַּאֲוָה דַּרְגָּא אַחֲרָא. חֲמִידָה, דְּאִי יָכִיל, אָזִיל לְמֵיסַב דִּילֵיהּ בְּגִין הַהִיא חֲמִידָה דְּנָקַט, אָזִיל לְמֶעְבַּד עוֹבָדָא. תַּאֲוָה, לָאו הָכִי. דְּהָא אֲפִילּוּ דְּלָא יִנְקוּט אוֹרְחָא לְמֵהַךְ אֲבַּתְרֵיהּ, וְהָא אוֹקְמוּהָ חַבְרַיָּיא.</p>\n<p>אָמַר לֵיהּ רִבִּי יוֹסֵי, אֲמַאי לָא כְּתִיב וְלֹא תִרְצַח, כְּהָנֵי אַחֲרִינֵי. אָמַר לֵיהּ בְּגִין דְּדַרְגָּא דְּדִינָא בִּגְבוּרָה תַּלְיָא, וְלָא בַּאֲתָר דְּרַחֲמֵי, בְּגִין כָּךְ לֹא תִרְצַח לָא כְּתִיב בֵּיהּ וָא\"ו. וּבְגִין דְּבַעְיָין ה' וָוִין אִתּוֹסָף וָא\"ו וְלֹא תִתְאַוֶּה, דְּהָא בְּלֹא תִרְצַח לָא בָּעֵי לְמִשְׁרֵי וָא\"ו, וְאִתּוֹסַף הָכָא.</p>\n<p>שָׁמַע רִבִּי פִּנְחָס דְּיָתִיב אֲבַּתְרֵיהּ, וּנְשָׁקֵיהּ. בָּכָה וְחָיִיךְ. אָמַר גּוּר אַרְיֵה, לֵית מַאן דְּקָאִים קַמַּיְיהוּ, מַאן יָכִיל לְקַיְּימָא קַמֵּיהּ וַאֲבוּהָּ בְּעָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, וְזַכָּאָה חוּלָקִי בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, דְּזָכֵינָא לְהַאי. עַל דָּא כְּתִיב, (איוב כ״ב:י״ט) יִרְאוּ צַדִּיקִים וְיִשְׂמָחוּ.</p>\n<p>רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (דברים ה׳:כ״ד) קְרַב אַתָּה וּשֲׁמָע וְגוֹ'. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל, (כלהו) כֻּלְּהוֹן קוֹלוֹת אִשְׁתְּכָחוּ. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כּוּרְסְיָּיא, וְדָא מִגּוֹ דְּדָא אִתְחֲזֵי, וּמִלּוּלָא דְּדָא נָפִיק מִגּוֹ עִלָּאָה דְּעָלֵיהּ, וְדָא הוּא רָזָא דִּכְתִּיב, (דברים ה׳:ד׳) פָּנִים בְּפָנִים דִּבֶּר יְיָ' עִמָּכֶם בָּהָר מִתּוֹךְ הָאֵשׁ, דְּמִלּוּלָא נָפְקָא, וּמַלִּיל מִגּוֹ אֶשָּׁא וְשַׁלְהוֹבָא, דְּדָחֵי לֵיהּ לְבַר, בִּדְפִיקוּ דְּרוּחָא וּמַיָּיא, דְּיָהֲבִין חֵילָא. דְּאֶשָּׁא וְרוּחָא וּמַיָּיא, מִגּוֹ שׁוֹפָר, דְּאִיהוּ כָּלִיל לְכֻלְּהוּ נָפִיק. וְיִשְׂרָאֵל אִתְרַחִיקוּ מִדְּחִילוּ דָּא.</p>\n<p>וּבְּגִין כָּךְ, וְאַתְּ תְּדַבֵּר אֵלֵינוּ, לָא בָּעֵינָן בְּתּוּקְפָא עִלָּאָה דִּלְעֵילָּא, אֶלָּא מֵאֲתָר דְּנוּקְבָּא וְלָא יַתִּיר, וְאַתְּ תְּדַבֵּר אֵלֵינוּ וְגוֹ'. אָמַר מֹשֶׁה וַדַּאי חָלַשְׁתּוּן חֵילָא דִּילִי, חָלַשְׁתּוּן חֵילָא אַחֲרָא, דְּאִלְמָלֵא לָא אִתְרַחֲקוּ יִשְׂרָאֵל, וְיִשְׁמְעוּן כָּל <Nonei></i> הַהִיא מִלָּה כַּד בְּקַדְמִיתָא, לָא הֲוָה יָכִיל עָלְמָא לְמֶהֱוֵי חָרִיב לְבָתַר, וְאִינּוּן הֲווֹ קַיְימִין לְדָרֵי דָּרִין.</p>\n<p>דְּהָא בְּשַׁעֲתָא קַדְמִיתָא מִיתוּ. מַאי טַעְמָא. בְּגִין דְּהָכִי אִצְטְרִיךְ, דְּהָא אִילָנָא דְּמוֹתָא גָּרִים. לְבָתַר דְּחַייוּ (דחיו) וְקָמוּ וְקָא סָגּוּ, וּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲלָא לוֹן לְאִילָנָא דְּחַיֵּי, דְּקָאִים עַל הַהוּא אִילָנָא דְּמוֹתָא, בְּגִין לְמֶהֱוֵי קַיְימִין לְעָלְמִין, אִתְרְחַק וְלָא בָּעוּן, כְּדֵין אִתְחֲלָשׁ חֵילָא דְּמֹשֶׁה עָלַיְיהוּ, וְאִתְחַלָּשׁ חֵילָא אַחֲרָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא בָּעֵינָא לְקַיְּימָא לְכוּ בַּאֲתָר עִלָּאָה, וּלְאִתְדַּבְּקָא בַּחַיִּים, אַתּוּן בָּעִיתוּן אֲתָר דְּנוּקְבָּא שַׁרְיָא. וּבְּגִין כָּךְ, לֵךְ אֱמוֹר לָהֶם וְגוֹ'. כָּל חַד יְהַךְ לְנוּקְבֵיהּ, וְיִתְיַחֵד בָּהּ.</p>\n<p>וְעִם כָּל דָּא, כֵּיוָן דְּיִשְׂרָאֵל לָא עָבְדוּ, אֶלָּא בִּדְחִילוּ עִלָּאָה דְּהֲוָה עָלַיְיהוּ, לָא אִתְּמַר עָלַיְיהוּ, אֶלָּא מִי יִתֵּן וְהָיָה לְבָבָם זֶה לָהֶם וְגוֹ'. מִכָּאן אוֹלִיפְנָא, כָּל מַאן דְּעָבִיד מִלָּה, וְלִבָּא וּרְעוּתֵיהּ לָא שַׁוֵּי לְסִטְרָא בִּישָׁא, אַף עַל גַּב דְּאִיהוּ בִּישׁ, הוֹאִיל וְלָא עָבִיד בִּרְעוּתָא, עוֹנְשָׁא לָא שַׁרְיָא עָלֵיהּ. וְלָא כְּבַּר נָשׁ אַחֲרָא. וְקוּדְשָׁא בְּרִיךְ הוּא לָא דָּאִין לֵיהּ לְבִישׁ.</p>"],[9520012644,"<p>(דברים ה׳:כ״ח) וְאַתָּה פֹּה עֲמוֹד עִמָּדִי. מֵהָכָא, אִתְפְּרַשׁ מִכֹּל וָכֹל, מְאִתְּתֵיהּ, וְאִתְדַּבָּק וְאִסְתַּלָּק בַּאֲתָר אַחֲרָא דִּדְכוּרָא, וְלָא בְּנוּקְבָּא. זַכָּאָה חוּלָקָא דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא, דְּזָכָה לְדַרְגִּין עִלָּאִין, מַה דְּלָא זָכָה בַּר נָשׁ אָחֳרָא לְעָלְמִין. עַל דָּא כְּתִיב, (קהלת ז׳:כ״ו) טוֹב לִפְנֵי הָאֱלֹהִים יִמָּלֵט מִמֶּנָּה. מַאי טוֹב. דָּא מֹשֶׁה. דִּכְתִּיב, (שמות ב) כִּי טוֹב הוּא. וּבְגִין דְּהֲוָה טָב, סָלִיק לְדַרְגָּא אַחֲרָא עִלָּאָה. וְעַל דָּא כְּתִיב, (שמות ג׳:ה׳) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא, עוֹמֵד עָלָיו דַּיְיקָא. מַאי טַעְמָא. בְּגִין כִּי טוֹב הוּא, וְטוֹב הוּא דְּכוּרָא.</p>\n<p>וְאִי תֵּימָא, דְּהָא אָמַר רִבִּי יְהוּדָה, הָא דָּוִד דִּכְתִּיב בֵּיהּ טוֹב, כְּמָה דְאַתְּ אָמֵר (שמואל א ט״ז:י״ב) וְטוֹב רֹאִי, אֲמַאי לָא הֲוָה יַתִּיר. אָמַר לֵיהּ וְטוֹב רֹאִי כְּתִיב. טוֹב רֹאִי, דָּא דְּאִיהוּ חֵיזוּ לְאִסְתַּכְּלָא, הָכִי הֲוָה דָּוִד. טוֹב רֹאִי, הֲוָה טוֹב דְּאִיהוּ חֵיזוּ. וּבְמֹשֶׁה כְּתִיב טוֹב הוּא מַמָּשׁ, וְהָכָא טוֹב רֹאִי. וְעִם כָּל דָּא, בְּתַרְוַויְיהוּ הֲוָה אָחִיד, דְּהָא דָּא בְּדָא אָחִיד. וּמֹשֶׁה לְבָתַר דְּהֲוָה טַב, סָלִיק לְמֶהֱוֵי גּוּפָא אִישׁ. (דברים כ\"ג) אִישׁ הָאֱלֹהִים, (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד.</p>\n<p>אָמַר רִבִּי יְהוּדָה, בְּכָל עוֹבָדוֹי, בָּעֵי בַּר נָשׁ לְשַׁוָּאָה לָקֳבְלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא אוֹקִימְנָא מִלָּה. רִבִּי יְהוּדָה לְטַעְמֵיהּ, דְּאָמַר רִבִּי יְהוּדָה, הַאי מַאן דְּאָזִיל בְּאָרְחָא, יְכַוֵּין לִתְלַת מִלִּין, וְעֵילָּא מִנְּהוֹן צְלוֹתָא, וְאַף עַל גַּב דִּצְלוֹתָא יַתִּיר עִלָּאָה מִכֹּלָּא, תְּרֵי חַבְרֵי אוֹ תְּלָתָא דְּלָעָאן בְּמִלֵי דְּאוֹרַיְיתָא. דְּהָא לָא מִסְתָּפֵי, בְּגִין דִּשְׁכִינְתָּא (ס\"א ועילא מנהון צלותא, ועלאה מכלהו, חברייא במלי דאורייתא. דהא שכינתא) אִשְׁתַּתְּפָא בַּהֲדַיְיהוּ.</p>"],[9520012645,"<p>(כי הא ד)רִבִּי אֶלְעָזָר וְרִבִּי חִיָּיא הֲווֹ אַזְלֵי בְּאָרְחָא, אָמַר רִבִּי אֶלְעָזָר (ס\"א חייא) כְּתִיב, (בראשית ג׳:כ״א) וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר. וְכִי עַד הַשְׁתָּא פְּשִׁיטֵי הֲווֹ מֵהַהוּא עוֹר. אִין. אֶלָּא מָאנֵי לְבוּשֵׁי יְקַר הֲווֹ. אָמַר לֵיהּ רִבִּי חִיָּיא, אִי הָכִי לָא אִתְחָזוּן לְהוּ אֲפִילּוּ כָּתְנוֹת עוֹר. וְכִי תֵּימָא דְּעַד לָא חָאבוּ אַלְבִּישׁוּ לְהוּ, לָא. אֶלָּא לְבָתַר דְּחָבוּ כְּתִיב, וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם וְגוֹ'.</p>\n<p>אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, בְּקַדְמִיתָא הֲווֹ כְּגַוְונָא דִּלְעֵילָּא, וּמִתְפָּשְׁטִן מִן גְּוָונֵי דִּלְתַּתָּא, וַהֲוָה נְהוֹרָא דִּלְעֵילָּא אַסְחַר עָלַיְיהוּ. וּלְבָתַר דְּחָבוּ, אַהְדָּר לוֹן בִּגְוָונֵי דְּהַאי עָלְמָא, וְאַעְבַּר מִנַּיְיהוּ גַּוְונֵי דִּלְעֵילָּא. מַה כְּתִיב. וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם מִגַּוְונָא דְּהַאי עָלְמָא. כְּתִיב (שמות כ״ט:ד׳) וְאֶת אַהֲרֹן וְאֶת בָּנָיו תַּקְרִיב וְהִלְבַּשְׁתָּם כָּתְנוֹת, הָתָם כְּגַוְונָא דִּלְעֵילָּא. הָכָא כְּגַוְונָא דִּלְתַּתָּא. הָתָם כָּתְנוֹת שֵׁשׁ, הָכָא כָּתְנוֹת עוֹר. וְאַף עַל גַּב דְּאִיהוּ הָכִי, שַׁפִּירָא דְּאִינּוּן לְבוּשִׁין סָלִיק עַל כֹּלָּא.</p>\n<p>(בראשית ג׳:ז׳) וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם (בטיפסא) (בעפושא) דְּהַאי עָלְמָא, מַה דְּלָא הֲוָה קוֹדֶם, דַּהֲווֹ מַשְׁגִּחִין וּפַקְחִין לְעֵילָּא. לְזִמְנָא דְּאָתֵי כְּתִיב, (ישעיהו מ״ב:ט״ז) וְהוֹלַכְתִּי עִוְרִים בְּדֶּרֶךְ לֹא יָדָעוּ וְגוֹ'. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַפְקְחָא עַיְינִין דְּלָא חַכִּימִין, וּלְאִסְתַּכְּלָא <Nonei></i> בְּחָכְמְתָא עִלָּאָה, וּלְאִתְדַּבְּקָא בְּמַאי דְּלָא אִתְדָּבָקוּ בְּהַאי עָלְמָא, בְּגִין דְּיִנְדְּעוּן לְמָארֵיהוֹן. זַכָּאִין אִינּוּן צַדִּיקַיָּא, דְּיִזְכּוּן לְהַהִיא חָכְמְתָא, דְּלָאו חָכְמְתָא כְּהַהִיא חָכְמְתָא, וְלָאו יְדִיעָה כְּהַהִיא יְדִיעָה, וְלָאו דְּבֵקוּתָא כְּהַהִיא דְּבֵקוּתָא.</p>\n<p>עַד דַּהֲווֹ אַזְלֵי, חֲזוּ אִינּוּן לִסְטִים אָזְלֵי בַּתְרַיְיהוּ, לְאַקְפְּחָא לוֹן. אִסְתָּכַּל בְּהוּ רִבִּי אֶלְעָזָר, אָתוּ תְּרֵין חֵיוָן בָּרָא וְקַטְלֵי לוֹן. אָמַר רִבִּי אֶלְעָזָר, בְּרִיךְ רַחֲמָנָא דְּשֵׁיזְבָן, קָרָא עָלַיְיהוּ, (משלי ד׳:י״ב) בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וּכְתִיב (תהילים צ״א:י״ד) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ'. וּכְתִיב (שם) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.</p>"],[9520012646,"<p>תָּאנָא בְּרָזָא עִלָּאָה בְּסִפְרָא דִּצְנִיעוּתָא, ג' חֲלָלִין דְּאַתְוָון רְשִׁימִין, אִתְגַּלְּיָין בָּהּ בְּגוּלְגַּלְתָּא דִּזְעֵיר אַנְפִּין. וְתָנֵינָן, ג' מוֹחֵי אִינּוּן, דִּסְתִּימוּ בְּאִינּוּן חַלָלִין. וּמִשֵּׁירוּתָא (וממשיכותא) דְּמוֹחָא עִלָּאָה סְתִימָאָה דְּעַתִּיקָא קַדִּישָׁא דְּאִתְמְשִׁיךְ בְּהַהוּא זְעֵיר אַנְפִּין, אִשְׁתְּכָחוּ ד' מוֹחֵי. וְאִלֵּין ד' מוֹחִין, (ס\"א דינא לית כתראי מכל כתרי מלכא) מִשְׁתַּכְּחִין וּמִתְפָּשְּׁטִין (ס\"א בכלא ואינון) בְּכָל גּוּפָא וְאִינּוּן ד' רִיהֲטֵי, דְּאַרְבַּע בָּתֵּי דִּתְפִילִין, דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וּבְּגִין כָּךְ בָּעֵי בַּר נָשׁ לַאֲנָחָא בְּכָל יוֹמָא, בְּגִין דְּאִינּוּן שְׁמָא קַדִּישָׁא עִלָּאָה בְּאַתְווֹי רְשִׁימָן, דִּכְתִּיב, (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ. וּתְנָן, שֵׁם יְיָ' מַמָּשׁ, וְאִלֵּין תְּפִלִּין דְּרֵישָׁא. (מוחא עלאה דאתמשך במוחא תתאה אקרון תרי מוחין ואינון דכתיב חכמות, ומתפרשן בחד)</p>\n<p>רִבִּי יִצְחָק אָמַר, הוּא דִּכְתִּיב, (שמות י״ג:ב׳) קַדֶּשׁ לִי כָל בְּכוֹר, דָּא הִיא כִּתְרָא דְּכָלִיל וְאַסְתִּים כָּל אִינּוּן אַחֲרָנִין. (כל בכור כל בכור סתם, לעלאה) מְשִׁיכוּתָא (ס\"א משרייתא) דִּלְעֵילָּא סְתִימָא בֵּיהּ. (דכלא) וְדָא אִקְרֵי פֶּטֶר כָּל רֶחֶם, פְּתִיחוּתָא דְּכָל מְשִׁיכוּתָא דְּרַחֲמֵי, וִיסוֹדָא (נ\"א ונהירו) דִּלְעֵילָּא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, וְסָתִים בְּיוֹ\"ד דִּשְׁמָא קַדִּישָׁא. וְדָא (ס\"א יו\"ד) חַד בֵּיתָא דִּתְפִלִּין, דְּהוּא קַדֶּשׁ לִי כָל בְּכוֹר סְתָם. מוֹחָא (נ\"א אבא) עִלָּאָה, חָכְמָה.</p>\n<p>בֵּיתָא תִּנְיָינָא, וְהָיָה כִּי יְבִיאֲךָ יְיָ' (אלהיך). אָמַר רִבִּי יְהוּדָה מוֹחָא דְּתַרְעוֹי נָפְקִין לְחַמְשִׁין תַּרְעִין. תַּרְעִין סַגִּיאִין, וְאִינּוּן לָקֳבֵל זִמְנִין סַגִּיאִין דִּכְתִּיב, (שמות כ׳:ב׳) אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם. (שמות י״ג:י״ח) הוֹצִיאֲךָ יְיָ' מִמִּצְרַיִם. וְאִדְכַּר זִמְנִין סַגִּיאִין דּוּכְרָנָא דְּמִצְרַיִם. וְאִינּוּן חַמְשִׁין לָקֳבֵל חַמְשִׁין.</p>\n<p>וְתָנֵינָן בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, דְּאָמַר תַּרְעִין סַגִּיאִין דִּלְעֵילָּא וְתַתָּא, תָּבַר קוּדְשָׁא בְּרִיךְ הוּא, דַּהֲווֹ סְתִימִין וּמִתְקַטְּרִין בְּשַׁלְשְׁלֵיהוֹן, בְּגִין לְאַפָּקָא לְהוּ לְיִשְׂרָאֵל (לבר). דְּהָא מֵאִלֵּין תַּרְעִין דְּהַהוּא מוֹחָא, מִתְפַּתְּחֵי וּמִשְׁתְּרוּ כָּל שְׁאַר תַּרְעִין. וְאִלְמָלֵא דְּאִתְעָרוּ וְאִתְפְּתָּחוּ אִינּוּן תַּרְעִין דְּהַאי מוֹחָא, לָא הֲווֹ מִתְפַּתְּחִין אִינּוּן אַחֲרָנִין לְמֶעְבַּד דִּינָא, וּלְאַפָּקָא לוֹן לְיִשְׂרָאֵל מִן עַבְדּוּתָא.</p>\n<p>וְכֹלָּא סָתִים בְּהַאי דְּאִקְרֵי אִימָא עִלָּאָה, דְּמִנָהּ אִתְּעַר חֵילָא לְאִימָא תַּתָּאָה. וּמַאי אִיהוּ. דִּכְתִּיב בָּהּ (ישעיהו נ״א:ד׳) וּלְאוּמִּי אֵלַי הַאֲזִינוּ. אַל תִּקְרֵי לְאוּמִּי, אֶלָּא לְאִמִּי. דְּלָא זָז קוּדְשָׁא בְּרִיךְ הוּא מֵחַבְּבָהּ לִכְנֶסֶת יִשְׂרָאֵל, עַד דִּקְרָאָהּ אִמִּי. וְהַאי נָפְקָא מֵאִימָא עִלָּאָה, דְּהִיא בֵּיתָא תִּנְיָינָא, דְּאִקְרֵי ה' דִּשְׁמָא קַדִּישָׁא, דְּאִתְפַּתְּחָא לְחַמְשִׁין תַּרְעִין. וּמֵהַאי נָפַק רוּחָא לְחַד נוּקְבָּא דְּפַרְדַּשְׁקָא דְּחוֹטָמָא.</p>\n<p>וְתָנֵינָן, יוֹבְלָא דְּנָפְקִין בֵּיהּ עַבְדִּין לְחֵירוּ, בְּהַאי מוֹחָא אִתְאֲחָד. וְאִינּוּן חַמְשִׁין שְׁנִין דְּיוֹבְלָא. וְאִינּוּן חַמְשִׁין יוֹמִין דְּחוּשְׁבָּנָא דְּעוֹמֶר, בֵּיהּ אִתְאֲחָדוּ. דִּבְהוּ נַיְיחִין רוּחֵי דְּעַבְדִּין, וּמַפְּקֵי רוּחֵיהוֹן (נ\"א ומפיק רוחיה) לְנַיְיחָא. כְּמָה דִּכְתִּיב, (ישעיהו י״ד:ג׳) בְּיוֹם הָנִיחַ יְיָ' לְךָ מֵעָצְבְּךָ וּמִרָגְזֶךָ וּמִן הָעֲבוֹדָה וְגוֹ'. וּבְגִין כַּךְ, ה' נַיְיחָא דְּרוּחָא, וּלְאַפָּקָא רוּחָא לְחֵירוּ. וְהַאי בֵּיתָא יְצִיאַת מִצְרַיִם בָּהּ תַּלְיָיא, וּבְאָת ה' דִּשְׁמָא קַדִּישָׁא, כְּמָה דְּאִתְּמַר. עֲד כָּאן כְּלָלָא דְּי\"ה דִּשְׁמָא קַדִּישָׁא.</p>\n<p>תָּא חֲזֵי, מִסִּטְרָא דְּאַבָּא נָפִיק חֶסֶד. מִסִּטְרָא דְּאִמָּא נָפִיק גְּבוּרָה. וְכֹלָּא אָחִיד קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְעַטָּר בְּהוּ, אָת וָא\"ו.</p>\n<p><Nonei></i> בֵּיתָא תְּלִיתָאָה שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. תָּאנָא רִבִּי שִׁמְעוֹן, דָּא הוּא רָזָא עִלָּאָה, דְּיִשְׂרָאֵל עִלָּאָה אִתְעֲטָּר בְּסִטְרָא דְּאַבָּא. וּמַאי אִיהוּ. אַבְרָהָם. וְאִתְעֲטָּר בְּסִטְרָא דְּאִימָּא. וּמַאי אִיהוּ. יִצְחָק.</p>\n<p>תָּנֵינָן, וְאָהַבְתָּ מַאן דְּרָחִים לֵיהּ לְמַלְכָּא, עָבִיד יַתִּיר טִיבוּ חֶסֶד עִם כֹּלָּא. וְחֶסֶד יַתִּירָא, הַהוּא דְּאִקְרֵי חֶסֶד דֶּאֱמֶת, דְּלָא בָּעֵי אֲגָר עָלֵיהּ, אֶלָּא בְּגִין רְחִימוּתָא דְּמַלְכָּא, דְּרָחִים לֵיהּ יַתִּיר, וּבִרְחִימוּתָא דְּמַלְכָּא תַּלְיָא חֶסֶד. וְעַל דָּא אִקְרֵי (ישעיהו מ״א:ח׳) אַבְרָהָם אוֹהֲבִי. וּבְגִין דְּרָחִים לֵיהּ יַתִּיר, אַסְגֵּי חֶסֶד בְּעָלְמָא. וְעַל דָּא, הָכָא וְאָהַבְתָּ. וּבִרְחִימוּתָא תַּלְיָא חֶסֶד, וְדָא הִיא בֵּיתָא תְּלִיתָאָה.</p>\n<p>בֵּיתָא רְבִיעָאָה, וְהָיָה אִם שָׁמוֹעַ. הִשָּׁמְרוּ לָכֶם. וְחָרָה אַף יְיָ'. גְּבוּרָה תַּקִּיפָא, וְדִינָא קַשְׁיָא הִיא, וְנַפְקַת מִסִּטְרָא דְּאִימָּא עִלָּאָה. וְתָנֵינָן, אַף עַל גַּב דְּלֵית הִיא דִּינָא, מִסִּטְרָהָא נָפְקָא דִּינָא, (דנפק) גְּבוּרָה עִלָּאָה. וְאִי תֵּימָא, וְהָיָה אִם שָׁמוֹעַ דְּלָאו הִיא דִּינָא. לֵית כִּתְרָא מִכָּל כִּתְרֵי מַלְכָּא, דְּלָא יִתְכְּלִיל דִּינָא וְרַחֲמֵי, כָּל שֶׁכֵּן גְּבוּרָה דְּאִתְכְּלִיל טַב וּבִישׁ.</p>\n<p>וְאִלֵּין אַרְבָּעָה נָטִיל לוֹן וָא\"ו, וְאִתְעֲטָּר בְּהוּ. וְאִלֵּין אִינּוּן תְּפִילִין דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא. תָּנֵינָן, הַאי וָא\"ו סָלִיק וְאִתְעֲטָּר בְּעִטְרוֹי, וְאָחִיד לְהַאי וּלְהַאי, וְאִתְעֲטָּר בְּכֻלְּהוּ, וְעַל דָּא וָא\"ו, אֶמְצָעִיתָא דְּכֹלָּא, דְּעֵילָּא וְתַתָּא, לְאַחֲזָאָה חָכְמְתָא שְׁלֵימָתָא מִכָּל סִטְרוֹי.</p>\n<p>(תאני רבי אבא, כתיב (דברים י׳:ט״ו)) רַק בַּאֲבוֹתֶיךָ חָשַׁק יְיָ'. מִכָּאן אָמַר רִבִּי שִׁמְעוֹן, אֲבָהָתָא אִינּוּן רְתִיכָא קַדִּישָׁא עִלָּאָה, וּכְתִיב חָשַׁק יְיָ'. תָּא חֲזֵי, כְּמָה דְּאִית רְתִיכָא קַדִּישָׁא לְתַתָּא, כַּךְ אִית רְתִיכָא קַדִּישָׁא לְעֵילָּא. וּמַאי נִיהוּ, הָא דְּאַמָרָן, רְתִיכָא קַדִּישָׁא כֹּלָּא אִקְרֵי, וְכֹלָּא אִתְקְשַׁר דָּא בְּדָא, וְאִתְעָבִיד כֹּלָּא חַד.</p>\n<p>רַק בַּאֲבוֹתֶיךָ תְּלָתָא, וּרְתִיכָא אַרְבְּעָה, ד' מְנָלָן. דִּכְתִּיב (דברים י׳:ט״ו) וַיִּבְחַר בְּזַרְעָם אַחֲרֵיהֶם. מַאי מַשְׁמַע. לְאַכְלְלָא בְּהוּ דָּוִד מַלְכָּא, דְּאִיהוּ רְבִיעָאָה, לְאִתְתַּקְנָא בִּרְתִיכָא קַדִּישָׁא. דְּתָנֵינָן, אֲבָהָתָא תִּקּוּנָא וּשְׁלֵימוּתָא דְּכֹלָּא, וְגוּפָא בְּהוּ אִשְׁתַּכְלָל וְאִתְבְּנֵי, וּבְהוּ אִתְאֲחִיד. אָתָא דָּוִד מַלְכָּא, וְשַׁכְלִיל כֹּלָּא, וְאַתְקִין גּוּפָא, וְאַשְׁלְמֵיהּ בְּהוּ. וְאָמַר רִבִּי יִצְחָק, כְּמָה דְּזָכוּ אֲבָהָתָא לְאִתְעַטְּרָא בִּרְתִיכָא קַדִּישָׁא, כַּךְ זָכָה דָּוִד לְאִתְתַּקְנָא בְּסַמְכָא רְבִיעָאָה דִּרְתִיכָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, כְּתִיב בֵּיהּ בְּדָוִד, (שמואל א ט״ז:י״ב) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. מַאי טַעֲמָא אַדְמוֹנִי. מִשּׁוּם דְּחוּלָקָא דְּעַדְבֵיהּ גַּרְמָא לֵיהּ. אַדְמוֹנִי דִּינָא וַדַּאי. עִם יְפֵה עֵינַיִם, דִּינָא בְּרַחֲמֵי. כְּמָה דִּכְתִּיב, (ישעיהו נ״ה:ג׳) חַסְדֵּי דָּוִד הַנֶּאֱמָנִים.</p>\n<p>אָמַר רִבִּי יִצְחָק, חַסְדֵּי דָּוִד, בְּאַתְרֵיהּ אוֹקִימְנָא. אֶלָּא וְהוּא אַדְמוֹנִי, כִּדְאַמָרָן. עִם יְפֵה עֵינַיִם, אִלֵּין אֲבָהָתָא. תָּא חֲזֵי, יְרוּשָׁלַיִם וְצִיּוֹן, דִּינָא וְרַחֲמֵי. וְאַף עַל פִּי כֵּן כְּתִיב, (מלכים א ח׳:א׳) עִיר דָּוִד הִיא צִיּוֹן. וּכְתִּיב (הושע י״א:ט׳) בְּקִרְבְּךָ קָדוֹשׁ וְלֹא אָבֹא בְּעִיר, נִשְׁבַּע קוּדְשָׁא בְּרִיךְ הוּא שֶׁלֹּא יִכָּנֵּס בִּיְרוּשָׁלַ ם שֶׁל מַעֲלָה וְכוּ'. אֵימָתַי. אָמַר רִבִּי יְהוּדָה, כַּד אִתְהַדָּר מַלְכוּ בֵּית דָּוִד לְאַתְרֵיהּ לְתַתָּא.</p>\n<p>רִבִּי יִצְחָק אָמַר, ש' דִּרְשִׁימָא בִּתְלַת קִשְׁרֵי, (דד' קשרין רמיזא היא לתלתא ורמיזא לארבעה, תלת הא דאמרן. ארבעה למהוי רתיכא קדישא כחדא. דהא הוא כללא דתקונא עלאה ומהכא מתפרשן ואתמשכן תתאי באורחייהו ברצועיהון דתליין בהני שערי דרישא דתליין בהו ואתמשכן מנייהו כל אינון אחרנין עד דאתקשרן באתרייהו).</p>\n<p>תָּנֵינָן, ו' נָטִיל אִינּוּן עִלָּאֵי דְּאַמָרָן, וְאִלֵּין תְּפִלִּין דְּאָנַח קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין כַּךְ בָּעֵי בַּר נָשׁ לְאִתְפָּאֲרָא בְּהוּ, עָלֵיהּ כְּתִיב (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ, שֵׁם יְיָ' מַמָּשׁ. וְאִלֵּין אִינּוּן תְּפִלִּין דְּרֵישָׁא, תְּפִלִּין דִּדְרוֹעָא הִיא שְׂמָאלָא, דְּאִקְרֵי עֹז, וְיָרְתָא מֵעֹז, הֲדָא הוּא דִכְתִיב, (שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה בְּהֵ\"א, וְהִיא הֵ\"א דְּאוֹקִימְנָא. זַכָּאָה חוּלָקֵיהוֹן <Nonei></i> דְּיִשְׂרָאֵל. וְעַל דָּא, הֵ\"א בַּתְרָאָה נַטְלָא תְּפִלִין, דְּהִיא שְׂמָאלָא.</p>\n<p>לְמַאן (נ\"א ומאן) אִינּוּן אִלֵּין אַרְבְּעָה, דְּאִינּוּן חַד גּוּפָא, וְעַל דָּא כְּלִילָן בְּחַד, וּמַאן אִינּוּן. תִּפְאֶרֶת נֶצַח הוֹד יְסוֹד. וְהִיא הֵ\"א דְּיָדְכָה, וְכֻלְּהוּ אֲחִידָא בָּהּ, בְּגִין לְאִתְבָּרְכָא מִנַּיְיהוּ, וּכְלִילָא מִכֻּלְּהוּ.</p>\n<p>אָמַר רִבִּי חִיָּיא, אִי הָכִי הָא כְּתִיב (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי, וְתָנֵינָן דָּא קֶשֶׁר שֶׁל תְּפִלִּין. אָמַר לֵיהּ, הָא אוֹקְמוּהָ, וְשַׁפִּיר הוּא, וְכֹלָּא בְּרִירָא דְּמִלָּה. וְעַל דָּא מֵהַאי תַּלְיָיא רְצוּעָה חַד לְתַתָּא, דְּהָא מִנָהּ תַּלְיָין תַּתָּאֵי, וְאִתְּזָנוּ מִנָהּ. וְעַל דָּא אִיתְקְרֵי אוֹת. כְּמָה דְאַתְּ אָמֵר (בראשית ט׳:י״ב) זֹאת אוֹת הַבְּרִית. וּכְתִיב (שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה בְּה' וְהָא אוֹקְמוּהָ.</p>\n<p>(דברים ו') שְׁמַע יִשְׂרָאֵל. אָמַר רִבִּי יֵיסָא, יִשְׂרָאֵל סָבָא. רִבִּי יִצְחָק אָמַר ע' רַבְרְבָא, לְאַכְלְלָא שִׁבְעִין שְׁמָהָן, סַהֲדוּתָא דְּכֹלָּא שְׁמַע יִשְׂרָאֵל, כְּמָה דִּכְתִּיב, (ישעיהו א׳:ב׳) שִׁמְעוּ שָׁמַיִם. וּכְתִיב (דברים ל״ב:א׳) הַאֲזִינוּ הַשָּׁמַיִם. אוּף הָכָא שְׁמַע יִשְׂרָאֵל. וְכֹלָּא חַד מִלָּה הוּא. יְדוָֹ\"ד, רֵישָׁא דְּכֹלָּא, בִּנְהִירוּ דְּעַתִּיקָא קַדִּישָׁא. וְהַאי הוּא דְּאִקְרֵי אָ\"ב. אֱלֹהֵינוּ, עֲמִיקְתָא דְּנַחֲלִין וּמַבּוּעִין, דְּנָפְקִין וְנַגְדִּין לְכֹלָּא.</p>\n<p>יְדוָֹ\"ד, גוּפָא דְּאִילָנָא שְׁלִימוּ דְּשָׁרָשִׁין. אֶחָד, כְּנֶסֶת יִשְׂרָאֵל. וְכֹלָּא חַד שְׁלֵימוּתָא, וְאִתְקְשַׁר דָּא בְּדָא, וְלָא אִשְׁתְּכַח פִּרוּדָא, אֶלָּא כֹּלָּא חַד.</p>\n<p>תָּנֵי רִבִּי יִצְחָק, רְתִיכָא קַדִּישָׁא עִלָּאָה, אַרְבַּע בָּתֵּי דִּתְפִילִין דְּאָנַח ו'. כְּמָה דְּאִתְּמַר. רְתִיכָא קַדִּישָׁא אָחֳרָא, אַרְבַּע אַחֲרָנִין דִּכְלִילָן בְּחַד, דְּאָנַח ה' בַּתְרָאָה כְּמָה דְּאוֹקְמוּהָ.</p>"],[9520012647,"<p><Noneb>רעיא מהימנא</b><br>(דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, פִּקּוּדָא דָּא, (ד) (עיין בהקדמה י\"ג ע\"ב) לְיַחֲדָא שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, דְּהָא כְּמָה דִּמְיַיחֲדֵי שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא, הָכִי אִתְיָיחָד שְׁמֵיהּ לְעֵילָּא. אִשְׁתְּכַח קוּדְשָׁא בְּרִיךְ הוּא יְחִידָאי עֵילָּא וְתַתָּא. מַאן דִּמְיַיחֵד שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, יְשַׁוִּי לִבֵּיהּ וּרְעוּתֵיהּ בְּהַהוּא יִחוּדָא דְּקָאַמְרָן, וִיחַבֵּר כָּל שַׁיְיפוֹי בְּהוּא יִחוּדָא בְּהַהוּא רְעוּתָא לְמֶהֱוִי כֻּלְּהוּ אֶחָד. כְּמָה דְּשַׁוִּי כָּל שַׁיְיפוֹי בְּרָזָא דְּחָד, הָכִי לְעֵילָּא מְחַבֵּר כָּל שַׁיְיפִין עִלָּאִין בְּהַהוּא יִחוּדָא, לְמֶהֱוִי כֻּלְּהוּ חַד.</p>\n<p>בְּשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְיַיחְדָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל חֵילֵי שְׁמַיָא כֻּלְּהוּ, קַיְימִין שׁוּרִין שׁוּרִין, בְּגִין לְאִתְתַּקְנָא וּלְאִתְכַּלְּלָא כֻּלְּהוּ בְּהַהוּא יִחוּדָא, לְמֵיקָם בְּרָזָא דְּחָד בְּיִחוּדָא חֲדָא. כֻּלְּהוּ מִתְתַּקְּנָן בְּתִקּוּנֵיהוֹן כְּדְקָא יָאוּת. בְּהַאי שַׁעֲתָא קַיְּימָא חַד מְמָנָא שַׁמָשָׁא, דְּקַיְּימָא תְּחוֹת רמ\"ח עָלְמִין, וְכֻלְּהוּ אִקְרוּן שַׁיְיפִין דְּגוּפָא. וְדָא אִקְרֵי הלני\"ו, קַיְּימָא מְחַכָּה לְהַהוּא יִחוּדָא, וְדָא אִיהוּ מְלַקֵּט שׁוֹשַׁנִּים, כְּמָה דְאַתְּ אָמֵר (שיר השירים ו׳:ב׳) וְלִלְקוֹט שׁוֹשַׁנִּים. דְּאִינּוּן שַׁיְיפִין דְּגוּפָא.</p>\n<p>שַׁיְיפִין עִלָּאִין לָקִיט לוֹן שְׁמָא עִלָּאָה, בְּרָזָא דְּיִחוּדָא דְּקָא אִתְיָיחָד בְּרָזָא דְּמ\"ב שְׁמָהָן. וְלָקִיט כָּל אִינּוּן שׁוֹשַׁנִּים עִלָּאִין, וְשַׁמָּשָׁא דָּא לָקִיט כָּל אִינּוּן תַּתָּאִין, דִּי כֻּלְּהוּ מְמָנָן בִּכְלָלָא דְּע\"ב שְׁמָהָן, וְאִתְלְקִּיטוּ כֻּלְּהוּ בְּהַהוּא יִחוּדָא, וְאִתְעָבִידוּ כֻּלְּהוּ גּוּפָא חֲדָא. בְּרָזָא חֲדָא. וְהַהוּא יִחוּדָא סַלְּקָא, וְקָא מְיַיחֵד כֹּלָּא בִּתְרֵין סִטְרִין בְּיִחוּדָא חֲדָא. בְּהַהוּא שַׁעֲתָא מִתְלַקְּטִין שַׁיְיפִין כֻּלְּהוּ, וּמִתְחַבְּרָן בְּחִבּוּרָא חֲדָא, לְמֶהֱוִי כֻּלְּהוּ בְּרָזָא דְּחָד, עֵילָּא וְתַתָּא, בְּרָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>וְעַל דָּא מַאֲרִיכִין בְּאֶחָד, בִּתְרֵי אַתְוָון. לְמִלְקַּט שׁוֹשַׁנִּים, לְאִתְיַיחֲדָא בְּרָזָא דְּאֶחָד בְּיִחוּדָא שְׁלִים. כֵּיוָן דְּאִתְיַיחֲדָן שַׁיְיפִין כֻּלְּהוּ, בְּרָזָא חֲדָא דְּיִחוּדָא חֲדָא, כְּדֵין אִתְקְרֵי כֹּלָּא קָרְבָּן שְׁלִים. וְעַל רָזָא דָּא, אָעִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּגַּן עֵדֶן לְאָדָם קַדְמָאָה, כְּמָה דִּכְתִּיב, (בראשית ב׳:ט״ו) לְעָבְדָהּ וּלְשָׁמְרָהּ. וְתָנֵינָן, דְּאִלֵּין אִינּוּן קָרְבְּנִין תְּרֵין, רָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד. דְּאִינּוּן קָרְבְּנִין כְּתִיב, וְלִלְקוֹט שׁוֹשַׁנִּים. (ד\"א דקודשא בריך הוא איהו לקיט שושנים לקיט כל אינון שייפין דעילא ותתא לחברא לון ביחודא בההוא דקאמרן. כדין אתער מאן דאתער ללקוט שושנים) אִלֵּין שַׁיְיפִין דִּתְרֵין סִטְרִין, דְּאִינּוּן חַד.</p>\n<p>שׁוֹשַׁנִּים רָזָא אִיהוּ. דְּכַד מִתְחַבְּרָן כָּל (אינון) שַׁיְיפִין כַּחֲדָא, לְמֶהֱוִי כֻּלְּהוּ בְּיִחוּדָא חֲדָא, רָזָא דְּקָרְבָּן, כְּדֵין מִתְעַטֵר קוּדְשָׁא בְּרִיךְ הוּא בַּעֲטָרָה בְּרֵישָׁא דְּכֶתֶם פָּז, לְמֶהֱוִי בִּיקָרוֹי מִתְעַטְרָא. וְרָזָא דָּא הֲוִי דִּכְתִּיב שׁוֹשַׁנִּים, רָזָא דְּכָל אִינּוּן שַׁיְיפִין דְּעֵילָּא וְתַתָּא. וְרָזָא דְּהַהוּא פָּז, עִטוּרָא דְּמִתְעַטְרָא וְסַלְּקָא מִבֵּינַיְיהוּ, וְכֹלָּא אִיהוּ בֵּיהּ.</p>\n<p>בְּהָנֵי שׁוֹשַׁנִּים אִית בָּהּ שִׁית מְאָה וּתְלֵיסָר פִּקּוּדִין, דְּאִינּוּן שַׁיְיפִין דִּתְרֵין סִטְרִין, רָזָא דַּיְדוָֹד אֶחָד וּשְׁמוֹ אֶחָד. <Nonei></i> וְאִית בֵּיהּ סְלִיקוּ דְּהַהוּא פָּז, דְּקָא סָלִיק מִבֵּינַיְיהוּ. וּבְכָל אֲתָר דְּאִינּוּן מִשְׁתַּכְּחִין, הַהוּא סְלִיקוּ עִלָּאָה אִשְׁתְּכַח מִבֵּינַיְיהוּ לְאִסְתַּלְּקָא. וְרָזָא דָּא (שיר השירים ב׳:ג׳) תַּפּוּחַ בַּעֲצֵּי הַיַּעַר. וְשׁוֹשַׁנָּה בֵּין הַחוֹחִים. דָּא וְדָא אִצְּטְרִיךְ לְאִסְתַּלְּקָא כַּחֲדָא בְּיִחוּדָא שְׁלִים. זַכָּאָה אִיהוּ מַאן דְּקָרִיב קָרְבְּנִין אִלֵּין, וַדַּאי לְרַעֲוָא לֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.</p>"],[9520012648,"<p>פִּקּוּדָא לְיִרְאָה (ה) בְּאֹרַח כְּלָל, וּבְאֹרַח פְּרָט. וְהָא יִרְאָה אוֹקִימְנָא, בְּגִין דְּאִית עָלֵיהּ דְּבַּר נָשׁ לְדַחֲלָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא תָּדִיר. כְּמָה דְאַתְּ אָמֵר, (דברים כ״ח:נ״ח) לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא הַזֶּה אֵת יְיָ' אֱלֹהֶיךָ. וּבְגִין יִרְאָה דָּא, יִסְתָּמָר בְּאָרְחוֹי. וְיִרְאָה, אֲתָר הוּא דְּאִקְרֵי יִרְאָה, בְּגִין דְּתַמָּן שַׁרְיָא דַּחֲלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ יִרְאַת יְיָ' לְדַחֲלָא מִנֵּיהּ, וְדָא אִיהוּ רָזָא דִּכְתִּיב, וּמִמִּקְדָּשִׁי תִּירָאוּ בְּהַאי יִרְאָה שַׁרְיָא פּוּלְסָא דְּנוּרָא, לְאַלְקָאָה לוֹן לְחַיָּיבַיָּא, דְּלָא נַטְרִין פִּקּוּדֵי אוֹרַיְיתָא וְעַל דָּא בְּאֹרַח כְּלַל, אִית לְדַחֲלָא.</p>\n<p>וּבָתַר בְּאֹרַח פְּרָט, כַּד יָדַע בַּר נָשׁ מַאן אִיהִי יִרְאַת יְיָ', וְדָא אִיהוּ דַּחֲלָא דַּחֲבִיבוּתָא, דְּאִיהִי עִיקָר וִיסוֹדָא לְמִרְחַם לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. (בתר) הַאי יִרְאָה עָבִיד לְנַטְרָא כָּל פִּקּוּדוֹי דְּאוֹרַיְיתָא, לְמֶהֱוִי בַּר נָשׁ עֶבֶד נֶאֱמָן לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא כַּדְּקָא יָאוּת. (יראה)</p>"],[9520012649,"<p>פִּקּוּדָא (ו) לְאַהֲבָה, וְהָא אוֹקִימְנָא רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּבָעֵי בַּר נָשׁ לְרַחֲמָא לֵיהּ רְחִימוּ סַגֵּי כְּאַבְרָהָם, דְּרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה רְחִימוּ, וּמָסַר גּוּפֵיהּ וְנַפְשֵׁיהּ לְגַבֵּיהּ. מִכָּאן אוֹלִיפְנָא, מַאן דְּרָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ מְקַיֵּים עֶשֶׂר אֲמִירָן עֵילָּא וְתַתָּא. וְעַל דָּא כָּל אִינּוּן עֶשֶׂר נִסְיוֹנֵי דְּאִתְנַסָּא אַבְרָהָם, וְקָאִים בְּכֻלְּהוּ לָקֳבֵל עֶשֶׂר אֲמִירָן, כָּל נִסְיוֹנָא אֲמִירָא הִיא, וְאִתְנָסָּא בְּהַהוּא אֲמִירָא, וְקָאִים בֵּיהּ.</p>\n<p>וְעַל דָּא אִינּוּן עֶשֶׂר נִסְיוֹנֵי, וְכֻלְּהוּ קָאִים בְּהוּ אַבְרָהָם, בְּגִין דְּאִתְקְשַּׁר וְאִתְדַּבָּק בִּימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהִי אַהֲבָה רַבָּה. מַאי טַעְמָא אִיקְרֵי אַהֲבָה רַבָּה. בְּגִין מַאן דְּקָאִים בְּהַאי אַהֲבָה, אִתְקְשַּׁר בְּעָלְמָא עִלָּאָה. אַהֲבַת עוֹלָם, דָּא רָזָא דְּעָלְמָא תַּתָּאָה, דְּאִתְקְשַׁר בֵּיהּ רְחִימוּ דִּילֵיהּ, וְכֹלָּא רָזָא חֲדָא, בְּלָא פִּרוּדָא, וְהָא אִתְּמַר רָזָא דְּאַהֲבָה, רְחִימוּ דָּא סָלִיק עַל כָּל פּוּלְחָנִין דְּעָלְמָא, בְּהַאי אִתְיְיקַר שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא יַתִּיר מִכֹּלָּא, וְאִתְבְּרַךְ. בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמִין, וְרָזָא דְּאַהֲבָה אִתְּמַר. ע\"כ (קע\"ב ע\"ב ציצית וכו')</p>\n<p>פִּקּוּדָא (ז) לְמִקְרֵי קְרִיאַת שְׁמַע ב' זִמְנִין בְּכָל יוֹמָא. חַד, לָקֳבֵל דַּרְגָּא דִּימָמָא. וְחַד, לָקֳבֵל דַּרְגָּא דְּלֵילְיָא. וּלְאַכְלְלָא בִּימָמָא דַּרְגָּא דְּלֵילְיָא, וּלְאַכְלְלָא בְּלֵילְיָא דַּרְגָּא דִּימָמָא, וְהָא אִתְּמַר. וְעַל דָּא תְּרֵין זִמְנִין בְּכָל יוֹמָא, חַד בִּימָמָא וְחַד בְּלֵילְיָא.</p>"],[9520012650,"<p>פִּקּוּדָא לְמִקְבַּע בַּר נָשׁ מְזוּזָה לְתַרְעֵיהּ, לְמֶהֱוִי כָּל בַּר נָשׁ נָטִיר מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, כַּד נָפִיק וְכַד עָיִּיל. וְרָזָא (תהילים קכ״א:ח׳) יְיָ' יִשְׁמָר צֵּאתְךָ וּבֹאֶךָ מֵעַתָּה וְעַד עוֹלָם. בְּגִין דְּרָזָא דִּמְזוּזָה אִיהוּ קָאִים תָּדִיר לְפִתְחָא. וְדָא אִיהוּ פִּתְחָא דִּלְעֵילָּא, וְדָא אִיהוּ דַּרְגָּא דְּאִקְרֵי שׁוֹמֵר, לְאִשְׁתַּכְּחָא בִּנְטִירוּ.</p>\n<p>דְּבַּר נָשׁ לָאו אִיהוּ נָטִיר, בַּר נְטִירוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ נָטִיר תָּדִיר, וְקָאִים לְפִתְחָא, וּבַּר נָשׁ לְגוֹ. וְתוּ, דְּלָא יִנְשֵׁי בַּר נָשׁ דּוּכְרָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. וְדָא אִיהוּ כְּגַוְונָא דְּצִּיצִּית, כְּמָה דְאַתְּ אָמֵר (במדבר ט״ו:ל״ט) וּרְאִיתֶם אוֹתוֹ וּזְּכַרְתֶּם אֶת וְגוֹ'. כֵּיוָן דְּחָמֵי בַּר נָשׁ לְהַאי דּוּכְרָנָא, אִדְכַּר בְּגַרְמֵיהּ לְמֶעְבַּד פִּקּוּדָא דְּמָארֵיהּ. וְרָזָא דִּמְהֵימְנוּתָא, מְזוּזָה כְּלָלָא דְּכַר וְנוּקְבָּא כַּחֲדָא.</p>\n<p>בְּסִפְרָא דִּשְׁלֹמֹה, סָמִיךְ לְפִתְחָא, לָקֳבֵל תְּרֵין דַּרְגִּין, אִזְדְּמַן חַד שִׁידָא (ודא איהו) וְאִית לֵיהּ רְשׁוּ לְחַבְּלָא. וְאִיהוּ קָאִים לִסְטַר שְׂמָאלָא. זָקִיף בַּר נָשׁ עֵינוֹי, חָמֵי לֵיהּ לְרָזָא דִּשְׁמָא דְּמָארֵיהּ, וְאִדְכַּר לֵיהּ, וְלָא יָכִיל לֵיהּ לְאַבְאָשָׁא. וְאִי תֵּימָא, אִי הָכִי כִּי נָפִיק בַּר נָשׁ מִתַּרְעֵיהּ לְבַר, הָא הַהוּא שִׁידָא קָאִים לִימִינֵיהּ, וּמְזוּזָה לִשְׂמָאלֵיהּ, וְהֵיאַךְ אִתְנְטִיר בַּר נָשׁ, אִי אִיהוּ שָׁארֵי לִשְׂמָאלֵיהּ.</p>\n<p>אֶלָּא כָּל מַה דְּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא, כָּל מִלָּה וּמִלָּה אִתְמְשַׁךְ בָּתַר זִינֵיהּ. בְּבַר נָשׁ קַיְימִין תְּרֵין דַּרְגִּין, חַד מִימִינָא, וְחַד מִשְּׂמָאלָא. הַהוּא דִּימִינָא אִקְרֵי יֵצֶּר הַטוֹב, וְהַהוּא דִּשְׂמָאלָא אִקְרֵי יִצֶּר הָרָע. כֵּיוָן דְּנָפַק בַּר נָשׁ מִתַּרְעָא דְּבֵיתֵיהּ, הַהוּא שִׁידָא זָקִיף עֵינוֹי, וְחָמֵי לְיִצֶּר הָרָע, דְּשָׁארִי לִשְׂמָאלָא, אִתְמְשַׁךְ לְהַהוּא סִטְרָא וְאִתְעָדֵי מִימִינָא. וּבְהַהוּא סִטְרָא, קָאִים שְׁמָא דְּמָארֵיהּ, וְלָא יָכִיל לְקָרְבָא וּלְאַבְאָשָׁא לֵיהּ, וְנָפִיק בַּר נָשׁ <Nonei></i> וְאִשְׁתְּזִיב מִנֵּיהּ. כַּד עָיִּיל, הָא שְׁמָא קַדִּישָׁא לִימִינָא קָאִים, וְלָא יָכִיל לְקַטְרְגָא בַּהֲדֵיהּ.</p>\n<p>וְעַל דָּא אִצְּטְרִיךְ בַּר נָשׁ, דְּלָא יַעְבִּיד (ס\"א יעביר) טִנּוּפָא וְלִכְלוּכָא בְּתַרְעָא דְּבֵיתֵיהּ, וְלָא יוֹשִׁיד מַיִין עֲכוּרִין. חַד, דְּלָא יַעְבִּיד קְלָנָא לְגַבֵּי שְׁמָא דְּמָארֵיהּ. וְחַד, דְּאִית לֵיהּ רְשׁוּ לְהַהוּא מְחַבְּלָא לְחַבְּלָא. וּבְּגִין כָּךְ יִזְדַּהֵר בַּר נָשׁ מֵהַאי, וְיִזְדְּהַר בַּר נָשׁ דְּלָא יִמְנַע מִתַּרְעָא דְּבֵיתֵיהּ שְׁמָא דְּמָארֵיהּ.</p>\n<p>וְכַד בַּר נָשׁ אַתְקִין מְזוּזָה לְפִתְחֵיהּ, כַּד עָיִּיל (ס\"א ההוא בר נש), הַהוּא יִצֶּר הָרָע וְהַהוּא שִׁידָא בַּעַל כָּרְחַיְּיהוּ נַטְרֵי לֵיהּ, וְאַמְרֵי (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ' צַּדִּיקִים יָבֹאוּ בוֹ. וְכַד לָא קָאִים מְזוּזָה לְפִתְחֵיהּ דְּבַּר נָשׁ, יִצֶּר הָרָע וְהַהוּא שִׁידָא מִתְתַּקְנִין כַּחֲדָא, שַׁוּוּ יְדַיְיהוּ עַל רֵישֵׁיהּ בְּזִמְנָא דְּעָיִּיל, פַּתְחֵי וְאַמְרֵי, וַוי לֵיהּ לִפְלַנְיָּא, דְּהָא נָפַק מֵרְשׁוּתָא דְּמָארֵיהּ, מֵהַהוּא זִמְנָא קָאִים בְּלָא נְטִירוּ, דְּלֵית מַאן דְּנָטִיר עָלֵיהּ, רַחֲמָנָא לִישֵׁזְבָן (צ\"א ע\"ב פקודאי לאומאה וכו').</p>"],[9520012651,"<p>(דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, דָּא אִיהוּ יִחוּדָא חַד. בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, הָא יִחוּדָא אַחֲרָא, לְמֶהֱוִי שְׁמֵיהּ רָזָא חַד. וְרָזָא דָּא, (מלכים א יח) יְיָ' הוּא הָאֱלֹהִים, דָּא כְּתִיב, כַּד אִינּוּן בְּיִחוּדָא חַד.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי כְּגַוְונָא דִּכְתִּיב, (זכריה יד) יְיָ' אֶחָד וּשְׁמוֹ אֶחָד, (נדפס בתרומה קע\"א ע\"ב) לָאו אִיהוּ יְיָ' הוּא הָאֱלֹהִים, דְּאִי כְּתִיב יְיָ' וּשְׁמוֹ הוּא אֶחָד, הֲוִינָא אַמְרֵי הָכִי, לָא כְּתִיב אֶלָּא יְיָ' אֶחָד וּשְׁמוֹ אֶחָד, וְאִצְּטְרִיךְ לוֹמַר בְּגַוְונָא דָּא, יְיָ' הוּא הָאֱלֹהִים הוּא, וְיִתְחֲזֵי יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>אֶלָּא כֹּלָּא חַד, דְּכַד אִתְאַחֲדָן תְּרֵין שְׁמָהָן אִלֵּין, דָּא בְּיִחוּדָא חַד, וְדָא בְּיִחוּדָא חַד, כְּדֵין תְּרֵין שְׁמָהָן אִלֵּין אִתְעָבִידוּ חַד, וְאִתְכְּלִילָן דָּא בְּדָא, וַהֲוִי כֹּלָּא שְׁמָא שְׁלִים בְּיִחוּדָא חֲדָא, וּכְדֵין יְיָ' הוּא הָאֱלֹהִים, דְּהָא כְּדֵין אִתְכְּלִיל כֹּלָּא דָּא בְּדָא לְמֶהֱוִי חַד, וְעַד דְּאִתְיַיחֲדוּ כָּל חַד דָּא בִּלְחוֹדוֹי וְדָא בִּלְחוֹדוֹי, לָא אִתְכְּלִילוּ דָּא בְּדָא, לְמֶהֱוִי כֹּלָּא חַד.</p>\n<p>כְּלָלָא דְּכָל אוֹרַיְיתָא, הָכִי הוּא וַדַּאי, דְּהָא אוֹרַיְיתָא אִיהִי תּוֹרָה שֶׁבִּכְתָּב, וְאִיהִי תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָּב, דָּא הוּא דִּכְתִּיב יְיָ'. תּוֹרָה שֶׁבְּעַל פֶּה, דִּכְתִּיב הָאֱלֹהִים. וּבְגִין דְּאוֹרַיְיתָא אִיהִי רָזָא דִּשְׁמָא קַדִּישָׁא, אִקְרֵי הָכִי.</p>\n<p>תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, דָּא כְּלָל, וְדָא פְּרָט. כְּלַל אִצְּטְרִיךְ לִפְרָט, וּפְרָט אִצְּטְרִיךְ לִכְּלָל, וְאִתְיַיחֲדוּ דָּא בְּדָא, וַהֲוִי כֹּלָּא חַד. וְעַל דָּא כְּלָלָא דְּאוֹרַיְיתָא, אִיהוּ כְּלָלָא דִּלְעֵילָּא וְתַתָּא, בְּגִין דִּשְׁמָא דָּא לְעֵילָּא, וּשְׁמָא דָּא לְתַתָּא. דָּא רָזָא דְּעָלְמָא עִלָּאָה. וְדָא רָזָא דְּעָלְמָא תַּתָּאָה. וְעַל דָּא כְּתִיב אַתָּה הָרְאֵתָ לָדַעַת כִּי יְיָ' הוּא הָאֱלֹהִים, דָּא כְּלָלָא דְּכֹלָּא, וְכָל דָּא דְּאַמָרָן, אִצְּטְרִיךְ בַּר נָשׁ לְמִנְדַּע בְּהַאי עָלְמָא.</p>\n<p>וְאִי תֵּימָא, פִּקּוּדֵי אוֹרַיְיתָא אָן אִינּוּן הָכָא, בִּכְלָלָא דָּא. אֶלָּא דָּא אִיהוּ זָכוֹר. וְדָא אִיהוּ שָׁמוֹר. וְכָל פִּקּוּדֵי אוֹרַיְיתָא בְּהָנֵי כְּלִילָן, בְּרָזָא דְּזָכוֹר, וּבְרָזָא דְּשָׁמוֹר, וְכֹלָּא אִיהוּ חַד.</p>\n<p>פָּתַח רִבִּי יוֹסִי וְאָמַר, הָא דְּתָנֵינָן צְּלוֹתָא דְּעַרְבִית חוֹבָה אִיהוּ, וַדַּאי בְּגִין דִּקְרִיאַת שְׁמַע דְּעַרְבִית חוֹבָה, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְיָיחָד בְּלֵילְיָא, כְּמָה דְּאִתְיָיחַד בִּימָמָא. וּמִדַּת לַיְלָה אִתְכְּלִיל בִּימָמָא, וּמִדַּת יְמָמָא אִתְכְּלִיל בְּלֵילְיָא, וְאִתְעָבִיד יִחוּדָא. וּמַאן דְּאָמַר רְשׁוּת, בְּגִין אֵימוּרִין וּפְדָרִין דְּמִתְעַכְּלֵי בְּלֵילְיָא. וְהָא אוֹקִימְנָא.</p>\n<p>דִּכְתִּיב וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ, הַאי קְרָא אוֹקִימְנָא, וְאוֹקְמוּהָ חַבְרַיָּיא. אֲבָל אִית לְשָׁאֲלָא, אִי בְּהַאי יִחוּדָא דִּשְׁמַע יִשְׂרָאֵל, אִתְכְּלִיל כֹּלָּא, יְמִינָא וּשְׂמָאלָא, אֲמַאי כְּתִיב לְבָתַר וְאָהַבְתָּ, וְהָיָה אִם שָׁמוֹעַ, דְּהָא בְּיִחוּדָא אִתְכְּלִילוּ. אֶלָּא הָתָם בִּכְלָל. הָכָא בִּפְרָט. וְהָכִי אִצְּטְרִיךְ.</p>\n<p>וּבְרָזָא דְּיִחוּדָא דְּהָא אִתְּעַרְנָא בֵּיהּ, יִחוּדָא אִיהוּ כְּגַוְונָא דִּתְפִלִּין דְּרֵישָׁא, וּתְפִילִּין דִּדְרוֹעָא, בִּתְפִילִין דְּרֵישָׁא ד' פַּרְשִׁיָּין, וְהָא אִתְּמַר. וְהָכָא ג' שְׁמָהָן אִינּוּן. הָתָם אַרְבַּע פַּרְשִׁיָּין, וְכָל חַד וְחַד בִּלְחוֹדוֹי. וְהָכָא ג' שְׁמָהָן, מַה בֵּין הַאי לְהַאי.</p>"],[9520012652,"<p>אֶלָּא אִינוּן אַרְבַּע פַּרְשִׁיָּין הָא אַתְּעֲרוּ בְּהוּ, חַד נְקוּדָּה (ס\"א עלאה) קַדְמָאָה. וְחַד רָזָא דְּעָלְמָא דְּאָתֵי. וְחַד יְמִינָא <Nonei></i> וְחַד שְׂמָאלָא. אִלֵּין רָזָא דִּתְפִילִין דְּרֵישָׁא. וְהָכָא בְּרָזָא דָּא, יִחוּדָא דָּא תְּלַת שְׁמָהָן עִלָּאִין, אִינּוּן כְּגַוְונָא דְּאִינּוּן אַרְבַּע פָּרְשִׁיָּין. יְיָ' קַדְמָאָה, דָּא נְקוּדָה עִלָּאָה, רֵאשִׁיתָא דְּכֹלָּא. אֱלֹהֵינוּ, רָזָא דְּעָלְמָא דְּאָתֵי. יְיָ' בַּתְרָאָה, כְּלָלָא דִּימִינָא וּשְׂמָאלָא כַּחֲדָא, בִּכְלָלָא חֲדָא וְאִלֵּין אִינּוּן תְּפִלָּה דְּרֵישָׁא, וְדָא אִיהוּ יִחוּדָא קַדְמָאָה.</p>\n<p>תְּפִלִּין דִּדְרוֹעָא, כְּלָלָא (גו תפלין דדרועא כללא) דְּכָל הָנֵי כַּחֲדָא, וְדָא אִיהוּ רָזָא, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. (עיין בהקדמה י\"ג ע\"ב) הָכָא כְּלָלָא דְּאִינּוּן תְּפִלִּין דְּרֵישָׁא, דְּאִתְכְּלִילוּ גּוֹ תְּפִלִּין דִּדְרוֹעָא.</p>\n<p>וְרָזָא דָּא, בָּרוּךְ: דָּא רָזָא דִּנְקוּדָה עִלָּאָה, דְּאִיהוּ בָּרוּךְ, דְּכָל בִּרְכָאן נַבְעִין מִתַּמָּן. וְאִי תֵּימָא, עָלְמָא דְּאָתֵי אִקְרֵי בָּרוּךְ. לָאו הָכִי. דְּהָא נְקוּדָּה עִלָּאָה אִיהוּ דְּכַר, עָלְמָא דְּאָתֵי נוּקְבָּא, אִיהוּ בָּרוּךְ, וְאִיהִי בְּרָכָה, בָּרוּךְ דְּכַר, בְּרָכָה נוּקְבָּא. וְעַל דָּא בָּרוּךְ אִיהוּ נְקוּדָּה עִלָּאָה. שֵׁם: דָּא עָלְמָא דְּאָתֵי, דְּאִיהוּ שֵׁם גָּדוֹל. כְּמָה דְאַתְּ אָמֵר (יהושע ז׳:ט׳) וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. כְּבוֹד: דָּא כְּבוֹד עִלָּאָה, דְּאִיהוּ יְמִינָא וּשְׂמָאלָא, וְכֻלְּהוּ כְּלִילָן בְּהַאי תְּפִלָּה שֶׁל יַד, דְּאִיהוּ מַלְכוּתוֹ. וְנָטִיל כֹּלָּא בְּגַוִּיהּ, וּבְהַאי אִתְּכְּלִילָן בְּהַאי מַלְכוּת, עָלְמִין כֻּלְּהוּ, לְמֵיזָן לוֹן, וּלְסַפְּקָא לוֹן, בִּכְמָּה דְּאִצְּטְרִיכוּ.</p>\n<p>וְדָא אִיהוּ יִחוּדָא דִּתְפִלִּין דְּרֵישָׁא וּתְפִלִּין דִּדְרוֹעָא, כְּגַוְונָא דְּרָזָא דְּיִחוּדָא דִּתְפִלִּין, הָכִי הוּא יִחוּדָא דְּכֹלָּא. וְדָא אִיהוּ בְּרִירוּ דְּמִלָּה. וְהָא סָדַּרְנָא יִחוּדָא דָּא קַמֵּי בּוּצִּינָא קַדִּישָׁא, וְאָמַר לִי דְּהָא בְּד' גַּוְונִין אִתְסָדַּר יִחוּדָא, וְדָא בְּרִירָא דְּכֻלְּהוּ. וְהָכִי אִיהוּ וַדַּאי, וְכֻלְּהוּ רָזָא דְּיִחוּדָא, אֲבָל סִדּוּרָא דִּתְפִלִּין, דָּא הוּא יִחוּדָא עִלָּאָה כַּדְּקָא יָאוּת.</p>\n<p>וּמִגּוֹ דְּאִתְכְּלִילוּ יְמִינָא וּשְׂמָאלָא בְּרָזָא דִּשְׁמָא חַד בְּאֹרַח כְּלָל, אִצְּטְרִיךְ לְבָתַר לְאַפָּקָא לוֹן. בְּאֹרַח פְּרָט, אֲבָל לָאו בְּאֹרַח יִחוּדָא, דְּהָא יִחוּדָא בִּקְרָאֵי קַדְמָאֵי אִיהוּ, לְמֶהֱוִי יְיָ' אֶחָד, בִּתְפִלִּין דְּרֵישָׁא. וּשְׁמוֹ אֶחָד, בִּתְפִלִּין דִּדְרוֹעָא. וַהֲוִי כֹּלָּא חַד. כֵּיוָן דְּיִחוּדָא אִתְסָדָּר כֹּלָּא בִּכְלָלָא, מֵרֵישָׁא דִּנְקוּדָה עִלָּאָה, אִצְּטְרִיךְ לְבָתַר לְאִתְעַטְרָא מֵרֵישָׁא דִּנְהוֹרָא קַדְמָאָה, דְּאִיהוּ רֵישָׁא דְּכֹלָּא. (ע\"כ רעיא מהימנא).</p>\n<p>גָּלִיף וְאַתְקִין מֹשֶׁה, כ\"ה אַתְוָון בְּרָזָא דִּפְסוּקָא דְּיִחוּדָא, דִּכְתִּיב שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד. וְאִינּוּן כ\"ה אַתְוָון גְּלִיפִין, מְחֻקָּקִין בְּרָזָא דִּלְעֵילָּא. יַעֲקֹב בָּעָא לְאַתְקְּנָא לְתַתָּא, בְּרָזָא דְּיִחוּדָא, וְאַתְקִין בְּכ\"ד אַתְוָון, וְאִינּוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלָא אַשְׁלִים לְכ\"ה אַתְוָון, בְּגִין דְּעַד לָא אִתְתְּקַּן מַשְׁכְּנָא. כֵּיוָן דְּאִתְתְּקַן מַשְׁכְּנָא, וְאִשְׁתְּלִים מִלָּה דְּהֲוָה נָפִיק מִנֵּיהּ, כַּד אִשְׁתְּלִים, לָא מַלִּיל אֶלָּא בְּכ\"ה אַתְוָון, לְאַחֲזָאָה דְּהָא אִשְׁתְּלִים דָּא, כְּגַוְונָא דִּלְעֵילָּא, דִּכְתִּיב, (ויקרא א׳:א׳) וַיְדַבֵּר יְיָ' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, הָא כ\"ה אַתְוָון.</p>\n<p>וְעַל דָּא כ\"ה זִינִין, לְאַשְׁלְמָא תִּקּוּנָא דְּמַקְדְּשָׁא, וְכָל הָנֵי אַתְוָון אוֹקִימְנָא בְּאִינּוּן אַתְוָון גְּלִיפִין דְּאוֹלִיפְנָא מִמַּר. וּבְגִין דְּמַשְׁכְּנָא אִשְׁתְּלִים בְּרָזִין אִלֵּין, אִקְרֵי כ\"ה, בְּיִחוּדָא דִּשְׁלִימוּ דְּמַשְׁכְּנָא. וְעַל דָּא (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה כְּתִיב, רָזָא דִּשְׁלִימוּ דְּכָל מַשְׁכְּנָא, וְתִקּוּנָא דִּילֵיהּ.</p>\n<p>כ\"ה: לָקֳבֵל כ\"ב אַתְוָון, וְתוֹרָה וּנְבִיאִים וּכְתוּבִים, דְּאִינּוּן כְּלָלָא חֲדָא, רָזָא חֲדָא. בְּשַׁעֲתָא דְּיִשְׂרָאֵל קָא מְיַחֲדֵי יִחוּדָא בְּהַאי קְרָא, בְּרָזָא דְּכ\"ה אַתְוָון, דְּאִינּוּן שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד, וּבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, דְּאִינּוּן כ\"ד אַתְוָון, וִיכַוֵּין כָּל חַד בְּהוּ, כֻּלְּהוּ אַתְוָון מִתְחַבְּרָן כַּחֲדָא, וְסַלְּקִין לְחִבּוּרָא חַד, תֵּשַׁע וְאַרְבָּעִים תַּרְעִין, בְּרָזָא דְּיוֹבְלָא. וּכְדֵין אִצְטְרִיךְ לְסַלְּקָא וָעֶד, לָא יַתִּיר. וּכְדֵין אִתְפְּתָחוּ תַּרְעִין, וְחָשִׁיב קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא בַּר נָשׁ, כְּאִילּוּ קִיֵּים אוֹרַיְיתָא כֻּלָהּ, דְּאִיהִי אַתְיָא בְּמ\"ט פָּנִים בְּכֹלָּא.</p>\n<p>וְעַל דָּא אִצְטְרִיךְ לְכַוְּונָא רְעוּתָא בְּכ\"ה וּבְאַרְבַּע וְעֶשְׂרִין, לְסַלְּקָא לוֹן בִּרְעוּתָא דְּלִבָּא, בְּתֵשַׁע וְאַרְבְּעִין תַּרְעִין דְּקַאמְרָן, כֵּיוָן דְּאִתְכָּוַּון בְּהַאי, יִתְכַּוָּון בְּהַהוּא יִחוּדָא דְּאָמַר מַר, שְׁמַע יִשְׂרָאֵל וְגוֹ' בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, כְּלָלָא דְּכָל אוֹרַיְיתָא כֹּלָּא. זַכָּאָה חוּלָקֵיהּ מַאן דְּיִתְכַּוֵּון בְּהוּ, וַדַּאי כְּלָלָא אִיהוּ דְּכָל אוֹרַיְיתָא דְּעֵילָּא וְתַתָּא. וְדָא אִיהוּ רָזָא דְּאָדָם, שְׁלִימוּ דִּדְכַר וְנוּקְבָּא, וְרָזָא דְּכָל מְהֵימְנוּתָא. עֲד כָּאן.</p>\n<p><Nonei></i> רִבִּי אַבָּא שָׁלַח לֵיהּ לְרִבִּי שִׁמְעוֹן וְאָמַר לֵיהּ, הַאי דְּאוּקְמֵיהּ מַר בַּתְּפִלִּין דְּמָארֵי עָלְמָא, ד' פָּרְשִׁיָּין אִינּוּן קוּדְשָׁא דְּקוּדְשִׁין, שַׁפִּיר. מִשְׁכָא דְּעַל תְּפִילִּין, וְאִינּוּן רְצוּעִין אִקְרוּ קְדוּשָּׁה, אַסְמַכְתָּא מְנָלָן. שָׁלַח לֵיהּ (בראשית ג׳:כ״א) וַיַּעַשׂ יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ וְגוֹ', דַּיְיקָא וְהָכִי אוּקְמֵיהּ רַב הַמְנוּנָא סָבָא. וְאִלֵּין אִינּוּן דְּרֵישָׁא, וּדְרוֹעָא יָדְכָה בְּהֵ\"א, וְהָא אוֹקְמוּהָ.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, אִית מַאן דְּמַתְנֵי בְּהַאי גַּוְונָא, וְהָיָה דְּרוֹעָא שְׂמָאלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִקְרֵי גְּבוּרָה. אִי הָכִי לָא אִשְׁתַּאֲרָן בְּרֵישָׁא אֶלָּא תְּלַת. וְאִינּוּן אַרְבַּע. אֲבָל תְּרֵין רְתִיכִין קַדִּישִׁין אִינּוּן, דָּא אִתְקְשַׁר בְּלִבָּא, וְדָא אִתְקְשַׁר בְּמוֹחָא. וְלִבָּא וּמוֹחָא, אִתְקְשַׁר דָּא בְּדָא. וְזִוּוּגָא חַד לְהוּ, וְשַׁפִּיר קָאַמְרוּ חַבְרַיָּיא. וְהָיָה לְאוֹת עַל יָדְכָה, כְּמָה דְּאִתְּמַר, וְלָא אִקְרֵי אֶלָּא אוֹת.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּבַּר נָשׁ אַקְדִּים בְּפַלְגּוּת לֵילְיָא, וְקָם וְאִשְׁתָּדַּל בְּאוֹרַיְיתָא, עַד דְּנָהִיר צַפְרָא. בְּצַפְרָא אֲנָח תְּפִילִּין בְּרֵישֵׁיהּ, וּתְפִילִּין בִּרְשִׁימָא קַדִּישָׁא בִּדְרוֹעֵיהּ, וְאִתְעַטָּף בְּעִטּוּפָא דְּמִצְוָה, וְאָתֵי לְנָפְקָא מִתַּרְעָא דְּבֵיתֵיהּ. אִעְרַע בַּמְּזוּזָה, רְשִׁימָא דִּשְׁמָא קַדִּישָׁא בְּתַרְעָא דְּבֵיתֵיהּ. אַרְבַּע מַלְאָכִין קַדִּישִׁין מִזְדַוְּוגִין עִמֵּיהּ וְנָפְקִין עִמֵּיהּ מִתַּרְעָא דְּבֵיתֵיהּ, וְאוֹזְפֵי לֵיהּ לְבֵי כְּנִישְׁתָּא. וּמַכְרְזֵי קַמֵּיהּ, הָבוּ יְקָרָא לְדִיּוּקְנָא דְּמַלְכָּא קַדִּישָׁא, הָבוּ יְקָרָא לִבְרֵיהּ דְּמַלְכָּא, לְפַרְצוּפָא יְקָרָא דְּמַלְכָּא. רוּחָא קַדִּישָׁא שַׁרְיָא עָלֵיהּ, אַכְרִיז וְאָמַר (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>\n<p>כְּדֵין הַהוּא רוּחָא קַדִּישָׁא סַלְּקָא לְעֵילָּא, וְאַסְהִיד עָלֵיהּ קַמֵּי מַלְכָּא קַדִּישָׁא, כְּדֵין פָּקִיד מַלְכָּא עִלָּאָה, לְמִכְתַּב קַמֵּיהּ כָּל אִינּוּן בְּנֵי הֵיכָלֵיהּ, כָּל אִינּוּן דְּאִשְׁתְּמוֹדְעָן קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ט״ז) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי יְיָ' וּלְחוֹשְׁבֵי שְׁמוֹ. מַאי וּלְחוֹשְׁבֵי שְׁמוֹ. כְּמָה דְאַתְּ אָמֵר (שמות לה) (ס\"א חשב האפוד) וְחוֹשְׁבֵי מַחֲשָׁבוֹת, אִינּוּן דְּעַבְדִּין לִשְׁמֵיהּ, אוּמָנוּתָא בְּכֹלָּא, אוּמָנוּתָא דִּתְפִילִּין, בְּבָתֵּיהוֹן בִּרְצוּעֵיהוֹן וּכְתִיבַתְהוֹן. אוּמָנוּתָא דְּצִיצִית, בְּחוּטֵיהוֹן, בְּחוּטָא דִּתְכֶלְתָּא. אוּמָנוּתָא דִּמְזוּזָה. וְאִלֵּין אִינּוּן חוֹשְׁבֵי שְׁמוֹ. וּכְתִיב (שם) וְחוֹשְׁבֵי מַחֲשָׁבוֹת.</p>\n<p>וְלֹא עוֹד אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּבַּח בֵּיהּ, וּמַכְרִיז עָלֵיהּ בְּכֻלְּהוּ עָלְמִין, חָמוּ מַה בִּרְיָה עַבְדֵּית בְּעוֹלָמִי. וּמַאן דְּיֵיעוּל קַמֵּיהּ לְבֵי כְּנִישְׁתָּא, כַּד נָפִק מִתַּרְעֵיהּ, וְלָא תְּפִילִּין בְּרֵישֵׁיהּ וְצִיצִית בִּלְבוּשֵׁיהּ, וְאוֹמֵר (תהילים ה׳:ח׳) אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךָ בְּיִרְאָתֶךָ. קוּדְשָׁא בְּרִיךְ הוּא אָמַר, אָן הוּא מוֹרָאִי, הָא סָהִיד סַהֲדוּתָא דְּשִׁקְרָא.</p>\n<p>אָמַר רִבִּי יוֹסִי, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּהָכָא אָמַר אֱלֹהֵינוּ. (נ\"א אלהיך) דְּאָמַר רִבִּי שִׁמְעוֹן, מֹשֶׁה בְּדַרְגָּא עִלָּאָה יַתִּיר אִתְאֲחָד, עַל שְׁאַר נְבִיאֵי מְהֵימְנֵי. וְאָמַר רִבִּי שִׁמְעוֹן, אִלְמָלֵא הֲווֹ יַדְעֵי בְּנֵי נָשָׁא מִלִּין דְּאוֹרַיְיתָא, לִינְדְּעוּן דְּהָא לֵית שׁוּם מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין וְיַקִּירִין.</p>"],[9520012653,"<p>תָּא חֲזֵי כְּתִיב, (שמות י״ט:י״ט) מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְתָנֵינָן, מַאי בְקוֹל. בְּקוֹלוֹ שֶׁל מֹשֶׁה. וְשַׁפִּיר הוּא, בְּקוֹלוֹ שֶׁל מֹשֶׁה דַּיְיקָא, בְּהַהוּא קוֹל דְּאִיהוּ אָחִיד בֵּיהּ, עַל כָּל שְׁאַר נְבִיאִין. (מתמן משה אתזן על כלהו) וּבְגִין דְּאִיהוּ אִתְאֲחִיד עַל כֻּלְּהוּ, בְּהַהוּא קוֹל, דַּרְגָּא עִלָּאָה, הֲוָה אָמַר לְהוּ לְיִשְׂרָאֵל, יְיָ' אֱלֹהֶיךָ, אִיהוּ דַּרְגָּא דְּאִקְרֵי שְׁכִינְתָּא, דְּשַׁרְיָיא בְּגַוַויְיהוּ. זַכָּאָה חוּלָקֵיהּ.</p>\n<p>וְאָמַר רִבִּי שִׁמְעוֹן, תָּנֵינָן, קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים, מֹשֶׁה מִפִּי הַגְּבוּרָה אַמָרָן. וְשֶׁבְּמִשְׁנֵה תּוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אָמָרָן. מַאי מִפִּי עַצְמוֹ. וְכִי סַלְּקָא דַּעְתָּךְ דְּאֲפִילּוּ אָת זְעֵירָא בְּאוֹרַיְיתָא, מֹשֶׁה אָמַר לֵיהּ מִגַּרְמֵיהּ.</p>\n<p>אֶלָּא שַׁפִּיר הוּא, וְהָא אִתְּעַרְנָא, מֵעַצְמוֹ לָא תָּנֵינָן, אֶלָּא מִפִּי עַצְמוֹ. וּמַאי אִיהוּ. הַהוּא קוֹל דְּאִיהוּ אָחִיד בֵּיהּ. וְעַל דָּא, הַלָּלוּ מִפִּי הַגְּבוּרָה. וְהַלָּלוּ מִפִּי עַצְמוֹ. מִפִּי הַהוּא דַּרְגָּא דְּאִתְקְשַׁר בֵּיהּ עַל שְׁאַר נְבִיאֵי מְהֵימְנֵי. וְעַל דָּא, בְּכָל אֲתָר אֱלֹהֶיךָ, וְהָכָא אֱלֹהֵינוּ.</p>\n<p>תָּא חֲזֵי, כַּמָּה אִית לְהוּ לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא אוֹרְחַיְיהוּ, בְּגִין דְּיִשְׁתַּדְּלוּן בְּפֻלְחָנָא דְּמָארֵיהוֹן, וְיִזְכּוּן לְחַיֵּי עָלְמִין. תְּחוֹת כּוּרְסְיָיא דְּמַלְכָּא קַדִּישָׁא, אִית מָדוֹרִין עִלָּאִין. וּבְהַהוּא אֲתָר דְּכוּרְסְיָּיא, מְזוּזָה אִתְקְשַׁר, לְאִשְׁתְּזָבָא מִכַּמָּה מָארֵי דִּינִין, <Nonei></i> דִּזְמִינִין לְאַתְּעָרָא בְּהוּ בִּבְנֵי נָשָׁא, בְּהַהוּא עָלְמָא. כְּגַוְונָא דָּא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, וְיָהַב לְהוּ פִּקּוּדֵי אוֹרַיְיתָא, בְּגִין דְּיִשְׁתַּדְּלוּן בָּהּ וְיִשְׁתֵּזְבוּן בְּהַאי עָלְמָא, מִכַּמָּה מָארֵי דִּינִין, מִכַּמָּה מְקַטְרְגֵי, דְּאִזְדַּמְנוּן בְּהוּ בִּבְנֵי נָשָׁא בְּכָל יוֹמָא.</p>"],[9520012654,"<p>רִבִּי חִיָּיא אָמַר, הַאי מַאן דְּבָעֵי דְּיִסְתָּמַר אוֹרְחוֹי, לָא יֶעְבַּר עַל מַיָּיא דְּאוֹשְׁדִין קַמֵּי פִּתְחָא. בְּגִין דְּתַמָּן שָׁרִי חַד שִׁידָא, וְהוּא בֵּין תְּרֵין דָּשִׁין דְּפִתְחָא, וְאַנְפּוֹי לָקֳבְלֵיהּ דְּפִתְחָא, וְאִסְתָּכֵי כָּל מַה דְּעַבְדִין בְּבֵיתָא, וְלָא לִבְעֵי לֵיהּ לְאֱנוֹשׁ (לאיניש) דְּיִשְׁדֵּי מַיָּיא בֵּין תְּרֵי תַּרְעֵי. רִבִּי יִצְחָק אָמַר, מַיִין צְלִילָן לֵית לָן בָּהּ. וְהוּא דְּלָא יוֹשִׁיט לוֹן אֹרַח קְלָנָא. מַאי טַעֲמָא. בְּגִין דְּאִית לֵיהּ רְשׁוּ לְנַזְקָא. וְלָא עוֹד אֶלָּא דְּיֶהְדַּר רֵישֵׁיהּ לָקֳבְלֵי בֵּיתָא, וּבְכָל מַה דְּאִסְתְּכַל אִתְלַטְּיָיא.</p>\n<p>תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ, כְּחוּשְׁבָּן יְמֵי שַׁתָּא, אִית לֵיהּ שַׁמָּשִׁין, דְּהוּא שַׁלִּיט עָלַיְיהוּ, וְכֻלְּהוּ נָפְקִין עִם בַּר נָשׁ, כַּד נָפִק מִתַּרְעָא דְּבֵיתֵיהּ. אָמַר רִבִּי אֶלְעָזָר, כָּל דָּא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַטְרָא לוֹן לְיִשְׂרָאֵל, וְאַתְקִין שְׁמֵיהּ קַדִּישָׁא לְעֵילָּא, דְּאִיהוּ אוֹרַיְיתָא, וְאוֹרַיְיתָא כֹּלָּא חַד שְׁמָא קַדִּישָׁא אִיהוּ, וּמַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, אִשְׁתְּדַּל בִּשְׁמֵיהּ.</p>\n<p>תָּא חֲזֵי, בָּעֵי בַּר נָשׁ בְּפִתְחָא דְּבֵיתָא לְרַשְׁמָא שְׁמָא קַדִּישָׁא, דְּאִיהוּ מְהֵימְנוּתָא דְּכֹלָּא. דְּהָא בְּכָל אֲתָר דִּשְׁמָא קַדִּישָׁא אִשְׁתְּכַח, זִינִין בִּישִׁין לָא מִשְׁתַּכְּחֵי תַּמָּן, וְלָא יַכְלִין לְקַטְרְגָא לֵיהּ לְבַּר נָשׁ, כְּמָה דִּכְתִּיב, (תהילים צ״א:י׳) לֹא תְאוּנֶה אֵלֶיךָ רָעָה וְגוֹ'.</p>\n<p>(מזוזא אקרי). אֲתָר דְּפִתְחָא דְּבֵיתָא שַׁרְיָא, כְּגַוְונָא דִּלְעֵילָּא, אֲתָר דְּפִתְחָא דְּבֵיתָא עִלָּאָה שַׁרְיָא, מְזוּזָא אִקְרֵי. דְּהוּא תִּקּוּנָא דְּבֵיתָא, וּפִתְחָא דְּבֵיתָא. מֵהַהִיא מְזוּזָה עַרְקִין מָארֵי נִימּוּסִין, מָארֵי דְּדִינִין קַמֵּיהּ לָא מִשְׁתַּכְּחִין. וְקֳבֵל דָּא לְתַתָּא, כַּד בַּר נָשׁ אַתְקִין מְזוּזָה לְפִתְחָא דְּבֵיתָא, וְהַאי שְׁמָא קַדִּישָׁא רָשִׁים בְּאַתווֹי, הַאי בַּר נָשׁ אִתְעֲטָּר בְּעִטְרוֹי דְּמָארֵיהּ, וְלָא קְרָבִין לְפִתְחָא דְּבֵיתֵיהּ זִינִין בִּישִׁין, וְלָא מִשְׁתַּכְּחֵי תַּמָּן.</p>\n<p>רִבִּי אַבָּא הֲוָה אָתֵי מִלְּמֵחמֵי לְרַבִּי שִׁמְעוֹן, פָּגַע בֵּיהּ רִבִּי יִצְחָק, אָמַר לֵיהּ מֵאָן אָתֵי, מָארֵיהּ דִּנְהוֹרָא, גְּבָר דְּאִתְדַּבָּק בְּנוּרָא דְּאַכְלָא כָּל יוֹמָא, הָא נְהוֹרָא עִמֵּיהּ שָׁרֵי. אָמַר לֵיהּ, תָּנֵינָן דְּחִיּוּבָא עָלֵיהּ דְּבַּר נָשׁ, לְקַבְּלָא אַפֵּי שְׁכִינְתָּא, בְּכָל רֵישׁ יַרְחֵי וְשַׁבַּתֵּי. וּמַאן אִיהוּ. רַבֵּיהּ. כָּל שֶׁכֵּן בּוּצִינָא עִלָּאָה קַדִּישָׁא, דְּכָל בְּנֵי עָלְמָא בָּעָאן לְקַבְּלָא אַנְפּוֹי. אָמַר רִבִּי יִצְחָק, אַהֲדַרְנָא עִמָּךְ, וְאַקְבֵּל אַנְפֵּי שְׁכִינְתָּא, וְאַטְעַם מֵאִינּוּן מִלִּין עִלָּאִין, דְּאַטְעֲמַת קַמֵּיהּ.</p>"]]});
